package main

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"runtime/debug"
	"time"

	"github.com/entireio/go-nuts"
	"github.com/nats-io/nats.go"
	"go.opentelemetry.io/otel/attribute"
	otelcodes "go.opentelemetry.io/otel/codes"
	"go.opentelemetry.io/otel/trace"

	"github.com/entirehq/mirror-pipeline/internal/natslog"
	"github.com/entirehq/mirror-pipeline/pkg/donejobs"
	"github.com/entirehq/mirror-pipeline/pkg/failindex"
	"github.com/entirehq/mirror-pipeline/pkg/gitjobs"
	"github.com/entireio/go-nuts/natsmsg"
)

const (
	consumerFailureDelay = 30 * time.Second
	consumerMaxDeliver   = 10
	consumerAckWait      = 15 * time.Minute
	consumerBackoffInit  = 1 * time.Second
	consumerBackoffMax   = 30 * time.Second
	// consumerInProgressInterval paces in-progress ack extensions while a
	// long sync is running. Derived from consumerAckWait so any change to
	// the ack budget automatically widens the extension cadence; /3 gives
	// two extension attempts within one ack window before redelivery.
	consumerInProgressInterval = consumerAckWait / 3
	// defaultSyncTimeout bounds one sync attempt end-to-end (override via
	// ENTIRE_WORKER_SYNC_TIMEOUT; "0" disables). The git smart-HTTP client
	// has no timeout of its own, and the InProgress extender refreshes the
	// ack deadline for as long as sync runs — so without this budget a
	// black-holed connection (established, then silently dropped) wedges
	// the replica forever AND suppresses redelivery: the serial consume
	// loop never fetches again and the extender keeps the message owned.
	// Generous on purpose: a legitimate multi-GB initial clone must fit.
	defaultSyncTimeout = 30 * time.Minute
)

type repoSyncer interface {
	sync(ctx context.Context, req syncRequest) error
}

// ackableMsg is the subset of *nats.Msg the disposition logic uses to ack a
// message. A seam so the Term/Nak/Ack decisions are unit-testable without a
// live JetStream subscription (*nats.Msg satisfies it implicitly).
type ackableMsg interface {
	Ack(opts ...nats.AckOpt) error
	Term(opts ...nats.AckOpt) error
	NakWithDelay(delay time.Duration, opts ...nats.AckOpt) error
	Metadata() (*nats.MsgMetadata, error)
}

// failureIndex is the failure-index surface the consumer depends on. An
// interface so a test can inject a fake whose RecordFailure errors, locking the
// fail-open invariant — a KV write failure must Term (not Nak) and surface via
// record_failed{cause} (*failindex.Index satisfies it).
type failureIndex interface {
	RecordFailure(ulid string, fs failindex.FailedSync, seq uint64, now time.Time) (recorded bool, err error)
	ClearOnSuccess(ulid string, successSeq uint64) (bool, error)
}

// completionPublisher publishes a terminal mirror-completion (the mirror_done
// op on the in-cell repo_ops_v1 stream) so the co-located regional entire-core
// can flip mirror_repos.status (processing → ready|failed). An interface so the
// disposition logic stays unit-testable without a live JetStream, and so a
// nil publisher degrades to the pre-completion behaviour (*donejobs.Publisher
// satisfies it).
type completionPublisher interface {
	PublishCompletion(ctx context.Context, jurisdiction, cluster string, job donejobs.Job) error
}

type subscriptionConfig struct {
	subject string
	durable string
}

type consumer struct {
	js                  nats.JetStreamContext
	clusterID           string
	jurisdiction        string
	sourceClusterDomain string
	syncer              repoSyncer
	metrics             *workerMetrics
	// health drives the severity of subscribe/fetch failure logs: recoverable
	// interruptions log at warn until the loop goes too long without progress.
	health natslog.Health
	// failidx is the mirror-sync failure index (KV). nil when the bucket could
	// not be bound at startup — the record/clear helpers then degrade to the
	// pre-index behaviour (bare Term / no clear) so the worker still syncs.
	failidx failureIndex
	// donePub publishes terminal mirror-completion events (repo_ops_v1 mirror_done op).
	// nil when no publisher is wired (degrades to the pre-completion
	// behaviour: ack/term as before, entire-core never learns the outcome).
	donePub completionPublisher
	// syncTimeout bounds one sync attempt (see defaultSyncTimeout). <= 0
	// disables the budget.
	syncTimeout time.Duration
}

// mirrorConsumerDurable is the JetStream durable name the worker subscribes
// to. KEDA's nats-jetstream scaler targets the same name (the `consumer:`
// field in the mirror-worker ScaledObjects in fleet) so the autoscaling
// signal reflects exactly this worker's backlog.
func mirrorConsumerDurable(jurisdiction, clusterID string) string {
	return fmt.Sprintf("mirror-git-v1-%s-%s", jurisdiction, clusterID)
}

func (c *consumer) run(ctx context.Context) {
	c.runSubscription(ctx, subscriptionConfig{
		subject: fmt.Sprintf("%s%s.%s.>", gitjobs.SubjectPrefix, c.jurisdiction, c.clusterID),
		durable: mirrorConsumerDurable(c.jurisdiction, c.clusterID),
	})
}

func (c *consumer) runSubscription(ctx context.Context, cfg subscriptionConfig) {
	backoff := consumerBackoffInit

	for {
		sub, err := c.js.PullSubscribe(cfg.subject, cfg.durable, nats.ManualAck(),
			nats.AckWait(consumerAckWait),
			nats.MaxDeliver(consumerMaxDeliver),
		)
		if err != nil {
			c.health.SubscribeErr(ctx, "Failed to subscribe", err,
				slog.String("subject", cfg.subject),
				slog.String("durable", cfg.durable),
			)
			select {
			case <-ctx.Done():
				return
			case <-time.After(backoff):
				backoff = min(backoff*2, consumerBackoffMax)
				continue
			}
		}
		backoff = consumerBackoffInit
		slog.Info("Consumer subscribed", slog.String("durable", cfg.durable), slog.String("subject", cfg.subject))

		c.consumeLoop(ctx, sub)

		if ctx.Err() != nil {
			return
		}
	}
}

func (c *consumer) consumeLoop(ctx context.Context, sub *nats.Subscription) {
	for {
		if ctx.Err() != nil {
			return
		}
		msgs, err := sub.Fetch(1, nats.MaxWait(5*time.Second))
		if err != nil {
			if errors.Is(err, nats.ErrTimeout) {
				// An idle poll is progress: connected, stream merely quiet.
				c.health.Recovered()
				continue
			}
			if nuts.IsShutdownFetchErr(ctx, err) {
				// Connection drained/closed during shutdown — a clean exit,
				// not a fault (COR-923).
				return
			}
			c.health.Err(ctx, "Fetch error", err)
			return
		}
		c.health.Recovered()

		for _, msg := range msgs {
			c.handleMessage(ctx, msg)
		}
	}
}

func (c *consumer) handleMessage(ctx context.Context, msg *nats.Msg) {
	// Parent the consume span to the producer's trace when the publisher
	// injected a W3C traceparent header (pkg/natsmsg.Inject). When headers
	// are absent (older publishers, or the test /publish endpoint), Extract
	// is a no-op and the span starts a new trace.
	ctx = natsmsg.Extract(ctx, msg)

	ctx, span := Tracer().Start(ctx, "mirror.consume",
		trace.WithSpanKind(trace.SpanKindConsumer),
		trace.WithAttributes(
			attribute.String("messaging.system", "nats"),
			attribute.String("messaging.operation.type", "receive"),
			attribute.String("messaging.destination.name", msg.Subject),
		),
	)
	defer span.End()

	// A panic anywhere below (a nil deref in payload handling, a bug deep in
	// the git-sync stack on a pathological repo) must NOT unwind into the
	// consume goroutine: that crashes the process, and because the message was
	// never acked JetStream redelivers it — so every replica that picks it up
	// crashes in turn, turning one poison-pill job into a cluster-wide
	// crash-loop. Recover and dispose it as a transient failure instead.
	// Registered after span.End() so it runs first (LIFO) and can stamp the
	// span before it closes.
	defer func() {
		if r := recover(); r != nil {
			c.handlePanic(ctx, span, msg, r)
		}
	}()

	if meta, err := msg.Metadata(); err == nil {
		span.SetAttributes(
			attribute.Int64("messaging.nats.sequence", int64(meta.Sequence.Stream)),
			attribute.Int64("messaging.nats.delivery_count", int64(meta.NumDelivered)),
		)
	} else {
		slog.DebugContext(ctx, "msg.Metadata failed; span missing nats sequence attrs", slog.Any("error", err))
	}

	// Subject is the canonical routing key — placement, source kind, and op
	// live there, not in the body. A malformed subject means the broker
	// routed something we shouldn't have received; terminate without retry.
	parsed, err := gitjobs.ParseSubject(msg.Subject)
	if err != nil {
		span.RecordError(err)
		span.SetStatus(otelcodes.Error, "parse subject")
		span.SetAttributes(attribute.Bool("entire.message.terminated", true))
		slog.ErrorContext(ctx, "Bad subject, terminating", slog.Any("error", err))
		_ = msg.Term()
		return
	}
	span.SetAttributes(parsed.SpanAttrs()...)

	j, err := gitjobs.UnmarshalFor(parsed.SourceKind, msg.Data)
	if err != nil {
		span.RecordError(err)
		span.SetStatus(otelcodes.Error, "unmarshal job")
		span.SetAttributes(attribute.Bool("entire.message.terminated", true))
		slog.ErrorContext(ctx, "Bad job payload, terminating", slog.Any("error", err))
		// Terminate WITH the failure-index record + failed-completion publish,
		// not a bare Term: UnmarshalFor returns the decoded body alongside a
		// validation error, so a kind/body mismatch (e.g. a github-shaped body
		// on an entiredb subject) still carries the target ULID that keys the
		// record — the same terminal handling the pre-kind-aware code gave
		// these messages at the source-kind gate. recordTerminal and
		// publishFailed no-op safely on an empty ULID (pure JSON garbage).
		c.terminate(ctx, msg, j.Target.ULID, msg.Subject, msg.Data, failindex.ReasonValidation, failindex.SourceWorkerValidation, err)
		return
	}
	c.handleGitJob(ctx, span, msg, parsed, j)
}

// handlePanic disposes of a message whose handler panicked. It Naks (rather
// than Terms) so redelivery is bounded by consumerMaxDeliver and the existing
// MAX_DELIVERIES path + advisory backstop still record the eventual terminal
// failure into the index for re-kick: a transient cause recovers on a later
// delivery, and a deterministic one dead-ends — both WITHOUT crashing the
// process. The stack is logged once here (the recover site) so the poison-pill
// payload is diagnosable; the span carries entire.handler.panicked for queries.
func (c *consumer) handlePanic(ctx context.Context, span trace.Span, m ackableMsg, recovered any) {
	err := fmt.Errorf("panic recovered in mirror handler: %v", recovered)
	span.RecordError(err)
	span.SetStatus(otelcodes.Error, "handler panic")
	span.SetAttributes(attribute.Bool("entire.handler.panicked", true))
	slog.ErrorContext(ctx, "Recovered panic in mirror handler; naking message (bounded by MaxDeliver)",
		slog.Any("panic", recovered),
		slog.String("stack", string(debug.Stack())),
	)
	c.metrics.recordPanic(ctx)
	_ = m.NakWithDelay(consumerFailureDelay)
}

func (c *consumer) handleGitJob(ctx context.Context, span trace.Span, msg *nats.Msg, parsed gitjobs.ParsedSubject, j gitjobs.Job) {
	span.SetAttributes(j.SpanAttrs()...)
	logAttrs := append(parsed.LogAttrs(), j.LogAttrs()...)
	slog.LogAttrs(ctx, slog.LevelInfo, "Processing git job", logAttrs...)

	if parsed.Op != gitjobs.OpSyncRepo {
		err := permanentErr(fmt.Errorf("unsupported operation %q", parsed.Op))
		span.RecordError(err)
		span.SetStatus(otelcodes.Error, "unsupported operation")
		span.SetAttributes(
			attribute.Bool("entire.error.permanent", true),
			attribute.Bool("entire.message.terminated", true),
		)
		slog.ErrorContext(ctx, "Unsupported operation, terminating", slog.String("operation", string(parsed.Op)))
		c.terminate(ctx, msg, j.Target.ULID, msg.Subject, msg.Data, failindex.ReasonValidation, failindex.SourceWorkerValidation, err)
		return
	}

	var sreq syncRequest
	switch parsed.SourceKind {
	case gitjobs.SourceKindGithub:
		installationID, err := gitjobs.ParseGithubInstallationAuthRef(j.Source.AuthRef)
		if err != nil {
			err := permanentErr(err)
			span.RecordError(err)
			span.SetStatus(otelcodes.Error, "invalid git source auth ref")
			span.SetAttributes(
				attribute.Bool("entire.error.permanent", true),
				attribute.Bool("entire.message.terminated", true),
			)
			slog.ErrorContext(ctx, "Invalid git source auth ref, terminating", slog.Any("error", err))
			c.terminate(ctx, msg, j.Target.ULID, msg.Subject, msg.Data, failindex.ReasonValidation, failindex.SourceWorkerValidation, err)
			return
		}
		span.SetAttributes(attribute.Int64("entire.installation_id", installationID))
		sreq = syncRequest{
			SourceKind:     gitjobs.SourceKindGithub,
			SourceOwner:    j.Source.Owner,
			SourceRepo:     j.Source.Repo,
			InstallationID: installationID,
			TargetULID:     j.Target.ULID,
		}
	case gitjobs.SourceKindEntireDB:
		// Decode validation bounds the URL shape; admission here bounds where
		// the worker may present its client certificate. The environment-wide
		// domain is derived from Fleet's trusted local target configuration,
		// so sibling clusters are accepted without a per-cluster allowlist.
		sourceClusterParent, err := admitEntireDBSourceURL(j.Source.URL, c.sourceClusterDomain)
		if err != nil {
			err = permanentErr(fmt.Errorf("admit entiredb source: %w", err))
			span.RecordError(err)
			span.SetStatus(otelcodes.Error, "entiredb source outside allowed domain")
			span.SetAttributes(
				attribute.Bool("entire.error.permanent", true),
				attribute.Bool("entire.message.terminated", true),
			)
			slog.ErrorContext(ctx, "Entiredb source rejected, terminating", slog.Any("error", err))
			c.terminate(ctx, msg, j.Target.ULID, msg.Subject, msg.Data, failindex.ReasonValidation, failindex.SourceWorkerValidation, err)
			return
		}
		span.SetAttributes(attribute.String("entire.source_cluster_parent", sourceClusterParent))
		sreq = syncRequest{
			SourceKind:          gitjobs.SourceKindEntireDB,
			SourceURL:           j.Source.URL,
			SourceClusterParent: sourceClusterParent,
			TargetULID:          j.Target.ULID,
		}
	default:
		// UnmarshalFor already rejects unknown kinds, so this is defensive.
		err := permanentErr(fmt.Errorf("unsupported git source kind %q", parsed.SourceKind))
		span.RecordError(err)
		span.SetStatus(otelcodes.Error, "unsupported git source")
		span.SetAttributes(
			attribute.Bool("entire.error.permanent", true),
			attribute.Bool("entire.message.terminated", true),
		)
		slog.ErrorContext(ctx, "Unsupported git source, terminating", slog.String("source_kind", string(parsed.SourceKind)))
		c.terminate(ctx, msg, j.Target.ULID, msg.Subject, msg.Data, failindex.ReasonValidation, failindex.SourceWorkerValidation, err)
		return
	}

	// A single sync on a multi-GB repo regularly exceeds consumerAckWait, so
	// extend the ack deadline on a sub-AckWait cadence while sync runs. The
	// extender's lifetime is exactly the sync call: explicit stop right after
	// sync returns keeps it from overlapping with Ack/Term/Nak in
	// disposeResult (an InProgress racing an Ack would log a spurious warn),
	// and a deferred stop covers the panic path. stopExtender is idempotent,
	// so the two paths don't fight. We deliberately don't raise AckWait: if a
	// pod dies mid-job we still want redelivery within the configured window.
	stopExtender := startInProgressExtender(ctx, msg, consumerInProgressInterval)
	defer stopExtender()

	// Bound the attempt. git-sync is context-aware end to end (every HTTP
	// request is built with NewRequestWithContext), so the deadline aborts
	// in-flight transfers — which also stops the extender above, restoring
	// AckWait expiry as the backstop. A timeout classifies as transient →
	// Nak; a repo that exceeds the budget on every attempt exhausts
	// MaxDeliver and lands in the failure index (reason=max_deliveries).
	syncCtx := ctx
	if c.syncTimeout > 0 {
		var cancel context.CancelFunc
		syncCtx, cancel = context.WithTimeout(ctx, c.syncTimeout)
		defer cancel()
	}
	// Saturation + tail-latency instrumentation. syncStarted increments the
	// in-flight gauge and its deferred done() decrements it on every exit
	// (including a panic recovered upstream), keeping mirror.sync.active
	// balanced. elapsed is the wall-time around exactly the sync call; it is
	// threaded into disposeResult so mirror.sync.duration_seconds is tagged with
	// the real disposition (a slow ack vs a slow nak). Measured here, recorded
	// there, so the latency sample and the outcome label share one source.
	doneActive := c.metrics.syncStarted(ctx, c.jurisdiction)
	defer doneActive() // deferred so the decrement runs on every exit, including a sync panic recovered in handleMessage; otherwise the in-flight gauge leaks and biases utilization toward saturation
	start := time.Now()
	err := c.syncer.sync(syncCtx, sreq)
	elapsed := time.Since(start)
	stopExtender()
	if err != nil && errors.Is(syncCtx.Err(), context.DeadlineExceeded) && ctx.Err() == nil {
		// Our budget fired (not a process shutdown: the parent is still
		// alive). Wrap explicitly transient so the disposition can't be
		// swayed by however the aborted transfer's error happens to read,
		// and stamp the span so timed-out syncs are queryable.
		span.SetAttributes(attribute.Bool("entire.sync.deadline_exceeded", true))
		err = transientErr(fmt.Errorf("sync exceeded the %v budget: %w", c.syncTimeout, err))
	}

	// Tag concurrent-ref races so they stay queryable in traces even though
	// (below) they're deliberately not marked as span errors.
	if isConcurrentRefError(err) {
		span.SetAttributes(attribute.Bool("entire.sync.raced", true))
	}
	// Mark the span as an error only for genuine failures. Benign cases —
	// errSourceNoRefs (empty source, acked as a no-op) and a redelivering
	// concurrent-ref race — are excluded so they don't inflate the
	// mirror.consume APM error rate, matching their exclusion from the outcome
	// metric. See shouldMarkSpanError.
	if shouldMarkSpanError(err, isLastDelivery(msg)) {
		span.RecordError(err)
		span.SetStatus(otelcodes.Error, "sync failed")
		span.SetAttributes(attribute.Bool("entire.error.permanent", isPermanentError(err)))
	}
	// A re-kicked job (cmd/rekicker) carries the Mirror-Rekick header; on success
	// the clear is tagged cleared{via=rekick} vs via=normal. Header.Get only
	// exists on *nats.Msg, not the ackableMsg disposition seam, so read it here
	// and thread the flag down rather than widen the interface.
	viaRekick := msg.Header.Get(failindex.RekickHeader) != ""
	c.disposeResult(ctx, msg, err, string(parsed.SourceKind), j.Target.ULID, msg.Subject, msg.Data, viaRekick, elapsed)
}

// disposeResult applies the JetStream action for a sync result and records the
// outcome metrics. elapsed is the wall-time of the sync attempt (measured in
// handleGitJob); it is recorded on mirror.sync.duration_seconds tagged with the
// disposition resolved here, so the latency sample carries the real outcome.
func (c *consumer) disposeResult(ctx context.Context, m ackableMsg, err error, provider, ulid, subject string, payload []byte, viaRekick bool, elapsed time.Duration) {
	seq := streamSeq(m)
	switch classifyDisposition(err) {
	case dispositionAck:
		// Publish the ready completion BEFORE acking. entire-core flips
		// mirror_repos.status (processing → ready) off this event, and once we
		// ack the job leaves the work-queue stream and is never redelivered — so
		// a publish lost after the ack would strand the row in 'processing'
		// forever, hanging the CLI's status poll. publishReadyOrRetry holds the
		// ack until the publish lands (or gives up on the final delivery); see
		// its doc for the at-least-once rationale.
		if !c.publishReadyOrRetry(ctx, m, provider, ulid, elapsed) {
			return
		}
		c.metrics.recordSyncOutcome(ctx, provider, c.jurisdiction, outcomeAck, elapsed)
		_ = m.Ack()
		c.clearIndex(ctx, ulid, seq, viaRekick) // repo healed → drop any stale index entry
	case dispositionNoop:
		// Empty source: nothing to mirror, but the mirror IS clonable (an empty
		// repo is a valid clone target), so it's 'ready' to entire-core. Same
		// publish-before-ack discipline as the success path. Do NOT clear the
		// failure index here: a noop applied no refs and reconciled nothing (it
		// is deliberately not a ref-applying success — see last_success_unix), so
		// it must not prune a recorded terminal failure that may have left the
		// mirror inconsistent. Only a real sync (Ack) or a re-kick that ends in
		// one clears. A genuinely-emptied source self-heals on its next real
		// sync, or the entry ages out via the bucket ttl.
		if !c.publishReadyOrRetry(ctx, m, provider, ulid, elapsed) {
			return
		}
		c.metrics.recordSyncOutcome(ctx, provider, c.jurisdiction, outcomeNoop, elapsed)
		_ = m.Ack()
	case dispositionTerm:
		// Best-effort record, then Term regardless — fail open. recordTerminal
		// logs + counts record_failed{cause} on a KV write failure; we Term
		// either way rather than Nak, because the failure is permanent (re-running
		// the sync would be wasted work) and a KV outage must not wedge the
		// consumer. Recovery of a dropped record is owned by the record_failed
		// alert + L2 reconcile, not by holding the message.
		c.recordTerminal(ctx, ulid, subject, payload, seq, failindex.ReasonPermanent, failindex.SourceWorkerPermanent, err)
		slog.WarnContext(ctx, "Permanent sync error, terminating", slog.Any("error", err))
		c.publishFailed(ctx, ulid) // best-effort: tell entire-core the clone won't land
		c.metrics.recordSyncOutcome(ctx, provider, c.jurisdiction, outcomeTerm, elapsed)
		_ = m.Term()
	case dispositionNak:
		if isLastDelivery(m) {
			// Final delivery: JetStream won't redeliver past consumerMaxDeliver,
			// so this is terminal. Best-effort record (max_deliveries), then Term —
			// fail open (recordTerminal surfaces a write failure via record_failed).
			c.recordTerminal(ctx, ulid, subject, payload, seq, failindex.ReasonMaxDeliveries, failindex.SourceWorkerExhausted, err)
			slog.ErrorContext(ctx, "Sync failed; deliveries exhausted, terminating", slog.Any("error", err))
			c.publishFailed(ctx, ulid) // best-effort: clone exhausted retries, won't land
			c.metrics.recordSyncOutcome(ctx, provider, c.jurisdiction, outcomeTerm, elapsed)
			_ = m.Term()
			return
		}
		slog.ErrorContext(ctx, "Sync failed", slog.Any("error", err))
		c.metrics.recordSyncOutcome(ctx, provider, c.jurisdiction, outcomeNak, elapsed)
		_ = m.NakWithDelay(consumerFailureDelay)
	case dispositionRaced:
		// Target ref moved between this job's plan and its push — a second sync
		// of the same repo won the race (rapid webhooks, or a webhook
		// overlapping the rekicker). Redeliver like a nak so the next delivery
		// re-plans against the new tip and applies cleanly (usually a no-op,
		// since the winner already mirrored the same source state), but record
		// outcomeRaced + WARN so it stays out of the sync-failure alert's
		// nak+term numerator: it self-heals and pages no one.
		//
		// Final-delivery escalation is identical to the nak path for the failure
		// index + alert: if a repo somehow races every delivery to exhaustion the
		// contention is no longer benign, so we record terminal (max_deliveries)
		// and label outcome=term — that DOES reach the alert. Fail open on the
		// index write exactly like dispositionNak.
		//
		// But we deliberately do NOT publish a 'failed' completion here. A raced
		// error (ErrTargetRefMoved) means the target ref moved under us — i.e. a
		// CONCURRENT sync of the same ULID is racing us, and one of those is the
		// likely winner that publishes 'ready'. Emitting 'failed' would describe
		// contention as an unclonable mirror; entire-core's MarkReady would heal
		// it on the winner's event anyway, but skipping 'failed' avoids the
		// misleading transient flip entirely. If no sibling ever wins (pathological
		// — they can't all lose), status lingers at 'processing' and the failure
		// index/alert still fire.
		if isLastDelivery(m) {
			c.recordTerminal(ctx, ulid, subject, payload, seq, failindex.ReasonMaxDeliveries, failindex.SourceWorkerExhausted, err)
			slog.ErrorContext(ctx, "Sync kept racing on target ref; deliveries exhausted, terminating", slog.Any("error", err))
			c.metrics.recordSyncOutcome(ctx, provider, c.jurisdiction, outcomeTerm, elapsed)
			_ = m.Term()
			return
		}
		slog.WarnContext(ctx, "Sync raced on target ref; will retry", slog.Any("error", err))
		c.metrics.recordSyncOutcome(ctx, provider, c.jurisdiction, outcomeRaced, elapsed)
		_ = m.NakWithDelay(consumerFailureDelay)
	}
}

// publishReadyOrRetry publishes the StatusReady completion and reports whether
// the caller may proceed to Ack. It returns true when the publish lands (or
// when no publisher is wired, or there's no ULID to key on) — the ack is safe.
//
// On a publish failure it does NOT ack: the completion is the only signal
// entire-core gets that the clone finished, and acking would drop it for good.
// Instead it Naks (except on the final delivery), so JetStream redelivers, the
// next attempt re-runs the idempotent sync (a near-noop — refs already
// applied), and re-publishes. entire-core's status write is itself idempotent,
// so a duplicate ready is harmless. On the FINAL delivery it gives up and acks
// anyway (returns true): the sync genuinely succeeded, so terming + recording a
// max_deliveries "sync failure" would be a lie, and a Nak past MaxDeliver just
// dead-letters the job. The row stays 'processing' until a later sync (or a
// reconcile backstop) re-publishes — surfaced via mirror.done.published{result=error}.
func (c *consumer) publishReadyOrRetry(ctx context.Context, m ackableMsg, provider, ulid string, elapsed time.Duration) (proceed bool) {
	if c.donePub == nil || ulid == "" {
		return true
	}
	err := c.donePub.PublishCompletion(ctx, c.jurisdiction, c.clusterID, donejobs.Job{
		RepoULID: ulid,
		Status:   donejobs.StatusReady,
	})
	if err == nil {
		c.metrics.recordDonePublished(ctx, string(donejobs.StatusReady), true)
		return true
	}
	c.metrics.recordDonePublished(ctx, string(donejobs.StatusReady), false)
	if isLastDelivery(m) {
		slog.ErrorContext(ctx, "Failed to publish mirror completion on final delivery; acking anyway (sync succeeded, status left processing)",
			slog.String("target_ulid", ulid), slog.Any("error", err))
		return true
	}
	slog.ErrorContext(ctx, "Failed to publish mirror completion; naking to retry", slog.String("target_ulid", ulid), slog.Any("error", err))
	c.metrics.recordSyncOutcome(ctx, provider, c.jurisdiction, outcomeNak, elapsed)
	_ = m.NakWithDelay(consumerFailureDelay)
	return false
}

// publishFailed publishes the StatusFailed completion on a best-effort basis:
// any error is logged and counted, never escalated. The message is already
// being Term'd (a permanent or retry-exhausted failure), so re-running the
// doomed sync to retry the publish would be wasted work; a lost 'failed' just
// leaves entire-core's row in 'processing' until the CLI's poll times out
// client-side — degraded, not incorrect. Mirrors the fail-open discipline
// recordTerminal already uses for the KV index.
func (c *consumer) publishFailed(ctx context.Context, ulid string) {
	if c.donePub == nil || ulid == "" {
		return
	}
	err := c.donePub.PublishCompletion(ctx, c.jurisdiction, c.clusterID, donejobs.Job{
		RepoULID: ulid,
		Status:   donejobs.StatusFailed,
	})
	if err != nil {
		slog.ErrorContext(ctx, "Failed to publish mirror failed-completion (best-effort, terminating anyway)",
			slog.String("target_ulid", ulid), slog.Any("error", err))
		c.metrics.recordDonePublished(ctx, string(donejobs.StatusFailed), false)
		return
	}
	c.metrics.recordDonePublished(ctx, string(donejobs.StatusFailed), true)
}

// disposition is the JetStream action disposeResult takes for a sync result.
type disposition int

const (
	dispositionAck   disposition = iota // success → Ack
	dispositionNoop                     // benign empty-source no-op → Ack
	dispositionTerm                     // permanent failure → Term (no redelivery)
	dispositionNak                      // transient failure → Nak (redeliver)
	dispositionRaced                    // benign concurrent-ref miss → Nak (redeliver), but counted as outcomeRaced not outcomeNak
)

// classifyDisposition maps a sync() result to its JetStream disposition. Pure
// (no IO) so the ack/noop/term/nak decision is unit-testable independent of a
// live subscription; disposeResult owns the side effects.
func classifyDisposition(err error) disposition {
	switch {
	case err == nil:
		return dispositionAck
	case errors.Is(err, errSourceNoRefs):
		return dispositionNoop
	case isPermanentError(err):
		return dispositionTerm
	case isConcurrentRefError(err):
		// Checked after isPermanentError so a 4xx that happens to echo a
		// concurrent-ref phrase still terminates; concurrent-ref errors are
		// never marked permanent, so this only ever reclassifies the transient
		// (would-be-nak) tail.
		return dispositionRaced
	default:
		return dispositionNak
	}
}

func isPermanentError(err error) bool {
	var se *syncError
	if errors.As(err, &se) {
		return se.permanent
	}
	return false
}

// streamSeq returns the message's JetStream stream sequence, or 0 if metadata
// is unavailable (e.g. a synthetic test message). Used as the failure-index
// dedup token and the clear-on-success ordering guard.
func streamSeq(msg ackableMsg) uint64 {
	if meta, err := msg.Metadata(); err == nil {
		return meta.Sequence.Stream
	}
	return 0
}

// isLastDelivery reports whether this is the final delivery before JetStream
// stops redelivering (NumDelivered has reached consumerMaxDeliver).
func isLastDelivery(msg ackableMsg) bool {
	if meta, err := msg.Metadata(); err == nil {
		return meta.NumDelivered >= consumerMaxDeliver
	}
	return false
}

// recordTerminal makes a BEST-EFFORT write of a terminal failure to the KV
// index. It never gates the caller's disposal: on a KV write failure it fails
// open — logs and increments record_failed{cause}, and the caller Terms the
// message anyway rather than Nak-ing. A KV outage must not wedge the consumer or
// burn re-sync retries (the record-failure paths are permanent/validation/
// exhausted, where a re-sync is wasted or moot). Recovery of a dropped record is
// owned by the record_failed alert and the L2 reconcile, not by holding the
// message.
func (c *consumer) recordTerminal(ctx context.Context, ulid, subject string, payload []byte, seq uint64, reason failindex.FailureReason, source string, cause error) {
	if c.failidx == nil {
		// Index unbound — cannot capture this terminal failure. Surface it
		// (depth/recorded stay flat otherwise); the caller Terms regardless.
		c.metrics.recordIndexUnavailable(ctx, failedIndexCauseUnbound)
		return
	}
	if ulid == "" {
		// Reachable: a payload that fails json decoding entirely carries no
		// target ULID to key a record on. Nothing to capture.
		return
	}
	fs := failindex.FailedSync{
		Subject:   subject,
		Payload:   payload,
		Reason:    reason,
		Source:    source,
		LastError: truncateError(cause),
	}
	recorded, err := c.failidx.RecordFailure(ulid, fs, seq, time.Now())
	if err != nil {
		// Fail open: log + metric, but the caller still Terms (see doc comment).
		slog.ErrorContext(ctx, "Failed to record terminal failure to index; terminating anyway (fail open)",
			slog.String("target_ulid", ulid), slog.String("reason", string(reason)), slog.Any("error", err))
		c.metrics.recordIndexUnavailable(ctx, failedIndexCauseWriteError)
		return
	}
	// Only count a genuine record — a dedup/reorder no-op (recorded=false) means
	// the failure was already captured, so counting it would inflate recorded
	// on a redelivery or the in-process/advisory pair.
	if recorded {
		c.metrics.recordIndexed(ctx, string(reason))
	}
}

// terminate records a terminal failure (best-effort) then Terms. Used by the
// pre-sync validation rejects, which carry no sync-outcome metric. These are
// permanent failures of a well-formed job (unsupported op/source kind, bad
// auth ref) — the clone will never land — so publish 'failed' best-effort so
// entire-core flips mirror_repos.status off 'processing' rather than the CLI
// poll hanging until timeout.
func (c *consumer) terminate(ctx context.Context, m ackableMsg, ulid, subject string, payload []byte, reason failindex.FailureReason, source string, cause error) {
	c.recordTerminal(ctx, ulid, subject, payload, streamSeq(m), reason, source, cause)
	c.publishFailed(ctx, ulid)
	_ = m.Term()
}

// clearIndex removes the repo's failure-index entry after a successful sync.
// Best-effort: a failure here is logged but never fails the sync (it already
// succeeded; a stale entry self-heals on the next success or re-kick). viaRekick
// tags the cleared metric so an operator can tell re-kicker-driven recoveries
// (cleared{via=rekick}) from organic ones (via=normal) — the "are re-kicks
// healing repos?" signal.
func (c *consumer) clearIndex(ctx context.Context, ulid string, seq uint64, viaRekick bool) {
	if c.failidx == nil || ulid == "" {
		return
	}
	cleared, err := c.failidx.ClearOnSuccess(ulid, seq)
	if err != nil {
		slog.WarnContext(ctx, "Failed to clear failure index after success",
			slog.String("target_ulid", ulid), slog.Any("error", err))
		return
	}
	if cleared {
		via := clearedViaNormal
		if viaRekick {
			via = clearedViaRekick
		}
		c.metrics.recordCleared(ctx, via)
	}
}

// truncateError renders an error for the index, capped so a pathological message
// can't bloat the KV value.
func truncateError(err error) string {
	if err == nil {
		return ""
	}
	const max = 1024
	s := err.Error()
	if len(s) > max {
		return s[:max]
	}
	return s
}

// inProgressMsg is the subset of *nats.Msg used by the in-progress extender.
// A tiny interface seam so the loop is unit-testable without a live JetStream
// subscription. Signature mirrors *nats.Msg.InProgress (variadic AckOpt) so
// the concrete type satisfies the interface implicitly.
type inProgressMsg interface {
	InProgress(opts ...nats.AckOpt) error
}

// startInProgressExtender periodically calls msg.InProgress() to push back the
// JetStream redelivery deadline while a long-running operation (a git sync)
// is still in flight. Returns a stop function that cancels the loop and blocks
// until the goroutine has exited — so a defer-stop won't leak the goroutine.
//
// InProgress() errors are logged and swallowed: a transient extend failure
// shouldn't kill an otherwise healthy job. Worst case the sync exceeds
// AckWait without a successful extend and JetStream redelivers — the same
// redelivery path that already exists today.
func startInProgressExtender(ctx context.Context, msg inProgressMsg, interval time.Duration) (stop func()) {
	ctx, cancel := context.WithCancel(ctx)
	done := make(chan struct{})
	go func() {
		defer close(done)
		ticker := time.NewTicker(interval)
		defer ticker.Stop()
		for {
			select {
			case <-ctx.Done():
				return
			case <-ticker.C:
				if err := msg.InProgress(); err != nil {
					slog.WarnContext(ctx, "InProgress extend failed", slog.Any("error", err))
				}
			}
		}
	}()
	return func() {
		cancel()
		<-done
	}
}

package main

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"net/http"
	"runtime/debug"
	"strings"
	"sync/atomic"
	"time"

	"github.com/entireio/go-nuts"
	"github.com/nats-io/nats.go"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	otelcodes "go.opentelemetry.io/otel/codes"
	"go.opentelemetry.io/otel/trace"

	"github.com/entirehq/mirror-pipeline/internal/natslog"
	"github.com/entirehq/mirror-pipeline/pkg/webhookdlq"
	"github.com/entirehq/mirror-pipeline/pkg/webhookevents"
	"github.com/entireio/go-nuts/natsmsg"
)

const (
	consumerBackoffInit = 1 * time.Second
	consumerBackoffMax  = 30 * time.Second

	// consumerFailureDelay is the flat delay between redeliveries on a transient
	// failure (network error or 5xx), requested explicitly via msg.NakWithDelay
	// (a bare Nak() does NOT honor a delay — the server redelivers immediately).
	// Matches cmd/fanout: a short, fixed in-stream retry rather than an
	// escalating backoff. The DLQ captures the delivery on MaxDeliver exhaustion
	// for replay once entire-web recovers.
	consumerFailureDelay = 30 * time.Second

	// consumerMaxDeliver bounds redelivery: first attempt + 7 retries. Kept at 8
	// (the value the live durable was created with) so this change reconciles onto
	// the existing JetStream consumer without a delete-and-recreate: the client's
	// checkConfig rejects a MaxDeliver mismatch, and dropping nats.BackOff is
	// tolerated (BackOff is not part of that comparison).
	consumerMaxDeliver = 8

	// consumerAckWait is the redelivery backstop when a pod dies mid-dispatch
	// without responding (no Ack/Nak/Term). The forward POST is fast, so a short
	// window is safe. No nats.BackOff is set, so this is a free choice — not
	// clamped to a schedule.
	consumerAckWait = 30 * time.Second

	// consumerInactiveThreshold lets the SERVER reap this durable after 72h
	// without a pull request. webhooks_github_v1 is interest-retention: an
	// abandoned durable pins every subsequent delivery for ALL consumers
	// until the stream's maxAge/maxBytes wall — the 2026-06-01 incident.
	// 72h sits under the stream's 96h maxAge; an app deliberately down
	// longer loses its cursor and re-consumes what is still retained on
	// return. Reconciled onto the existing durable in run() — the client's
	// checkConfig does not compare this field, so PullSubscribe alone would
	// silently leave the live consumer without it.
	consumerInactiveThreshold = 72 * time.Hour
)

const tracerName = "webhook-forwarder"

// githubSignatureHeader is the HMAC header GitHub sends and webhook-ingest both
// verifies (rejecting unsigned deliveries with 403) and replays verbatim into the
// envelope (cmd/webhook-ingest/forward.go). Its presence therefore marks a genuine
// GitHub-originated delivery; an envelope without it was published straight onto
// webhooks_github_v1 by another producer and is not forwardable to entire-web.
const githubSignatureHeader = "X-Hub-Signature-256"

type forwarder struct {
	js        nats.JetStreamContext
	client    *http.Client
	metrics   *forwarderMetrics
	targetURL string
	durable   string
	subject   string
	// health drives the severity of subscribe/fetch failure logs: recoverable
	// interruptions log at warn until the loop goes too long without progress.
	health natslog.Health
	// dlq captures deliveries this forwarder dead-letters (Term on a permanent
	// reject, or MaxDeliver-exhaustion on a sustained entire-web outage) so a
	// non-reconstructible webhook isn't lost. nil disables capture (behavior then
	// identical to before) — wired only when ENTIRE_WEBHOOK_DLQ_ENABLED is set, so
	// this ships ahead of the fleet stream + PUBLISH grant.
	dlq *webhookdlq.Publisher

	// subscribed tracks whether the forwarder currently holds a live JetStream
	// pull subscription. /readyz consults it so a pod that can dial NATS but
	// cannot PullSubscribe (a consumer-config mismatch, a perm reject) is reported
	// NotReady instead of silently forwarding nothing. Mirrors cmd/fanout.
	subscribed atomic.Bool
}

// Ready reports whether the forwarder currently holds a live JetStream pull
// subscription. Cleared during the backoff window between failed subscribes.
func (f *forwarder) Ready() bool {
	return f.subscribed.Load()
}

// ensureInactiveThreshold reconciles consumerInactiveThreshold onto an
// already-existing durable before the subscribe — PullSubscribe binds to an
// existing consumer and silently ignores the requested InactiveThreshold
// (checkConfig does not compare it), so without this the live fleet would
// never pick it up. Mirrors fanoutengine.(*Consumer).ensureInactiveThreshold.
// Best-effort: on any error the subscribe proceeds and the next run loop
// iteration retries.
func (f *forwarder) ensureInactiveThreshold() {
	info, err := f.js.ConsumerInfo(webhookevents.StreamName, f.durable)
	if err != nil {
		if !errors.Is(err, nats.ErrConsumerNotFound) && !errors.Is(err, nats.ErrStreamNotFound) {
			slog.Warn("InactiveThreshold reconcile: consumer lookup failed; proceeding without update",
				slog.String("durable", f.durable), slog.Any("error", err))
		}
		return
	}
	if info.Config.InactiveThreshold == consumerInactiveThreshold {
		return
	}
	updated := info.Config
	updated.InactiveThreshold = consumerInactiveThreshold
	if _, err := f.js.UpdateConsumer(webhookevents.StreamName, &updated); err != nil {
		slog.Warn("InactiveThreshold reconcile: consumer update failed; proceeding without update",
			slog.String("durable", f.durable), slog.Any("error", err))
		return
	}
	slog.Info("InactiveThreshold reconciled onto existing durable",
		slog.String("durable", f.durable), slog.Duration("inactive_threshold", consumerInactiveThreshold))
}

func (f *forwarder) run(ctx context.Context) {
	backoff := consumerBackoffInit
	for {
		f.subscribed.Store(false)
		f.ensureInactiveThreshold()
		sub, err := f.js.PullSubscribe(f.subject, f.durable,
			nats.ManualAck(),
			nats.AckWait(consumerAckWait),
			nats.MaxDeliver(consumerMaxDeliver),
			nats.InactiveThreshold(consumerInactiveThreshold),
		)
		if err != nil {
			f.health.SubscribeErr(ctx, "Subscribe failed", err,
				slog.String("subject", f.subject),
				slog.String("durable", f.durable),
			)
			select {
			case <-ctx.Done():
				return
			case <-time.After(backoff):
				backoff = minDuration(backoff*2, consumerBackoffMax)
				continue
			}
		}
		backoff = consumerBackoffInit
		f.subscribed.Store(true)
		slog.Info("Subscribed", slog.String("subject", f.subject), slog.String("durable", f.durable))

		f.consumeLoop(ctx, sub)
		f.subscribed.Store(false)

		if ctx.Err() != nil {
			return
		}
	}
}

func (f *forwarder) consumeLoop(ctx context.Context, sub *nats.Subscription) {
	for {
		if ctx.Err() != nil {
			return
		}
		msgs, err := sub.Fetch(1, nats.MaxWait(5*time.Second))
		if err != nil {
			if errors.Is(err, nats.ErrTimeout) {
				// An idle poll is progress: connected, stream merely quiet.
				f.health.Recovered()
				continue
			}
			if nuts.IsShutdownFetchErr(ctx, err) {
				return
			}
			f.health.Err(ctx, "Fetch error", err)
			return
		}
		f.health.Recovered()
		for _, msg := range msgs {
			f.handleMessage(ctx, msg)
		}
	}
}

func (f *forwarder) handleMessage(ctx context.Context, msg *nats.Msg) {
	ctx = natsmsg.Extract(ctx, msg)
	ctx, span := otel.Tracer(tracerName).Start(ctx, "webhook.forward.dispatch",
		trace.WithSpanKind(trace.SpanKindConsumer),
		trace.WithAttributes(
			attribute.String("messaging.system", "nats"),
			attribute.String("messaging.operation.type", "receive"),
			attribute.String("messaging.destination.name", msg.Subject),
		),
	)
	defer span.End()

	if meta, err := msg.Metadata(); err == nil {
		span.SetAttributes(
			attribute.Int64("messaging.nats.sequence", int64(meta.Sequence.Stream)),
			attribute.Int64("messaging.nats.delivery_count", int64(meta.NumDelivered)),
		)
	}

	f.dispatch(ctx, span, msg)
}

// ackableMsg is the disposition subset of *nats.Msg the panic handler needs; a
// seam so handlePanic is unit-testable without a live JetStream subscription.
type ackableMsg interface {
	Ack(opts ...nats.AckOpt) error
	Nak(opts ...nats.AckOpt) error
	NakWithDelay(delay time.Duration, opts ...nats.AckOpt) error
	Term(opts ...nats.AckOpt) error
}

// handlePanic disposes of a delivery whose handler panicked. It Naks (not
// Terms) so the only durable copy of the webhook isn't permanently dropped on a
// first panic: redelivery is bounded by MaxDeliver, so a transient cause recovers
// on a later delivery and a deterministic one ages out of the stream — both
// WITHOUT crashing the process. It Naks WITH a delay (consumerFailureDelay): a
// bare Nak() would redeliver immediately and burn through MaxDeliver in
// milliseconds across replicas. Asymmetry with the transient path, by design: a
// panic on the FINAL delivery is Nak'd and dropped at MaxDeliver with NO DLQ
// capture — a panic is a deterministic code bug, not a recoverable webhook, so
// replay can't fix it. The stack is logged once here so the poison-pill payload
// is still diagnosable; the span carries entire.handler.panicked for queries.
func (f *forwarder) handlePanic(ctx context.Context, span trace.Span, msg ackableMsg, recovered any) {
	err := fmt.Errorf("panic recovered in forwarder handler: %v", recovered)
	span.RecordError(err)
	span.SetStatus(otelcodes.Error, "handler panic")
	span.SetAttributes(attribute.Bool("entire.handler.panicked", true))
	slog.ErrorContext(ctx, "Recovered panic in forwarder handler; naking delivery (bounded by MaxDeliver)",
		slog.Any("panic", recovered),
		slog.String("stack", string(debug.Stack())),
	)
	f.metrics.recordPanic(ctx)
	_ = msg.NakWithDelay(consumerFailureDelay)
}

// dispatch is the per-message handler. It unmarshals, POSTs to entire-web,
// and ack/nak/term-s based on the response. Exposed for testing.
func (f *forwarder) dispatch(ctx context.Context, span trace.Span, msg *nats.Msg) {
	// A panic here (a nil deref, a bug in the HTTP path on a pathological body)
	// must NOT unwind into the consume goroutine: that crashes the process, and
	// because the message was never acked JetStream redelivers it — so every
	// replica that picks it up crashes in turn, turning one poison-pill delivery
	// into a cluster-wide crash-loop. Recover and Nak instead.
	defer func() {
		if r := recover(); r != nil {
			f.handlePanic(ctx, span, msg, r)
		}
	}()

	forwarded, err := webhookevents.Unmarshal(msg.Data)
	if err != nil {
		// Malformed payload — broker routed something we cannot interpret.
		// Terminate without redelivery; the dropped message is searchable in
		// Honeycomb via the span error.
		span.RecordError(err)
		span.SetStatus(otelcodes.Error, "unmarshal forwarded webhook")
		span.SetAttributes(attribute.Bool("entire.message.terminated", true))
		slog.ErrorContext(ctx, "Bad forwarded webhook, terminating", slog.Any("error", err))
		f.deadLetter(ctx, span, webhookdlq.ReasonBadEnvelope, msg, nil, numDelivered(msg), err)
		f.metrics.recordForward(ctx, eventUnknown, forwardOutcomeTerm, forwardReasonBadEnvelope)
		_ = msg.Term()
		return
	}
	span.SetAttributes(
		attribute.String("github.delivery_id", forwarded.DeliveryID),
		attribute.String("github.event", forwarded.Event),
	)

	// A well-formed envelope with no X-Hub-Signature-256 is not a GitHub delivery:
	// ingest only publishes deliveries whose signature it verified, and replays that
	// header verbatim. An unsigned envelope was published straight onto the stream by
	// another producer (e.g. entire-core's "mirror resync", which re-triggers fanout
	// with a stub push). The sibling fanout consumer handles those; forwarding one to
	// entire-web only earns a guaranteed 4xx that dead-letters as noise. Ack without
	// forwarding — it is not a drop (nothing was ever meant for entire-web here, so
	// there is nothing to preserve or replay).
	if !hasGitHubSignature(forwarded.Headers) {
		span.SetAttributes(attribute.Bool("entire.forward.skipped", true))
		slog.InfoContext(ctx, "Skipping unsigned (non-GitHub) delivery; not forwarding",
			slog.String("delivery_id", forwarded.DeliveryID),
			slog.String("event", forwarded.Event))
		f.metrics.recordForward(ctx, forwarded.Event, forwardOutcomeSkip, forwardReasonUnsigned)
		_ = msg.Ack()
		return
	}

	deliveries := numDelivered(msg)

	status, err := f.forward(ctx, forwarded)
	if err != nil {
		span.RecordError(err)
		span.SetStatus(otelcodes.Error, "forward request")
		f.nakOrDeadLetter(ctx, span, msg, forwarded, deliveries, forwardReasonNetwork, err)
		return
	}
	span.SetAttributes(attribute.Int("http.response.status_code", status))

	switch {
	case status >= 200 && status < 300:
		f.metrics.recordForward(ctx, forwarded.Event, forwardOutcomeAck, "")
		_ = msg.Ack()
		slog.InfoContext(ctx, "Forwarded",
			slog.String("delivery_id", forwarded.DeliveryID),
			slog.String("event", forwarded.Event),
			slog.Int("http.status_code", status))
	case status == http.StatusUnauthorized, status == http.StatusForbidden:
		// Auth / authz problem — entire-web rejected the request (e.g. the
		// shared webhook secret drifted, or its request gating kicked in).
		// Either way it's a config issue; retrying without operator action
		// just burns deliveries. Dead-letter so the delivery survives the
		// config fix for replay.
		span.SetStatus(otelcodes.Error, "auth rejected")
		span.SetAttributes(attribute.Bool("entire.message.terminated", true))
		slog.ErrorContext(ctx, "Forward auth rejected; terminating",
			slog.String("delivery_id", forwarded.DeliveryID),
			slog.Int("http.status_code", status))
		f.deadLetter(ctx, span, webhookdlq.ReasonAuth, msg, &forwarded, deliveries, fmt.Errorf("entire-web returned %d", status))
		f.metrics.recordForward(ctx, forwarded.Event, forwardOutcomeTerm, forwardReasonAuth)
		_ = msg.Term()
	case status >= 400 && status < 500:
		// Other 4xx — entire-web rejected the body. Retry won't fix it, but
		// preserve it for inspection (the body may reveal why entire-web 4xx'd).
		span.SetStatus(otelcodes.Error, fmt.Sprintf("client error %d", status))
		span.SetAttributes(attribute.Bool("entire.message.terminated", true))
		slog.ErrorContext(ctx, "Forward rejected with 4xx; terminating",
			slog.String("delivery_id", forwarded.DeliveryID),
			slog.Int("http.status_code", status))
		f.deadLetter(ctx, span, webhookdlq.ReasonClientError, msg, &forwarded, deliveries, fmt.Errorf("entire-web returned %d", status))
		f.metrics.recordForward(ctx, forwarded.Event, forwardOutcomeTerm, forwardReasonClientError)
		_ = msg.Term()
	default:
		// 5xx or unexpected status — transient on entire-web's side.
		span.SetStatus(otelcodes.Error, fmt.Sprintf("server error %d", status))
		f.nakOrDeadLetter(ctx, span, msg, forwarded, deliveries, forwardReasonServerError, fmt.Errorf("entire-web returned %d", status))
	}
}

// nakOrDeadLetter disposes a transient forward failure (network error or 5xx).
// Normally it NakWithDelay(consumerFailureDelay) for JetStream redelivery on a
// flat delay (a bare Nak would redeliver immediately). On the FINAL delivery a
// Nak is dropped silently at MaxDeliver, so — when DLQ capture is enabled — it
// dead-letters the webhook and Terms instead, preserving the only copy for replay
// once entire-web recovers. reason is the transient class for the Nak metric
// (network|server_error). deliveries is threaded in (rather than read from msg
// here) so the decision is unit-testable without a live JetStream subscription,
// matching the forwarder's existing test seams.
func (f *forwarder) nakOrDeadLetter(ctx context.Context, span trace.Span, msg *nats.Msg, fw webhookevents.ForwardedWebhook, deliveries int, reason string, cause error) {
	if f.dlq != nil && deliveries >= consumerMaxDeliver {
		slog.ErrorContext(ctx, "Forward failed; deliveries exhausted, dead-lettering",
			slog.String("delivery_id", fw.DeliveryID), slog.String("event", fw.Event), slog.Any("error", cause))
		f.deadLetter(ctx, span, webhookdlq.ReasonMaxDeliveries, msg, &fw, deliveries, cause)
		span.SetAttributes(attribute.Bool("entire.message.terminated", true))
		f.metrics.recordForward(ctx, fw.Event, forwardOutcomeTerm, forwardReasonExhausted)
		_ = msg.Term()
		return
	}
	slog.WarnContext(ctx, "Forward failed; will redeliver",
		slog.String("delivery_id", fw.DeliveryID), slog.String("event", fw.Event),
		slog.Int("delivery", deliveries), slog.Duration("redeliver_in", consumerFailureDelay), slog.Any("error", cause))
	f.metrics.recordForward(ctx, fw.Event, forwardOutcomeNak, reason)
	_ = msg.NakWithDelay(consumerFailureDelay)
}

// deadLetter best-effort captures a dead-lettered delivery to the DLQ. No-op
// when capture is disabled (f.dlq == nil). On a publish failure it fails open —
// logs + a span event, and the caller Terms anyway — because the failure is
// permanent (replay can't fix the cause) or the deliveries are exhausted, so
// holding the message only re-runs doomed work. The drop-with-no-copy is
// surfaced by webhook.dlq.published{outcome=error}. fw is nil for a delivery
// whose envelope didn't parse (the raw bytes are still preserved for triage).
func (f *forwarder) deadLetter(ctx context.Context, span trace.Span, reason string, msg *nats.Msg, fw *webhookevents.ForwardedWebhook, deliveries int, cause error) {
	if f.dlq == nil {
		return
	}
	dl := webhookdlq.DeadLetter{
		Source:          webhookdlq.SourceForwarder,
		Reason:          reason,
		OriginalSubject: msg.Subject,
		Envelope:        msg.Data,
		Deliveries:      deliveries,
		DeadLetteredAt:  time.Now(),
	}
	if cause != nil {
		dl.LastError = cause.Error()
	}
	if fw != nil {
		dl.DeliveryID = fw.DeliveryID
		dl.Event = fw.Event
	}
	if err := f.dlq.Publish(ctx, dl); err != nil {
		span.AddEvent("webhook.dlq.publish_failed")
		slog.WarnContext(ctx, "Failed to capture dead-lettered webhook; terminating anyway (fail open)",
			slog.String("reason", reason), slog.Any("error", err))
	}
}

// hasGitHubSignature reports whether the forwarded envelope carries a non-empty
// X-Hub-Signature-256 header — the marker of a genuine GitHub delivery (see the
// header constant). Case-insensitive: the envelope's header-map key is
// producer-set and not guaranteed to be canonicalized. A nil/empty map returns
// false, so a directly-published headerless event is treated as unsigned.
func hasGitHubSignature(headers map[string]string) bool {
	for k, v := range headers {
		if v != "" && strings.EqualFold(k, githubSignatureHeader) {
			return true
		}
	}
	return false
}

// numDelivered reports the JetStream delivery count, or 0 if metadata is
// unavailable (e.g. a synthetic test message with no JetStream reply subject).
func numDelivered(msg *nats.Msg) int {
	if meta, err := msg.Metadata(); err == nil {
		return int(meta.NumDelivered)
	}
	return 0
}

// forward issues the POST to entire-web. Returns the response status code.
// A non-nil error means the request never produced a response (network /
// timeout) and the caller should treat it as transient.
func (f *forwarder) forward(ctx context.Context, w webhookevents.ForwardedWebhook) (int, error) {
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, f.targetURL, bytes.NewReader(w.Body))
	if err != nil {
		return 0, fmt.Errorf("build request: %w", err)
	}
	// Replay GH headers verbatim — including X-Hub-Signature-256 — so the
	// downstream (entire-web) verifies HMAC against the same secret it has
	// always used. mirror-pipeline does not add its own auth; the request is
	// indistinguishable from a direct GitHub delivery.
	for k, v := range w.Headers {
		req.Header.Set(k, v)
	}
	if req.Header.Get("Content-Type") == "" {
		req.Header.Set("Content-Type", "application/json")
	}

	resp, err := f.client.Do(req)
	if err != nil {
		return 0, err
	}
	defer func() { _ = resp.Body.Close() }()
	// Drain the body so the connection can be reused.
	_, _ = io.Copy(io.Discard, resp.Body)
	return resp.StatusCode, nil
}

func minDuration(a, b time.Duration) time.Duration {
	if a < b {
		return a
	}
	return b
}

package main

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"runtime/debug"
	"sort"
	"strconv"
	"sync/atomic"
	"time"

	"github.com/entireio/go-nuts"
	"github.com/nats-io/nats.go"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	otelcodes "go.opentelemetry.io/otel/codes"
	"go.opentelemetry.io/otel/trace"

	"github.com/entirehq/mirror-pipeline/internal/natslog"
	"github.com/entirehq/mirror-pipeline/internal/natspub"
	"github.com/entirehq/mirror-pipeline/pkg/metajobs"
	"github.com/entireio/go-nuts/natsmsg"
)

const (
	// lifecycleStream is the JetStream stream carrying resource_lifecycle_v1 on
	// every cell. Provisioned declaratively in fleet (apps/nats-streams) —
	// meta-fanout neither creates nor reconciles it, it only consumes the local
	// copy and re-publishes into each remote cell's copy.
	lifecycleStream = "resource_lifecycle_v1"

	// lifecycleSubjectFilter binds the consumer to the whole stream. meta-fanout
	// is a dumb cross-region pipe for resource_lifecycle_v1: it fans every
	// subtype (github_handle.*, verified_email.*, and the org/project/repo
	// binding events that share the bus) and leaves subtype filtering to the
	// per-cell consumers downstream.
	lifecycleSubjectFilter = lifecycleStream + ".>"

	// lifecycleDurable is meta-fanout's durable on the LOCAL
	// resource_lifecycle_v1 stream — distinct from the github_meta webhook and
	// backfill durables so the three drain independently. Overridable via env for
	// non-prod / migration.
	lifecycleDurable = "meta-fanout-lifecycle"

	// lifecyclePublishAckWait bounds the synchronous pub-ack on each remote
	// region's PublishMsg (the shared natspub.AckWait, so the lifecycle fan
	// can't drift from the job publishers). A publish routed to a reconnecting
	// region becomes a bounded error → consumer Nak → JetStream redelivery,
	// instead of parking in the client's reconnect buffer and stalling the
	// serial consume loop until the region returns.
	lifecyclePublishAckWait = natspub.AckWait

	// lifecycleFannedByHeader marks a resource_lifecycle_v1 event as an
	// already-fanned cross-region copy. publishOne stamps it (value = the
	// fanning cell's cluster id) on every copy it emits; dispatch skips
	// re-fanning any event that already carries it. That makes the fan exactly
	// one generation deep: an event fanned US→EU is not re-fanned by EU back to
	// US or on to AP, so a cross-region echo loop is structurally impossible at
	// any lag — independent of the destination dedup window (COR-902). The value
	// is for debuggability (which cell exported it); the guard keys on presence.
	// Carried verbatim across hops like any user header, so once stamped it stays
	// stamped.
	lifecycleFannedByHeader = "Entire-Lifecycle-Fanned-By"
)

// lifecycleFanout re-publishes one resource_lifecycle_v1 event into the local
// resource_lifecycle_v1 stream of every REMOTE region, subject and payload
// verbatim.
//
// The local cell is deliberately not a target: entire-core already emitted the
// event into the local stream (that is what this consumer reads), so publishing
// it back would feed the consumer its own output — an infinite loop, since here
// the source and target stream are the same (unlike github_meta_v1, whose
// source is the separate webhooks_github_v1 stream). meta-fanout's only job is
// to carry the event to the OTHER cells. With no remotes configured
// (single-region mode) the fan is a no-op and the delivery simply Acks.
type lifecycleFanout struct {
	remotes map[string]metajobs.JetStreamPublisher // cluster_id → remote JetStream

	// localClusterID is this cell's cluster id (FANOUT_LOCAL_CLUSTER_ID). It is
	// stamped as the lifecycleFannedByHeader value on every fanned copy so the
	// one-generation guard in dispatch can suppress echoes. Empty only in
	// single-region mode, where remotes is also empty and the fan never runs.
	localClusterID string
}

// fan publishes (subject, data) into every remote region. Regions are
// independent: a failure on one (a region momentarily disconnected) must not
// stop the others, so we attempt all and return a non-nil error if any failed
// — the caller Naks and the whole event rides JetStream redelivery; the regions
// that already accepted it re-publish idempotently (same Nats-Msg-Id within the
// dedup window).
func (f *lifecycleFanout) fan(ctx context.Context, subject, msgID string, data []byte, srcHeader nats.Header) error {
	span := trace.SpanFromContext(ctx)

	var failed []string
	var firstErr error
	for _, clusterID := range f.sortedClusters() {
		if err := f.publishOne(ctx, f.remotes[clusterID], subject, msgID, data, srcHeader); err != nil {
			failed = append(failed, clusterID)
			if firstErr == nil {
				firstErr = err
			}
			slog.ErrorContext(ctx, "Lifecycle fan failed for region; continuing with remaining regions",
				slog.String("subject", subject),
				slog.String("cluster_id", clusterID),
				slog.Any("error", err))
		}
	}

	span.SetAttributes(
		attribute.Int("entire.fanout.regions", len(f.remotes)),
		attribute.Int("entire.fanout.regions_failed", len(failed)),
	)
	if len(failed) > 0 {
		span.SetAttributes(attribute.StringSlice("entire.fanout.failed_cluster_ids", failed))
		return fmt.Errorf("lifecycle fan failed for %d of %d regions (clusters: %v): %w",
			len(failed), len(f.remotes), failed, firstErr)
	}
	return nil
}

// publishOne re-publishes the event into one remote region's stream. The source
// headers are carried verbatim (preserving the dedup Nats-Msg-Id) on a private
// copy per region, then this publish's trace context is injected so the
// downstream consumer span parents to meta-fanout rather than the original
// producer.
func (f *lifecycleFanout) publishOne(ctx context.Context, js metajobs.JetStreamPublisher, subject, msgID string, data []byte, srcHeader nats.Header) error {
	ctx, span := otel.Tracer(tracerName).Start(ctx, "resource_lifecycle.fan",
		trace.WithSpanKind(trace.SpanKindProducer),
		trace.WithAttributes(
			attribute.String("messaging.system", "nats"),
			attribute.String("messaging.operation.type", "publish"),
			attribute.String("messaging.destination.name", subject),
		),
	)
	defer span.End()

	msg := &nats.Msg{
		Subject: subject,
		Data:    data,
		Header:  cloneHeader(srcHeader),
	}
	// Mark this copy as fanned so the destination cell does not re-export it
	// (see dispatch). cloneHeader gave us a private copy, so this never mutates
	// the shared source header.
	msg.Header.Set(lifecycleFannedByHeader, f.localClusterID)
	if msgID != "" {
		msg.Header.Set(metajobs.NatsMsgIDHeader, msgID)
		span.SetAttributes(attribute.String("messaging.message.id", msgID))
	}
	natsmsg.Inject(ctx, msg)

	pubCtx, cancel := context.WithTimeout(ctx, lifecyclePublishAckWait)
	defer cancel()
	ack, err := js.PublishMsg(pubCtx, msg)
	if err != nil {
		span.RecordError(err)
		span.SetStatus(otelcodes.Error, "nats publish")
		return fmt.Errorf("publish lifecycle event: %w", err)
	}
	span.SetAttributes(
		attribute.Int64("messaging.nats.sequence", int64(ack.Sequence)),
		attribute.Bool("messaging.nats.duplicate", ack.Duplicate),
	)
	return nil
}

func (f *lifecycleFanout) sortedClusters() []string {
	out := make([]string, 0, len(f.remotes))
	for cid := range f.remotes {
		out = append(out, cid)
	}
	sort.Strings(out)
	return out
}

// lifecycleConsumer drains the LOCAL resource_lifecycle_v1 stream and fans each
// event cross-region. Its own durable keeps it isolated from the github_meta
// webhook and backfill consumers on their own streams. The ack discipline
// mirrors the github_meta consumer: explicit ManualAck with a bounded AckWait
// and MaxDeliver, NakWithDelay on a transient fan failure, Ack on success.
// There is no Term path — the event is republished verbatim, so nothing about
// it can be permanently unprocessable.
type lifecycleConsumer struct {
	js      nats.JetStreamContext
	fanout  *lifecycleFanout
	metrics *metaFanoutMetrics
	durable string
	subject string
	// health drives the severity of subscribe/fetch failure logs: recoverable
	// interruptions log at warn until the loop goes too long without progress.
	health natslog.Health

	// enqueuer + resolver drive the additive mirror.created → github_meta seed
	// (COR-717). Both nil leaves the consumer a pure cross-region fan (its
	// original behavior), so fan-only tests need not wire them.
	enqueuer backfillEnqueuer
	resolver mirrorResolver

	// subscribed mirrors the github_meta consumer's /readyz gate: a pod that can
	// dial NATS but cannot PullSubscribe (auth/perm/durable-config problem) is
	// reported NotReady instead of silently looping on backoff.
	subscribed atomic.Bool
}

// Ready returns true while the consumer holds a live pull subscription.
func (c *lifecycleConsumer) Ready() bool { return c.subscribed.Load() }

func (c *lifecycleConsumer) run(ctx context.Context) {
	backoff := consumerBackoffInit
	for {
		c.subscribed.Store(false)
		sub, err := c.js.PullSubscribe(c.subject, c.durable,
			nats.ManualAck(),
			nats.AckWait(consumerAckWait),
			nats.MaxDeliver(consumerMaxDeliver),
		)
		if err != nil {
			c.health.SubscribeErr(ctx, "Lifecycle subscribe failed", err,
				slog.String("subject", c.subject), slog.String("durable", c.durable))
			select {
			case <-ctx.Done():
				return
			case <-time.After(backoff):
				backoff = min(backoff*2, consumerBackoffMax)
				continue
			}
		}
		backoff = consumerBackoffInit
		c.subscribed.Store(true)
		slog.Info("Lifecycle subscribed", slog.String("subject", c.subject), slog.String("durable", c.durable))

		c.consumeLoop(ctx, sub)
		c.subscribed.Store(false)

		if ctx.Err() != nil {
			return
		}
	}
}

func (c *lifecycleConsumer) consumeLoop(ctx context.Context, sub *nats.Subscription) {
	for {
		if ctx.Err() != nil {
			return
		}
		msgs, err := sub.Fetch(1, nats.MaxWait(5*time.Second))
		if err != nil {
			if errors.Is(err, nats.ErrTimeout) {
				// An idle poll is progress: connected, stream merely quiet.
				c.health.Recovered()
				continue
			}
			// This loop lacked the shutdown guard its siblings carry, so a
			// clean teardown surfaced as a fault here.
			if nuts.IsShutdownFetchErr(ctx, err) {
				return
			}
			c.health.Err(ctx, "Lifecycle fetch error", err)
			return
		}
		c.health.Recovered()
		for _, msg := range msgs {
			c.handleMessage(ctx, msg)
		}
	}
}

func (c *lifecycleConsumer) handleMessage(ctx context.Context, msg *nats.Msg) {
	ctx = natsmsg.Extract(ctx, msg)
	ctx, span := otel.Tracer(tracerName).Start(ctx, "meta_fanout.lifecycle_fan",
		trace.WithSpanKind(trace.SpanKindConsumer),
		trace.WithAttributes(
			attribute.String("messaging.system", "nats"),
			attribute.String("messaging.operation.type", "receive"),
			attribute.String("messaging.destination.name", msg.Subject),
		),
	)
	defer span.End()

	if meta, err := msg.Metadata(); err == nil {
		span.SetAttributes(
			attribute.Int64("messaging.nats.sequence", int64(meta.Sequence.Stream)),
			attribute.Int64("messaging.nats.delivery_count", int64(meta.NumDelivered)),
		)
	}

	c.dispatch(ctx, span, msg.Subject, msg.Data, msg.Header, msg)
}

// dispatch is the per-message handler. Exposed so tests can drive the fan + ack
// behavior directly with a fake ackableMsg, no live JetStream needed.
func (c *lifecycleConsumer) dispatch(ctx context.Context, span trace.Span, subject string, data []byte, header nats.Header, msg ackableMsg) {
	// A panic anywhere below must NOT unwind into the consume goroutine: that
	// crashes the process, and because the message was never acked JetStream
	// redelivers it — so every replica that picks it up crashes in turn, turning
	// one poison-pill delivery into a cluster-wide crash-loop. Recover and Nak
	// (bounded by MaxDeliver) instead.
	defer func() {
		if r := recover(); r != nil {
			err := fmt.Errorf("panic recovered in lifecycle handler: %v", r)
			span.RecordError(err)
			span.SetStatus(otelcodes.Error, "handler panic")
			span.SetAttributes(attribute.Bool("entire.handler.panicked", true))
			slog.ErrorContext(ctx, "Recovered panic in lifecycle handler; naking delivery (bounded by MaxDeliver)",
				slog.Any("panic", r), slog.String("stack", string(debug.Stack())))
			c.metrics.recordPanic(ctx)
			_ = msg.NakWithDelay(consumerFailureDelay)
		}
	}()

	span.SetAttributes(attribute.String("entire.lifecycle.subject", subject))

	// Additive to the verbatim fan: on a mirror.created, enqueue a github_meta
	// backfill so a new mirror gets its display metadata without a webhook or a
	// manual run (COR-717). Best-effort by design — it never touches the ack
	// disposition below, which stays governed solely by the fan. Run before the
	// fan so a delivery the fan will Nak (remote region down) still seeds; the
	// backfill dedup id makes the redelivery idempotent.
	c.maybeSeedMirrorMeta(ctx, span, subject, data)

	// One-generation fan (COR-902): if this event already carries the fanned-by
	// marker it is a cross-region copy some cell exported (possibly ours, hops
	// ago), so do NOT re-export it — re-fanning imported copies is exactly the
	// echo that recirculated at ~16.5/s across all cells. Ack and stop here. This
	// runs AFTER maybeSeedMirrorMeta on purpose: a foreign-origin mirror.created
	// reaches US only as a fanned copy and US is where the github_meta seed runs
	// (COR-717), so the seed must still fire for marked messages. And it does not
	// affect downstream consumers — the event is already in this cell's stream
	// where entire-api's repolifecycle / mirror-lifecycle / settings consumers
	// read it (COR-901); only the re-EXPORT is suppressed.
	if _, marked := header[lifecycleFannedByHeader]; marked {
		span.SetAttributes(attribute.Bool("entire.lifecycle.fanned_in", true))
		c.metrics.recordLifecycleFan(ctx, dispatchOutcomeSkippedForeign)
		_ = msg.Ack()
		return
	}

	if err := c.fanout.fan(ctx, subject, lifecycleMsgID(header, msg), data, header); err != nil {
		// A region was unreachable. NakWithDelay so JetStream redelivers after
		// the flat consumerFailureDelay; acking would drop the only durable copy
		// of the event before it reached every region. On the final delivery the
		// Nak is dropped silently at MaxDeliver (no DLQ — the source stream
		// retains the event and replay is a separate path).
		span.RecordError(err)
		span.SetStatus(otelcodes.Error, "lifecycle fan")
		slog.WarnContext(ctx, "Lifecycle fan failed; will redeliver",
			slog.String("subject", subject),
			slog.Int("delivery", numDelivered(msg)),
			slog.Duration("redeliver_in", consumerFailureDelay),
			slog.Any("error", err))
		c.metrics.recordLifecycleFan(ctx, dispatchOutcomeNak)
		_ = msg.NakWithDelay(consumerFailureDelay)
		return
	}

	c.metrics.recordLifecycleFan(ctx, dispatchOutcomeAck)
	_ = msg.Ack()
	slog.InfoContext(ctx, "Fanned lifecycle event", slog.String("subject", subject))
}

// lifecycleMsgID returns the dedup key carried onto the fanned copies. It
// prefers the source event's own Nats-Msg-Id (stable across the source's
// redeliveries and semantically the same logical event), falling back to the
// source stream + sequence (also stable for a given stored message) so a
// republish always collapses on the remote dedup window. Empty only for a
// synthetic message with neither, in which case dedup is simply not applied.
func lifecycleMsgID(srcHeader nats.Header, msg ackableMsg) string {
	if srcHeader != nil {
		if id := srcHeader.Get(metajobs.NatsMsgIDHeader); id != "" {
			return id
		}
	}
	if meta, err := msg.Metadata(); err == nil {
		return lifecycleStream + ":" + strconv.FormatUint(meta.Sequence.Stream, 10)
	}
	return ""
}

// cloneHeader deep-copies a nats.Header so per-region trace injection does not
// mutate the shared source header. A nil source yields an empty, writable map.
func cloneHeader(h nats.Header) nats.Header {
	out := make(nats.Header, len(h))
	for k, v := range h {
		out[k] = append([]string(nil), v...)
	}
	return out
}

package main

import (
	"time"

	"github.com/nats-io/nats.go"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/trace"

	"github.com/entirehq/mirror-pipeline/pkg/fanoutengine"
	"github.com/entirehq/mirror-pipeline/pkg/webhookevents"
)

// Retry envelope, mirroring cmd/fanout: a flat NakWithDelay redelivery (no
// escalating BackOff) bounded by MaxDeliver, with a short AckWait backstop for
// a pod that dies mid-dispatch. meta-fanout dispatch (unmarshal → route →
// publish) is sub-second, so the short windows are safe. Shared by the engine
// consumers (the live webhook dispatcher and the github_meta backfill, which
// gets the engine's Config.TermOnExhaustion work-queue disposition) and the
// still-hand-rolled github_pr backfill + lifecycle consumers. The Backoff*
// constants are now only the hand-rolled consumers' subscribe-retry cadence
// (the engine has its own internal backoff).
const (
	consumerBackoffInit = 1 * time.Second
	consumerBackoffMax  = 30 * time.Second

	// consumerFailureDelay is the flat delay between redeliveries on a
	// transient failure, requested via msg.NakWithDelay (a bare Nak() does NOT
	// honor a delay — the server redelivers immediately).
	consumerFailureDelay = 30 * time.Second

	// consumerMaxDeliver bounds redelivery: first attempt + 7 retries.
	consumerMaxDeliver = 8

	// consumerAckWait is the redelivery backstop when a pod dies mid-dispatch
	// without responding (no Ack/Nak/Term).
	consumerAckWait = 30 * time.Second

	// consumerInactiveThreshold lets the SERVER reap the LIVE webhook durable
	// after 72h without a pull request — webhooks_github_v1 is
	// interest-retention, so an abandoned durable pins every subsequent
	// delivery for all consumers until the stream's maxAge/maxBytes wall (the
	// 2026-06-01 incident). 72h sits under the stream's 96h maxAge. NOT
	// applied to the backfill durables: their work-queue streams pin nothing
	// when idle, and sitting idle between backfill runs is their normal
	// state. See fanoutengine.Config.InactiveThreshold.
	consumerInactiveThreshold = 72 * time.Hour
)

const tracerName = "meta-fanout"

// newConsumer wires the meta dispatcher (star/fork/repository → github_meta,
// pull_request → github_pr) into the shared fanoutengine runtime: the consumer
// scaffold (subscribe/backoff loop, Ack/Nak/Term decision tree, panic recovery,
// OTel span + trace propagation) lives in the engine; the envelope decode, span
// attrs, and metrics are plugged in here. js may be nil when only Dispatch is
// exercised (tests). meta-fanout has no nak-reason refinement (no DLQ, no
// unmapped-cluster split) so ClassifyNak is omitted.
func newConsumer(js nats.JetStreamContext, resolver *metaResolver, regions fanoutengine.Regions, metrics *metaFanoutMetrics, durable, subject string) *fanoutengine.Consumer {
	return fanoutengine.New(js, webhookDecoder{}, resolver, regions, hooksFor(metrics), fanoutengine.Config{
		Subject:           subject,
		Stream:            webhookevents.StreamName,
		Durable:           durable,
		Tracer:            tracerName,
		SpanName:          "meta_fanout.dispatch", // preserve the existing span name verbatim
		AckWait:           consumerAckWait,
		MaxDeliver:        consumerMaxDeliver,
		NakDelay:          consumerFailureDelay,
		InactiveThreshold: consumerInactiveThreshold,
		SpanAttrs:         stampGithubSpanAttrs,
	})
}

// webhookDecoder turns the raw delivery into the engine envelope by unmarshaling
// the ForwardedWebhook contract. A decode failure → Term (bad envelope).
type webhookDecoder struct{}

func (webhookDecoder) Decode(data []byte) (fanoutengine.Envelope, error) {
	fw, err := webhookevents.Unmarshal(data)
	if err != nil {
		return fanoutengine.Envelope{}, err
	}
	return fanoutengine.Envelope{
		Event:      fw.Event,
		DeliveryID: fw.DeliveryID,
		ObservedAt: fw.ReceivedAt,
		Body:       fw.Body,
	}, nil
}

// stampGithubSpanAttrs preserves the github.* span attributes the consumer used
// to set inline, kept on the domain side so the engine stays envelope-agnostic.
func stampGithubSpanAttrs(span trace.Span, env fanoutengine.Envelope) {
	span.SetAttributes(
		attribute.String("github.delivery_id", env.DeliveryID),
		attribute.String("github.event", env.Event),
	)
}

// hooksFor adapts the (nil-safe) metric methods into engine hooks.
func hooksFor(m *metaFanoutMetrics) fanoutengine.Hooks {
	return fanoutengine.Hooks{
		RecordDispatch: m.recordDispatch,
		RecordPanic:    m.recordPanic,
	}
}

// ackableMsg is the subset of *nats.Msg the lifecycle per-message handler needs,
// so tests can drive it with a fake without a live JetStream. (The live webhook
// consumer and both work-queue backfills now use fanoutengine.AckableMsg via the
// engine; only the hand-rolled lifecycle fan still uses this.)
type ackableMsg interface {
	Ack(opts ...nats.AckOpt) error
	Nak(opts ...nats.AckOpt) error
	NakWithDelay(delay time.Duration, opts ...nats.AckOpt) error
	Term(opts ...nats.AckOpt) error
	Metadata() (*nats.MsgMetadata, error)
}

// numDelivered reports the JetStream delivery count, or 0 if metadata is
// unavailable (e.g. a synthetic test message).
func numDelivered(msg ackableMsg) int {
	if meta, err := msg.Metadata(); err == nil {
		return int(meta.NumDelivered)
	}
	return 0
}

// Package fanoutengine is the shared NATS-consumer runtime extracted from the
// hand-rolled scaffold that cmd/fanout, cmd/meta-fanout, and cmd/core-fanout
// each copy: the subscribe + backoff-retry loop, the Ack/Nak/Term decision
// tree, panic recovery, the flat-NakWithDelay retry envelope, OTel span +
// trace-context propagation, and /readyz readiness.
//
// A binary plugs in a Decoder (raw bytes → Envelope) and a Resolver (envelope →
// self-describing Routes); the runtime owns everything else, including the
// per-region publish + partial-failure aggregation. This is the in-repo
// realization of the engine validated by the fanout/ spike — kept on the current
// legacy nats.JetStreamContext API and OTel wiring so converting a live binary
// is behavior-preserving. The modern jetstream.Consume shape lands when this
// graduates to the standalone module.
package fanoutengine

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"runtime/debug"
	"strings"
	"sync"
	"sync/atomic"
	"time"

	"github.com/entireio/go-nuts"
	"github.com/nats-io/nats.go"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	otelcodes "go.opentelemetry.io/otel/codes"
	"go.opentelemetry.io/otel/trace"

	"github.com/entirehq/mirror-pipeline/internal/natslog"
	"github.com/entireio/go-nuts/natsmsg"
)

// Subscribe-retry backoff: how long Run waits between attempts to (re-)open the
// PullSubscribe, e.g. while the upstream stream is still being ensured at
// startup. Distinct from the per-message redelivery delay (Config.NakDelay).
const (
	backoffInit = 1 * time.Second
	backoffMax  = 30 * time.Second

	fetchMaxWait = 5 * time.Second
)

// Disposition + term-reason metric strings the runtime emits. Stable wire
// contract — dashboards key on these.
const (
	OutcomeAck  = "ack"
	OutcomeNak  = "nak"
	OutcomeTerm = "term"

	ReasonBadEnvelope   = "bad_envelope"   // decode failed — not a valid envelope
	ReasonInputError    = "input_error"    // envelope ok, body malformed
	ReasonMaxDeliveries = "max_deliveries" // transient failure exhausted MaxDeliver (DLQ-captured + Term'd)

	// eventUnknown stands in for the event attribute when the envelope didn't
	// decode, so the attribute stays populated without inventing values.
	eventUnknown = "unknown"
)

// InputError marks a malformed input body (bad JSON, unparseable identifier) a
// Resolver cannot ever process. The runtime Terminates these without
// redelivery — replay can't unstick a broken payload.
//
// Reason optionally overrides the term-metric reason (default ReasonInputError)
// so a consumer can distinguish sub-kinds — e.g. a work-queue job whose source
// repo has vanished upstream vs a merely malformed job.
type InputError struct {
	Msg    string
	Reason string
}

func (e *InputError) Error() string { return e.Msg }

// Input constructs an *InputError with the default ReasonInputError term reason.
func Input(format string, a ...any) *InputError { return &InputError{Msg: fmt.Sprintf(format, a...)} }

// InputReason constructs an *InputError that records reason on the term metric
// instead of the default ReasonInputError.
func InputReason(reason, format string, a ...any) *InputError {
	return &InputError{Msg: fmt.Sprintf(format, a...), Reason: reason}
}

// AsInputError reports whether err is (or wraps) an *InputError.
func AsInputError(err error) (*InputError, bool) {
	var ie *InputError
	if errors.As(err, &ie) {
		return ie, true
	}
	return nil, false
}

// Envelope is the decoded source envelope handed to a Resolver.
type Envelope struct {
	Event      string
	DeliveryID string
	ObservedAt time.Time
	Body       []byte
}

// Decoder turns a raw delivery into an Envelope. A non-nil error → Term
// (bad envelope; replay can't fix it).
type Decoder interface {
	Decode(data []byte) (Envelope, error)
}

// Hooks are the metric callbacks. Passed as funcs so a binary's unexported
// metric methods can be wired without exporting them. Both are nil-safe.
type Hooks struct {
	RecordDispatch func(ctx context.Context, event, outcome, reason string)
	RecordPanic    func(ctx context.Context)

	// Worker-pool + latency instruments (cmd/fanout). All nil-safe; serial
	// consumers leave them unset. IncActive/DecActive bracket one in-flight
	// dispatch; RecordFetchBatch reports a non-empty Fetch's size;
	// RecordDuration reports one dispatch's wall-clock seconds tagged by outcome.
	IncActive        func(ctx context.Context)
	DecActive        func(ctx context.Context)
	RecordFetchBatch func(ctx context.Context, n int)
	RecordDuration   func(ctx context.Context, outcome string, seconds float64)
}

// Config is the per-consumer wiring.
type Config struct {
	Subject string // subscribe subject/filter, e.g. webhooks.github.v1.push
	Durable string // pull-consumer durable (distinct per region where applicable)
	Tracer  string // OTel tracer (instrumentation scope) name, e.g. "core-fanout"

	// SpanName is the per-message span name. Kept separate from Tracer because
	// the existing consumers use an underscore form ("core_fanout.dispatch")
	// distinct from the hyphenated tracer/scope name — trace queries key on it,
	// so it must be preserved verbatim on conversion. Defaults to
	// Tracer+".dispatch" when empty.
	SpanName string

	// Retry envelope. The runtime applies these to PullSubscribe and to the
	// per-message NakWithDelay. Callers keep these as their own constants so the
	// domain-specific invariants (e.g. redelivery-span < dedup-window) stay
	// testable at the call site.
	AckWait time.Duration
	// MaxDeliver is the JetStream delivery-attempt limit. Use -1 for unlimited
	// transient retries; poison inputs still Term through the decode/InputError
	// paths independently of this setting.
	MaxDeliver int
	NakDelay   time.Duration

	// InactiveThreshold, when set, has the SERVER delete the durable after
	// that long without a pull request. On an interest-retention stream
	// (webhooks_github_v1) an abandoned durable — undeployed or wedged app —
	// otherwise pins every subsequent matching delivery for ALL consumers
	// until the stream's maxAge/maxBytes wall (the 2026-06-01 incident);
	// reaping it releases the backlog. Size it under the stream's maxAge and
	// well above any deploy gap: an app deliberately down longer loses its
	// cursor and re-consumes whatever is still retained when it returns
	// (safe: consumers are idempotent and msg-id-deduped downstream). Leave
	// unset (0) for work-queue streams, where an idle durable pins nothing.
	//
	// Requires Stream: the threshold is reconciled onto an ALREADY-EXISTING
	// durable via UpdateConsumer before subscribing, because the legacy
	// PullSubscribe binds to an existing consumer and silently ignores this
	// field (nats.go checkConfig does not compare it) — without the update,
	// the option would only take effect on freshly created durables.
	InactiveThreshold time.Duration

	// Stream is the JetStream stream the durable lives on. Only needed (and
	// only used) when InactiveThreshold is set — see above.
	Stream string

	// ClassifyNak optionally refines a transient (nak) error into a metric
	// reason and may annotate the span / log (e.g. an unmapped-cluster misconfig
	// that won't self-heal). Returns "" for a plain transient outage.
	ClassifyNak func(ctx context.Context, span trace.Span, err error) string

	// SpanAttrs optionally stamps domain attributes from the decoded envelope
	// (e.g. github.delivery_id / github.event), keeping the runtime domain-free.
	SpanAttrs func(span trace.Span, env Envelope)

	// Concurrency / FetchBatch enable a bounded worker pool (cmd/fanout). A
	// Concurrency of 0 or 1 keeps the strictly-serial Fetch(1) path (the
	// core-fanout / meta-fanout default, byte-for-byte unchanged). When >1, the
	// runtime fetches FetchBatch at a time and hands each message to one of
	// Concurrency workers. FetchBatch MUST be <= Concurrency — the AckWait
	// correctness bound (JetStream starts a message's AckWait clock when Fetch
	// delivers it, so an over-large batch leaves the tail aging un-dispatched);
	// the caller validates this. FetchBatch defaults to 1.
	Concurrency int
	FetchBatch  int

	// DLQ optionally captures dead-lettered deliveries (Term on bad envelope /
	// input error, or a transient failure exhausting MaxDeliver). nil disables
	// capture — behavior is then identical to the no-DLQ consumers.
	DLQ DLQ

	// TermOnExhaustion makes a transient failure — or a recovered panic — on the
	// FINAL delivery Term the message (reason=max_deliveries) instead of Nak,
	// even without a DLQ. For work-queue streams where an un-acked exhausted
	// message orphans until max_age rather than being redelivered (COR-762);
	// webhook/durable streams leave it off (Nak, or Term + DLQ capture).
	TermOnExhaustion bool
}

// AckableMsg is the subset of *nats.Msg the per-message handler needs. Narrowed
// so Dispatch can be driven by a fake in tests without a live JetStream.
type AckableMsg interface {
	Ack(opts ...nats.AckOpt) error
	Nak(opts ...nats.AckOpt) error
	NakWithDelay(delay time.Duration, opts ...nats.AckOpt) error
	Term(opts ...nats.AckOpt) error
	Metadata() (*nats.MsgMetadata, error)
}

// Consumer is the running pull consumer: a Decoder + Resolver driven by the
// shared runtime. The Resolver returns Routes and the engine owns the per-region
// publish + partial-failure aggregation.
type Consumer struct {
	js       nats.JetStreamContext
	decoder  Decoder
	resolver Resolver
	regions  Regions
	hooks    Hooks
	cfg      Config
	memo     *routeMemo

	subscribed atomic.Bool
	// health drives the severity of subscribe/fetch failure logs: recoverable
	// interruptions log at warn until the loop goes too long without progress.
	health natslog.Health
}

// New builds a consumer on the Resolver contract: the Resolver returns Routes and
// the engine owns the per-region publish + partial-failure aggregation (publish
// all, Nak if any failed, Term + DLQ on exhaustion).
func New(js nats.JetStreamContext, decoder Decoder, resolver Resolver, regions Regions, hooks Hooks, cfg Config) *Consumer {
	// Memo TTL for bounded consumers: each MaxDeliver attempt holds the message
	// for at most AckWait before the NakDelay-spaced redelivery. Unlimited
	// consumers use the fallback below; their memo remains an optimization and
	// may republish successful routes after a long-running outage.
	memoTTL := time.Duration(cfg.MaxDeliver) * (cfg.AckWait + cfg.NakDelay)
	if memoTTL <= 0 {
		memoTTL = 10 * time.Minute
	}
	return &Consumer{js: js, decoder: decoder, resolver: resolver, regions: regions, hooks: hooks, cfg: cfg,
		memo: newRouteMemo(memoTTL, memoMaxEntries)}
}

// ensureInactiveThreshold reconciles Config.InactiveThreshold onto an
// already-existing durable before the subscribe. The legacy PullSubscribe
// BINDS to an existing consumer and silently ignores a requested
// InactiveThreshold (nats.go checkConfig does not compare it), so without
// this the option would only apply to freshly created durables — a silent
// no-op on the live fleet. Read-modify-write keeps every other field exactly
// as the server has it; concurrent replicas write the same value, so the race
// is benign. Best-effort: on any error the subscribe proceeds — a missing
// threshold just degrades to the pre-threshold behavior, and the next Run
// iteration retries.
func (c *Consumer) ensureInactiveThreshold() {
	if c.cfg.InactiveThreshold <= 0 || c.cfg.Stream == "" {
		return
	}
	info, err := c.js.ConsumerInfo(c.cfg.Stream, c.cfg.Durable)
	if err != nil {
		// Not-found is the fresh-durable case: the subscribe below creates it
		// WITH the threshold (the create path sends the full config).
		if !errors.Is(err, nats.ErrConsumerNotFound) && !errors.Is(err, nats.ErrStreamNotFound) {
			slog.Warn("InactiveThreshold reconcile: consumer lookup failed; proceeding without update",
				slog.String("stream", c.cfg.Stream), slog.String("durable", c.cfg.Durable), slog.Any("error", err))
		}
		return
	}
	if info.Config.InactiveThreshold == c.cfg.InactiveThreshold {
		return
	}
	updated := info.Config
	updated.InactiveThreshold = c.cfg.InactiveThreshold
	if _, err := c.js.UpdateConsumer(c.cfg.Stream, &updated); err != nil {
		slog.Warn("InactiveThreshold reconcile: consumer update failed; proceeding without update",
			slog.String("stream", c.cfg.Stream), slog.String("durable", c.cfg.Durable), slog.Any("error", err))
		return
	}
	slog.Info("InactiveThreshold reconciled onto existing durable",
		slog.String("stream", c.cfg.Stream), slog.String("durable", c.cfg.Durable),
		slog.Duration("inactive_threshold", c.cfg.InactiveThreshold))
}

// Ready reports whether the consumer currently holds a live pull subscription.
// /readyz consults this so a pod that can dial NATS but cannot PullSubscribe
// (auth/perm/durable-config problem) is reported NotReady instead of looping on
// backoff while pretending healthy.
func (c *Consumer) Ready() bool { return c.subscribed.Load() }

func (c *Consumer) Run(ctx context.Context) {
	backoff := backoffInit
	for {
		c.subscribed.Store(false)
		c.ensureInactiveThreshold()
		subOpts := []nats.SubOpt{
			nats.ManualAck(),
			nats.AckWait(c.cfg.AckWait),
			nats.MaxDeliver(c.cfg.MaxDeliver),
		}
		if c.cfg.InactiveThreshold > 0 {
			subOpts = append(subOpts, nats.InactiveThreshold(c.cfg.InactiveThreshold))
		}
		sub, err := c.js.PullSubscribe(c.cfg.Subject, c.cfg.Durable, subOpts...)
		if err != nil {
			c.health.SubscribeErr(ctx, "Subscribe failed", err,
				slog.String("subject", c.cfg.Subject), slog.String("durable", c.cfg.Durable))
			select {
			case <-ctx.Done():
				return
			case <-time.After(backoff):
				backoff = min(backoff*2, backoffMax)
				continue
			}
		}
		backoff = backoffInit
		c.subscribed.Store(true)
		slog.Info("Subscribed", slog.String("subject", c.cfg.Subject), slog.String("durable", c.cfg.Durable))

		c.consumeLoop(ctx, sub)
		c.subscribed.Store(false)

		if ctx.Err() != nil {
			return
		}
	}
}

// messageFetcher is the subset of *nats.Subscription the worker pool needs,
// narrowed so the pool can be unit-tested with a fake returning canned batches
// without a live JetStream.
type messageFetcher interface {
	Fetch(batch int, opts ...nats.PullOpt) ([]*nats.Msg, error)
}

func (c *Consumer) consumeLoop(ctx context.Context, sub *nats.Subscription) {
	if c.cfg.Concurrency >= 1 {
		c.consumeLoopPool(ctx, sub)
		return
	}
	// Strictly-serial path (Concurrency unset): one Fetch(1) at a time. Identical
	// to the pre-engine core-fanout / meta-fanout behavior.
	for {
		if ctx.Err() != nil {
			return
		}
		msgs, err := sub.Fetch(1, nats.MaxWait(fetchMaxWait))
		if err != nil {
			if errors.Is(err, nats.ErrTimeout) {
				// An idle poll is progress: connected, stream merely quiet.
				c.health.Recovered()
				continue
			}
			if nuts.IsShutdownFetchErr(ctx, err) {
				return
			}
			c.health.Err(ctx, "Fetch error", err)
			return
		}
		c.health.Recovered()
		for _, msg := range msgs {
			c.handleMessage(ctx, msg)
		}
	}
}

// consumeLoopPool pulls FetchBatch deliveries at a time and hands each to a
// fixed pool of Concurrency workers, so independent deliveries dispatch in
// parallel within one pod. Backpressure is structural: the work channel is
// UNBUFFERED, so the fetch loop blocks on the send until a worker is free — the
// most un-acked fetched messages in flight is at most FetchBatch + Concurrency,
// a function of config, never of backlog. On shutdown the fetch loop stops
// fetching but every already-fetched message is still handed to the pool, which
// drains the channel to its close (not on ctx.Done), so an in-flight dispatch
// always runs to its Ack/Nak/Term. Ported verbatim from cmd/fanout.
func (c *Consumer) consumeLoopPool(ctx context.Context, sub messageFetcher) {
	batch := c.cfg.FetchBatch
	if batch < 1 {
		batch = 1
	}
	work := make(chan *nats.Msg)
	var wg sync.WaitGroup
	wg.Add(c.cfg.Concurrency)
	for range c.cfg.Concurrency {
		go func() {
			defer wg.Done()
			for msg := range work {
				if c.hooks.IncActive != nil {
					c.hooks.IncActive(ctx)
				}
				c.handleMessage(ctx, msg)
				if c.hooks.DecActive != nil {
					c.hooks.DecActive(ctx)
				}
			}
		}()
	}
	defer wg.Wait()
	defer close(work)

	for {
		if ctx.Err() != nil {
			return
		}
		msgs, err := sub.Fetch(batch, nats.MaxWait(fetchMaxWait))
		if err != nil {
			if errors.Is(err, nats.ErrTimeout) {
				// An idle poll is progress: connected, stream merely quiet.
				c.health.Recovered()
				continue
			}
			if nuts.IsShutdownFetchErr(ctx, err) {
				return
			}
			c.health.Err(ctx, "Fetch error", err)
			return
		}
		c.health.Recovered()
		if c.hooks.RecordFetchBatch != nil {
			c.hooks.RecordFetchBatch(ctx, len(msgs))
		}
		for _, msg := range msgs {
			work <- msg
		}
	}
}

func (c *Consumer) handleMessage(ctx context.Context, msg *nats.Msg) {
	spanName := c.cfg.SpanName
	if spanName == "" {
		spanName = c.cfg.Tracer + ".dispatch"
	}
	ctx = natsmsg.Extract(ctx, msg)
	ctx, span := otel.Tracer(c.cfg.Tracer).Start(ctx, spanName,
		trace.WithSpanKind(trace.SpanKindConsumer),
		trace.WithAttributes(
			attribute.String("messaging.system", "nats"),
			attribute.String("messaging.operation.type", "receive"),
			attribute.String("messaging.destination.name", msg.Subject),
		),
	)
	defer span.End()

	if meta, err := msg.Metadata(); err == nil {
		span.SetAttributes(
			attribute.Int64("messaging.nats.sequence", int64(meta.Sequence.Stream)),
			attribute.Int64("messaging.nats.delivery_count", int64(meta.NumDelivered)),
		)
	}

	c.Dispatch(ctx, span, msg.Subject, msg.Data, msg)
}

// Dispatch is the per-message handler: decode → resolve → publish → Ack/Nak/Term,
// with optional DLQ capture. It is exported and takes a subject + AckableMsg so
// tests can drive it directly with a fake, no live JetStream. subject is the
// original delivery subject, carried through for the DLQ record. A panic anywhere
// below is recovered and Nak'd — never allowed to crash the consume goroutine
// (which would redeliver the unacked message and crash-loop every replica).
func (c *Consumer) Dispatch(ctx context.Context, span trace.Span, subject string, data []byte, msg AckableMsg) {
	// outcome tags the dispatch-duration sample with the disposition the message
	// actually got. Defaults to nak so a panic (handled by the recover defer,
	// which leaves it nak) or a stray early return is attributed conservatively.
	// The duration recorder is the OUTERMOST defer (declared first) so it runs
	// after the recover defer and observes the final outcome.
	start := time.Now()
	outcome := OutcomeNak
	defer func() {
		if c.hooks.RecordDuration != nil {
			c.hooks.RecordDuration(ctx, outcome, time.Since(start).Seconds())
		}
	}()
	// deliveryID/event are captured for the recover path: a panic mid-fan-out
	// on the FINAL delivery must still drop the route memo entry (no redelivery
	// of this message can consult it again), and its dead-letter/metric should
	// carry the decoded event name. Empty until decode succeeds — nothing is
	// memoized under "".
	var deliveryID, event string
	defer func() {
		if r := recover(); r != nil {
			outcome = c.handlePanic(ctx, span, subject, data, msg, r, deliveryID, event)
		}
	}()

	env, err := c.decoder.Decode(data)
	if err != nil {
		span.RecordError(err)
		span.SetStatus(otelcodes.Error, "decode envelope")
		span.SetAttributes(attribute.Bool("entire.message.terminated", true))
		slog.ErrorContext(ctx, "Bad envelope, terminating", slog.Any("error", err))
		c.deadLetter(ctx, span, ReasonBadEnvelope, subject, Envelope{}, data, numDelivered(msg), err)
		c.recordDispatch(ctx, eventUnknown, OutcomeTerm, ReasonBadEnvelope)
		outcome = OutcomeTerm
		_ = msg.Term()
		return
	}
	deliveryID, event = env.DeliveryID, env.Event
	if c.cfg.SpanAttrs != nil {
		c.cfg.SpanAttrs(span, env)
	}

	outcome = c.dispatchRoutes(ctx, span, subject, env, data, msg)
}

// dispatchRoutes is the Resolver-path handler: resolve the envelope into routes,
// publish each into its region, and apply the disposition. Routes are
// independent — one region failing must not starve the others — so it publishes
// ALL routes, then Naks if any failed. Regions that already PubAck'd are
// memoized in-process and skipped when the redelivery lands back here; a
// redelivery on another replica misses the memo and re-publishes them, which
// is safe (idempotent syncs / server-side Nats-Msg-Id dedup where the stream's
// window allows — mirror_git_v1's 1s window notably does NOT cover the ~30s
// redelivery, which is why the memo exists; see routememo.go). Returns the
// outcome for the duration metric. An empty route set is a benign no-op (Ack —
// nothing to fan out).
func (c *Consumer) dispatchRoutes(ctx context.Context, span trace.Span, subject string, env Envelope, data []byte, msg AckableMsg) string {
	routes, ackReason, err := c.resolver.Resolve(ctx, env.Event, env.DeliveryID, env.ObservedAt, env.Body)
	if err != nil {
		var ie *InputError
		if errors.As(err, &ie) {
			reason := ReasonInputError
			if ie.Reason != "" {
				reason = ie.Reason // consumer-supplied sub-kind, e.g. repo_gone
			}
			span.RecordError(err)
			span.SetStatus(otelcodes.Error, ie.Error())
			span.SetAttributes(attribute.Bool("entire.message.terminated", true))
			slog.ErrorContext(ctx, "Resolve input error, terminating",
				slog.String("delivery_id", env.DeliveryID), slog.String("event", env.Event), slog.Any("error", err))
			c.deadLetter(ctx, span, reason, subject, env, data, numDelivered(msg), err)
			c.memo.forget(env.DeliveryID)
			c.recordDispatch(ctx, env.Event, OutcomeTerm, reason)
			_ = msg.Term()
			return OutcomeTerm
		}
		return c.nakOrExhaust(ctx, span, subject, env, data, msg, err)
	}

	// failedClusterIDs collects the cluster_id (route.Region()) of each route
	// whose publish failed; routeErrs collects the errors themselves.
	var failedClusterIDs []string
	var routeErrs []error
	skipped := 0
	for _, route := range routes {
		if c.memo.succeeded(env.DeliveryID, route.Region()) {
			// This route already PubAck'd this delivery on a prior attempt
			// that Nak'd on another route's failure — re-publishing would
			// re-run the work downstream (mirror_git_v1's 1s dedup window is
			// long expired by the redelivery).
			skipped++
			continue
		}
		rerr := c.publishRoute(ctx, route)
		if rerr != nil {
			failedClusterIDs = append(failedClusterIDs, route.Region())
			routeErrs = append(routeErrs, rerr)
			// cluster_id is the field the pre-engine consumers logged; the source
			// repo is on the span (entire.source_repo), stamped by the resolver.
			slog.ErrorContext(ctx, "Publish failed for placement; continuing with remaining placements",
				slog.String("cluster_id", route.Region()), slog.Any("error", rerr))
			continue
		}
		c.memo.record(env.DeliveryID, route.Region())
	}

	// Preserve the fan-out telemetry contract the consumers already emit
	// (entire.dispatch.placements* / failed_cluster_ids) — dashboards key on
	// these, so the engine keeps the established names even though its internal
	// term is "route". Could be Config-driven if a non-fan-out consumer ever
	// needs different labels.
	span.SetAttributes(
		attribute.Int("entire.dispatch.placements", len(routes)),
		attribute.Int("entire.dispatch.placements_failed", len(failedClusterIDs)),
		attribute.Int("entire.dispatch.placements_skipped", skipped),
	)
	if len(failedClusterIDs) > 0 {
		span.SetAttributes(attribute.StringSlice("entire.dispatch.failed_cluster_ids", failedClusterIDs))
		// Join ALL route failures (not just the first) so a consumer's ClassifyNak
		// finds a sentinel like ErrUnmappedRegion whenever ANY route hit it,
		// regardless of order — an earlier transient error must not mask a later
		// misconfig that never self-heals. The summary rides in front for a
		// readable log/span line.
		summary := fmt.Errorf("publish failed for %d of %d placements (clusters: %s)",
			len(failedClusterIDs), len(routes), strings.Join(failedClusterIDs, ","))
		cause := errors.Join(append([]error{summary}, routeErrs...)...)
		return c.nakOrExhaust(ctx, span, subject, env, data, msg, cause)
	}

	c.memo.forget(env.DeliveryID)
	c.recordDispatch(ctx, env.Event, OutcomeAck, ackReason)
	_ = msg.Ack()
	slog.InfoContext(ctx, "Dispatched",
		slog.String("delivery_id", env.DeliveryID), slog.String("event", env.Event),
		slog.Int("routes", len(routes)), slog.String("ack_reason", ackReason))
	return OutcomeAck
}

// publishRoute resolves the route's region to its publish handle and publishes.
// A region with no mapping (multi-region misconfig) is a failed route, like a
// publish error — it Naks and rides redelivery until the map is fixed.
func (c *Consumer) publishRoute(ctx context.Context, route Route) error {
	js, err := c.regions.resolve(route.Region())
	if err != nil {
		return err
	}
	return route.Publish(ctx, js)
}

// nakOrExhaust applies the transient disposition shared by the resolve-error and
// publish-failure cases: Nak for redelivery, unless this is the final delivery
// and a DLQ is wired, in which case capture + Term so the only durable copy
// survives.
func (c *Consumer) nakOrExhaust(ctx context.Context, span trace.Span, subject string, env Envelope, data []byte, msg AckableMsg, cause error) string {
	nakReason := ""
	if c.cfg.ClassifyNak != nil {
		nakReason = c.cfg.ClassifyNak(ctx, span, cause)
	}
	span.RecordError(cause)
	span.SetStatus(otelcodes.Error, "dispatch")
	// The final delivery is terminal whichever branch runs below — the Term,
	// or a Nak that JetStream will never redeliver (MaxDeliver reached). Drop
	// the route memo entry now, so a later SEPARATE message reusing the
	// delivery id (e.g. a manual GitHub redelivery after the ingest stream's
	// dedup window) fans out fresh instead of skipping regions.
	if isFinalDelivery(msg, c.cfg.MaxDeliver) {
		c.memo.forget(env.DeliveryID)
	}
	// On the final delivery a Nak is dropped silently at MaxDeliver (and for a
	// work-queue stream the un-acked message orphans until max_age). When a DLQ
	// is wired OR TermOnExhaustion is set, Term instead so the message is removed
	// cleanly; the DLQ (if any) captures it first for replay.
	if isFinalDelivery(msg, c.cfg.MaxDeliver) && (c.cfg.DLQ != nil || c.cfg.TermOnExhaustion) {
		slog.ErrorContext(ctx, "Dispatch failed; deliveries exhausted, terminating",
			slog.String("delivery_id", env.DeliveryID), slog.String("event", env.Event), slog.Any("error", cause))
		c.deadLetter(ctx, span, ReasonMaxDeliveries, subject, env, data, numDelivered(msg), cause)
		span.SetAttributes(attribute.Bool("entire.message.terminated", true))
		c.recordDispatch(ctx, env.Event, OutcomeTerm, ReasonMaxDeliveries)
		_ = msg.Term()
		return OutcomeTerm
	}
	slog.WarnContext(ctx, "Dispatch failed; will redeliver",
		slog.String("delivery_id", env.DeliveryID), slog.String("event", env.Event),
		slog.Int("delivery", numDelivered(msg)), slog.Duration("redeliver_in", c.cfg.NakDelay),
		slog.Any("error", cause))
	c.recordDispatch(ctx, env.Event, OutcomeNak, nakReason)
	_ = msg.NakWithDelay(c.cfg.NakDelay)
	return OutcomeNak
}

// deadLetter best-effort captures a dead-lettered delivery to the DLQ sink.
// No-op when no DLQ is configured. Fails open on a capture error (logs + a span
// event; the caller Terms anyway) — the failure is permanent or the deliveries
// are exhausted, so holding the message only re-runs doomed work. env is the
// zero value when the envelope didn't decode (raw bytes still preserved).
func (c *Consumer) deadLetter(ctx context.Context, span trace.Span, reason, subject string, env Envelope, data []byte, deliveries int, cause error) {
	if c.cfg.DLQ == nil {
		return
	}
	dl := DeadLetter{
		Reason:     reason,
		Subject:    subject,
		Envelope:   data,
		Deliveries: deliveries,
		Event:      env.Event,
		DeliveryID: env.DeliveryID,
		Err:        cause,
	}
	if err := c.cfg.DLQ.Capture(ctx, dl); err != nil {
		span.AddEvent("dlq.capture_failed")
		slog.WarnContext(ctx, "Failed to capture dead-lettered delivery; terminating anyway (fail open)",
			slog.String("reason", reason), slog.Any("error", err))
	}
}

func (c *Consumer) handlePanic(ctx context.Context, span trace.Span, subject string, data []byte, msg AckableMsg, recovered any, deliveryID, event string) string {
	err := fmt.Errorf("panic recovered in %s handler: %v", c.cfg.Tracer, recovered)
	span.RecordError(err)
	span.SetStatus(otelcodes.Error, "handler panic")
	span.SetAttributes(attribute.Bool("entire.handler.panicked", true))
	if c.hooks.RecordPanic != nil {
		c.hooks.RecordPanic(ctx)
	}
	// Terminal either way below (Term, or a Nak past MaxDeliver that will
	// never redeliver): drop the route memo entry so a later message reusing
	// the delivery id fans out fresh. Mid-fan-out panics can leave one.
	if isFinalDelivery(msg, c.cfg.MaxDeliver) {
		c.memo.forget(deliveryID)
	}
	// A Nak on the final delivery leaves the message un-acked and orphaned until
	// max_age (COR-762). When a DLQ is wired OR TermOnExhaustion is set, Term
	// instead — draining the poison-pill — and, symmetric with nakOrExhaust,
	// capture it first so a deterministic panic on delivery MaxDeliver isn't
	// silently lost outside the DLQ. deadLetter is a no-op when DLQ is nil (the
	// TermOnExhaustion-only work-queue case). The panic is counted via
	// RecordPanic above regardless.
	if isFinalDelivery(msg, c.cfg.MaxDeliver) && (c.cfg.DLQ != nil || c.cfg.TermOnExhaustion) {
		slog.ErrorContext(ctx, "Recovered panic on final delivery; terminating (dead-letter captured when a DLQ is wired)",
			slog.Any("panic", recovered), slog.String("stack", string(debug.Stack())))
		metricEvent := event
		if metricEvent == "" {
			metricEvent = eventUnknown
		}
		c.deadLetter(ctx, span, ReasonMaxDeliveries, subject, Envelope{DeliveryID: deliveryID, Event: event}, data, numDelivered(msg), err)
		span.SetAttributes(attribute.Bool("entire.message.terminated", true))
		c.recordDispatch(ctx, metricEvent, OutcomeTerm, ReasonMaxDeliveries)
		_ = msg.Term()
		return OutcomeTerm
	}
	slog.ErrorContext(ctx, "Recovered panic in handler; naking delivery",
		slog.Any("panic", recovered), slog.String("stack", string(debug.Stack())))
	_ = msg.NakWithDelay(c.cfg.NakDelay)
	return OutcomeNak
}

func (c *Consumer) recordDispatch(ctx context.Context, event, outcome, reason string) {
	if c.hooks.RecordDispatch != nil {
		c.hooks.RecordDispatch(ctx, event, outcome, reason)
	}
}

// numDelivered reports the JetStream delivery count, or 0 if metadata is
// unavailable (e.g. a synthetic test message).
func numDelivered(msg AckableMsg) int {
	if meta, err := msg.Metadata(); err == nil {
		return int(meta.NumDelivered)
	}
	return 0
}

// isFinalDelivery reports whether this is the last delivery before JetStream
// stops redelivering (NumDelivered has reached MaxDeliver), so a transient
// failure here is terminal rather than another Nak-and-retry.
func isFinalDelivery(msg AckableMsg, maxDeliver int) bool {
	if maxDeliver <= 0 {
		return false
	}
	if meta, err := msg.Metadata(); err == nil {
		return meta.NumDelivered >= uint64(maxDeliver)
	}
	return false
}

