package main

import (
	"context"
	"time"

	"github.com/nats-io/nats.go"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/trace"

	"github.com/entirehq/mirror-pipeline/pkg/fanoutengine"
	"github.com/entirehq/mirror-pipeline/pkg/webhookdlq"
	"github.com/entirehq/mirror-pipeline/pkg/webhookevents"
)

// Retry envelope. A flat NakWithDelay redelivery (no escalating BackOff) bounded
// by MaxDeliver, with a short AckWait backstop for a pod that dies mid-dispatch.
// The DLQ captures the delivery on MaxDeliver exhaustion for replay once the
// downstream recovers. Kept here (passed to the engine via Config) because
// MaxDeliver is load-bearing for the durable-reconcile-without-recreate
// invariant (see below).
const (
	// consumerFailureDelay is the flat delay between redeliveries on a transient
	// failure (requested via NakWithDelay; a bare Nak redelivers immediately).
	consumerFailureDelay = 30 * time.Second

	// consumerMaxDeliver bounds redelivery: first attempt + 7 retries. Kept at 8
	// (the value the live durable was created with) so the consumer reconciles
	// onto the existing JetStream consumer without a delete-and-recreate.
	consumerMaxDeliver = 8

	// consumerAckWait is the redelivery backstop when a pod dies mid-dispatch
	// without responding (no Ack/Nak/Term). Dispatch is sub-second, so a short
	// window is safe.
	consumerAckWait = 30 * time.Second

	// consumerInactiveThreshold lets the SERVER reap this durable after 72h
	// without a pull request. webhooks_github_v1 is interest-retention: an
	// abandoned durable (undeployed or wedged app) pins every subsequent
	// delivery for ALL consumers until the stream's maxAge/maxBytes wall —
	// the 2026-06-01 incident. 72h sits under the stream's 96h maxAge; an
	// app deliberately down longer loses its cursor and re-consumes what is
	// still retained on return (idempotent + msg-id-deduped downstream).
	// See fanoutengine.Config.InactiveThreshold.
	consumerInactiveThreshold = 72 * time.Hour
)

const tracerName = "fanout"

// newConsumer wires the git-sync resolver into the shared fanoutengine runtime
// with fanout's worker pool (concurrency/fetchBatch) and opt-in DLQ. The
// consumer scaffold (subscribe/backoff loop, worker pool, Ack/Nak/Term decision
// tree, panic recovery, DLQ capture, per-region publish + partial-failure, OTel
// span + trace propagation) lives in the engine; the envelope decode, span
// attrs, metrics, region map, and DLQ sink are plugged in here. dlq is a nil
// interface when capture is disabled.
func newConsumer(js nats.JetStreamContext, resolver *syncResolver, regions fanoutengine.Regions, metrics *fanoutMetrics, durable string, concurrency, fetchBatch int, dlq fanoutengine.DLQ) *fanoutengine.Consumer {
	return fanoutengine.New(js, webhookDecoder{}, resolver, regions, hooksFor(metrics), fanoutengine.Config{
		Subject:           webhookevents.SubjectPrefix + ">",
		Stream:            webhookevents.StreamName,
		Durable:           durable,
		Tracer:            tracerName,
		SpanName:          "fanout.dispatch", // preserve the existing span name verbatim
		AckWait:           consumerAckWait,
		MaxDeliver:        consumerMaxDeliver,
		NakDelay:          consumerFailureDelay,
		InactiveThreshold: consumerInactiveThreshold,
		SpanAttrs:         stampGithubSpanAttrs,
		Concurrency:       concurrency,
		FetchBatch:        fetchBatch,
		DLQ:               dlq,
	})
}

// webhookDecoder turns the raw delivery into the engine envelope by unmarshaling
// the ForwardedWebhook contract. A decode failure → Term (bad envelope).
type webhookDecoder struct{}

func (webhookDecoder) Decode(data []byte) (fanoutengine.Envelope, error) {
	fw, err := webhookevents.Unmarshal(data)
	if err != nil {
		return fanoutengine.Envelope{}, err
	}
	return fanoutengine.Envelope{
		Event:      fw.Event,
		DeliveryID: fw.DeliveryID,
		ObservedAt: fw.ReceivedAt,
		Body:       fw.Body,
	}, nil
}

// stampGithubSpanAttrs preserves the github.* span attributes the consumer used
// to set inline, kept on the domain side so the engine stays envelope-agnostic.
func stampGithubSpanAttrs(span trace.Span, env fanoutengine.Envelope) {
	span.SetAttributes(
		attribute.String("github.delivery_id", env.DeliveryID),
		attribute.String("github.event", env.Event),
	)
}

// hooksFor adapts the (nil-safe) metric methods into engine hooks, including the
// worker-pool + latency instruments fanout records.
func hooksFor(m *fanoutMetrics) fanoutengine.Hooks {
	return fanoutengine.Hooks{
		RecordDispatch:   m.recordDispatch,
		RecordPanic:      m.recordPanic,
		IncActive:        m.incActiveDispatch,
		DecActive:        m.decActiveDispatch,
		RecordFetchBatch: m.recordFetchBatch,
		RecordDuration:   m.recordDispatchDuration,
	}
}

// dlqSink adapts a webhooks_github_dlq publisher to the engine's DLQ interface.
// The engine's reason strings are the same values as webhookdlq's Reason* consts
// (bad_envelope / input_error / max_deliveries), so they pass through verbatim.
type dlqSink struct{ pub *webhookdlq.Publisher }

func (s dlqSink) Capture(ctx context.Context, dl fanoutengine.DeadLetter) error {
	rec := webhookdlq.DeadLetter{
		Source:          webhookdlq.SourceFanout,
		Reason:          dl.Reason,
		OriginalSubject: dl.Subject,
		DeliveryID:      dl.DeliveryID,
		Event:           dl.Event,
		Deliveries:      dl.Deliveries,
		Envelope:        dl.Envelope,
		DeadLetteredAt:  time.Now(),
	}
	if dl.Err != nil {
		rec.LastError = dl.Err.Error()
	}
	return s.pub.Publish(ctx, rec)
}
