// MaxDeliver, with a short AckWait backstop for a pod that dies mid-dispatch.
const (
	// consumerFailureDelay is the flat delay between redeliveries on a transient
	// failure (NakWithDelay; a bare Nak redelivers immediately).
	consumerFailureDelay = 30 * time.Second

	// consumerMaxDeliver bounds redelivery: first attempt + 7 retries. On
	// exhaustion the engine captures the delivery to webhooks_github_dlq and
	// Terms it (when DLQ capture is wired — see dlqSink), so a sustained
	// dependency outage doesn't silently drop trail events; matches cmd/fanout.
	// Unbounded (-1) was a fleet-wide hazard: an unreachable destination cell
	// would Nak forever and pin the shared interest stream for ALL of its
	// consumers. Malformed envelopes/bodies still Term immediately (bad_envelope
	// / input_error), captured to the DLQ too when wired.
	consumerMaxDeliver = 8

	// consumerAckWait is the redelivery backstop when a pod dies mid-dispatch
	// without responding (no Ack/Nak/Term). Dispatch is sub-second, so a short
	// window is safe.
	consumerAckWait = 30 * time.Second

	// consumerInactiveThreshold lets the server reap this durable if the app
	// stops pulling, so an abandoned durable can't pin the interest stream for
	// other consumers. Kept below webhooks_github_v1's max age.
	consumerInactiveThreshold = 24 * time.Hour

	tracerName = "trails-fanout"

	// nakReasonUnmappedCluster tags a nak whose cause is a placement routed to a
	// cluster_id absent from FANOUT_NATS_REGIONS — a non-transient misconfig,
	// distinct from a transient outage (empty reason). Unless fixed within the
	// ~3.5m redelivery span, the delivery exhausts MaxDeliver and is
	// dead-lettered (or final-Naks and is retained only until the stream's
	// max age when DLQ capture is off).
	nakReasonUnmappedCluster = "unmapped_cluster"
)

func newConsumer(js nats.JetStreamContext, resolver *trailResolver, regions fanoutengine.Regions, metrics *trailFanoutMetrics, durable, subject string, dlq fanoutengine.DLQ) *fanoutengine.Consumer {
	return fanoutengine.New(js, webhookDecoder{}, resolver, regions, hooksFor(metrics), fanoutengine.Config{
		Subject:           subject,
		Stream:            webhookevents.StreamName,
		Durable:           durable,
		Tracer:            tracerName,
		SpanName:          "trails_fanout.dispatch",
		AckWait:           consumerAckWait,
		MaxDeliver:        consumerMaxDeliver,
		NakDelay:          consumerFailureDelay,
		InactiveThreshold: consumerInactiveThreshold,
		ClassifyNak:       classifyNak,
		DLQ:               dlq,
		SpanAttrs:         stampGitHubSpanAttrs,
	})
}

// dlqSink adapts a webhooks_github_dlq publisher to the engine's DLQ interface.
// The engine's reason strings are the same values as webhookdlq's Reason* consts
// (bad_envelope / input_error / max_deliveries), so they pass through verbatim.
type dlqSink struct{ pub *webhookdlq.Publisher }

func (s dlqSink) Capture(ctx context.Context, dl fanoutengine.DeadLetter) error {
	rec := webhookdlq.DeadLetter{
		Source:          webhookdlq.SourceTrailsFanout,
		Reason:          dl.Reason,
		OriginalSubject: dl.Subject,
		DeliveryID:      dl.DeliveryID,
		Event:           dl.Event,
		Deliveries:      dl.Deliveries,
		Envelope:        dl.Envelope,
		DeadLetteredAt:  time.Now(),
	}
	if dl.Err != nil {
		rec.LastError = dl.Err.Error()
	}
	return s.pub.Publish(ctx, rec)
}

// classifyNak refines a transient nak into a metric reason. An unmapped cluster
// is a non-transient misconfig — a placement routed to a cluster_id absent from
// FANOUT_NATS_REGIONS — so it must be distinguishable from a transient outage
// (empty reason). The disposition stays a Nak: the delivery may carry other
// healthy placements, and a config fix within the ~3.5m redelivery span lets it
// drain; past that it exhausts MaxDeliver and is dead-lettered for replay (or
// final-Naks when DLQ capture is off).
func classifyNak(ctx context.Context, span trace.Span, err error) string {
	if errors.Is(err, fanoutengine.ErrUnmappedRegion) {
		span.SetAttributes(attribute.Bool("entire.mirror.unmapped_cluster", true))
		slog.ErrorContext(ctx, "Trail forge event placement routed to an unmapped cluster_id; fix FANOUT_NATS_REGIONS within the redelivery span or its deliveries dead-letter",
			slog.Any("error", err))
		return nakReasonUnmappedCluster
	}
	return ""
}

type webhookDecoder struct{}

func (webhookDecoder) Decode(data []byte) (fanoutengine.Envelope, error) {
	forwarded, err := webhookevents.Unmarshal(data)
	if err != nil {
		return fanoutengine.Envelope{}, err
	}
	return fanoutengine.Envelope{
		Event: forwarded.Event, DeliveryID: forwarded.DeliveryID,
		ObservedAt: forwarded.ReceivedAt, Body: forwarded.Body,
	}, nil
}

func stampGitHubSpanAttrs(span trace.Span, env fanoutengine.Envelope) {
	span.SetAttributes(
		attribute.String("github.delivery_id", env.DeliveryID),
		attribute.String("github.event", env.Event),
	)
}

func hooksFor(metrics *trailFanoutMetrics) fanoutengine.Hooks {
	return fanoutengine.Hooks{
		RecordDispatch: metrics.recordDispatch,
		RecordPanic:    metrics.recordPanic,
	}
}
