package main

import (
	"context"
	"errors"
	"log/slog"
	"strings"
	"time"

	"github.com/nats-io/nats.go"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/trace"

	"github.com/entirehq/mirror-pipeline/internal/mirrorjobs"
	"github.com/entirehq/mirror-pipeline/pkg/fanoutengine"
	"github.com/entirehq/mirror-pipeline/pkg/refevents"
)

// Native-mirror trigger consumer (COR-1021): consumes the LOCAL cluster's
// repo_refs_v1 ref-event stream and publishes one mirror.git sync_repo job per
// serving native mirror of the pushed repo — the event-driven fast path that
// keeps native mirrors fresh. Enabled per cluster via
// FANOUT_NATIVE_MIRROR_CONSUMER_ENABLED; a no-op while no native mirrors exist
// (every event resolves to an empty route set and Acks).
const (
	// nativeMirrorDurable is the pull-consumer durable on repo_refs_v1. A fixed
	// name (unlike FANOUT_DURABLE) is safe here because the stream itself is
	// per-cluster local — durables are stream-scoped, so two clusters' consumers
	// can never collide on one stream the way the shared US webhook stream's
	// could.
	nativeMirrorDurable = "native-mirror-fanout"

	// Retry envelope: same flat-NakWithDelay shape as the webhook consumer.
	// repo_refs_v1 is limits-retention, so an exhausted delivery is simply not
	// redelivered again (nothing orphans, nothing pins). A dropped event is
	// healed by the primary's next push — every sync replicates full ref
	// state — so no DLQ is wired (rev 11: v1 accepts "next push" as the
	// staleness RPO). No InactiveThreshold either: an abandoned durable on a
	// limits stream pins nothing.
	nativeMirrorFailureDelay = 30 * time.Second
	nativeMirrorMaxDeliver   = 8
	nativeMirrorAckWait      = 30 * time.Second
)

// Ack reasons for benign no-op dispositions, recorded on the completed metric
// so drops are observable without per-event logs (not_home fires on every
// worker-push echo in a mirror cluster; no_native_mirrors on every push in a
// home cluster — both far too hot to log).
const (
	ackReasonTlogRef      = "tlog_ref"          // transparency-log ref churn; the branch event triggers the sync
	ackReasonRepoNotFound = "repo_not_found"    // repo deleted between event publish and consume
	ackReasonNotHome      = "not_home"          // event echoed from a native-mirror placement (loop prevention)
	ackReasonNoMirrors    = "no_native_mirrors" // repo has no serving native mirrors (every repo today)
)

// newNativeMirrorConsumer wires the ref-event resolver into the shared
// fanoutengine runtime. Same worker pool knobs and region map as the webhook
// consumer; no DLQ (see the retry-envelope comment above).
func newNativeMirrorConsumer(js nats.JetStreamContext, resolver *nativeMirrorSyncResolver, regions fanoutengine.Regions, metrics *fanoutMetrics, concurrency, fetchBatch int) *fanoutengine.Consumer {
	return fanoutengine.New(js, refEventDecoder{}, resolver, regions, hooksFor(metrics), fanoutengine.Config{
		Subject:     refevents.NATSSubjectPrefix + ">",
		Stream:      refevents.NATSStreamName,
		Durable:     nativeMirrorDurable,
		Tracer:      tracerName,
		SpanName:    "fanout.native_mirror.dispatch",
		AckWait:     nativeMirrorAckWait,
		MaxDeliver:  nativeMirrorMaxDeliver,
		NakDelay:    nativeMirrorFailureDelay,
		SpanAttrs:   stampRefEventSpanAttrs,
		Concurrency: concurrency,
		FetchBatch:  fetchBatch,
	})
}

// refEventDecoder turns a raw repo_refs_v1 delivery into the engine envelope.
// A decode failure → Term (bad envelope). Event carries the ref op so the
// completed metric's event attribute stays low-cardinality: the KNOWN wire
// vocabulary (create/update/delete/force_update/symref_update) passes
// through, anything else is clamped to "other" — Unmarshal tolerates
// newer-producer payloads by design, so the wire value is unbounded even
// though the payload is valid. DeliveryID is the producer's
// content+timestamp identity, which doubles as the engine's route-memo key.
type refEventDecoder struct{}

// eventOther stands in for a ref op outside the known vocabulary on the
// metric attribute, so a future producer op can't create unbounded metric
// cardinality. Spans/logs still carry the real op via the resolver.
const eventOther = "other"

var knownRefOps = map[string]bool{
	refevents.RefOpCreate:       true,
	refevents.RefOpUpdate:       true,
	refevents.RefOpDelete:       true,
	refevents.RefOpForceUpdate:  true,
	refevents.RefOpSymrefUpdate: true,
}

func (refEventDecoder) Decode(data []byte) (fanoutengine.Envelope, error) {
	ev, err := refevents.Unmarshal(data)
	if err != nil {
		return fanoutengine.Envelope{}, err
	}
	event := ev.RefOp
	if !knownRefOps[event] {
		event = eventOther
	}
	return fanoutengine.Envelope{
		Event:      event,
		DeliveryID: ev.DeliveryID(),
		ObservedAt: ev.Timestamp,
		Body:       data,
	}, nil
}

// stampRefEventSpanAttrs stamps the envelope-level identity; the resolver adds
// the repo/ref attributes once it has re-decoded the body.
func stampRefEventSpanAttrs(span trace.Span, env fanoutengine.Envelope) {
	span.SetAttributes(
		attribute.String("entire.ref_event.op", env.Event),
		attribute.String("entire.ref_event.delivery_id", env.DeliveryID),
	)
}

// nativeRouteResolver is the mirrorjobs.NativeMirrorResolver surface this
// consumer needs, narrowed for tests.
type nativeRouteResolver interface {
	NativeMirrorRoutes(ctx context.Context, repoID string) (mirrorjobs.NativeMirrorResolution, error)
}

// nativeMirrorSyncResolver resolves local ref events into mirror.git sync_repo
// routes, one per serving native mirror. It is the engine's Resolver for the
// native-mirror consumer.
//
// Loop prevention: a worker push into a native-mirror placement emits ref
// events on THAT cluster's repo_refs_v1 too. Those events resolve to a home
// cluster different from this consumer's local cluster and are dropped, so a
// sync can never trigger another sync. Only the home cluster — where user
// pushes land — fans out.
type nativeMirrorSyncResolver struct {
	routes         nativeRouteResolver
	localClusterID string
}

func newNativeMirrorSyncResolver(routes nativeRouteResolver, localClusterID string) *nativeMirrorSyncResolver {
	return &nativeMirrorSyncResolver{routes: routes, localClusterID: localClusterID}
}

// Resolve returns one sync_repo route per serving native mirror of the pushed
// repo. Every ref op fans out — hash transitions move objects, and a
// symref_update (default-branch move) is reconciled by the worker's post-sync
// HEAD follow, the entiredb twin of the webhook path's default-branch edit.
// Transparency-log refs are skipped: every push writes them alongside the
// branch ref, so the branch event already triggers the (full-ref-state) sync.
func (d *nativeMirrorSyncResolver) Resolve(ctx context.Context, _ string, _ string, _ time.Time, body []byte) ([]fanoutengine.Route, string, error) {
	ev, err := refevents.Unmarshal(body)
	if err != nil {
		// Unreachable in practice — Decode already validated this payload —
		// kept as an input error so a future decoder/resolver drift Terms
		// instead of redelivering a poison payload forever.
		return nil, "", fanoutengine.Input("invalid ref event: %v", err)
	}
	if ev.RepoID == "" {
		// Unmarshal tolerates absent fields by design (independent producer
		// deploys), but an event with no repo id can never resolve — an
		// input error (Term), not a Nak, or the poison payload would ride
		// all MaxDeliver redeliveries for nothing.
		return nil, "", fanoutengine.Input("ref event has no repo_id")
	}

	if strings.HasPrefix(ev.RefName, "refs/tlog/") {
		return nil, ackReasonTlogRef, nil
	}

	// Stamp the parent span with the source coordinates so dropped or failed
	// deliveries are still findable by repo id. entire.ref_event.op is
	// re-stamped with the WIRE value: the decoder's envelope clamps unknown
	// ops to "other" for metric cardinality, but the span can carry the
	// real one.
	span := trace.SpanFromContext(ctx)
	span.SetAttributes(
		attribute.String("entire.source_kind", "entiredb"),
		attribute.String("entire.repo_id", ev.RepoID),
		attribute.String("entire.ref_name", ev.RefName),
		attribute.String("entire.ref_event.op", ev.RefOp),
	)

	res, err := d.routes.NativeMirrorRoutes(ctx, ev.RepoID)
	if err != nil {
		if errors.Is(err, mirrorjobs.ErrNativeRepoNotFound) {
			// Repo deleted between event publish and consume: benign skip.
			span.AddEvent("native_mirror.repo_not_found")
			slog.InfoContext(ctx, "Ref event for unknown repo; skipping",
				slog.String("repo_id", ev.RepoID), slog.String("ref_name", ev.RefName))
			return nil, ackReasonRepoNotFound, nil
		}
		slog.ErrorContext(ctx, "Native mirror route resolution failed",
			slog.String("repo_id", ev.RepoID), slog.Any("error", err))
		return nil, "", err
	}

	if res.HomeClusterID != d.localClusterID {
		// Mirror-side echo of a worker push (or an event for a repo homed
		// elsewhere): only the home cluster fans out.
		span.SetAttributes(attribute.String("entire.native_mirror.home_cluster_id", res.HomeClusterID))
		return nil, ackReasonNotHome, nil
	}

	if len(res.Routes) == 0 {
		return nil, ackReasonNoMirrors, nil
	}

	out := make([]fanoutengine.Route, 0, len(res.Routes))
	for _, route := range res.Routes {
		out = append(out, gitSyncRoute{route: route})
	}
	return out, "", nil
}

