	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/trace"

	"github.com/entirehq/mirror-pipeline/internal/mirrorjobs"
	"github.com/entirehq/mirror-pipeline/pkg/fanoutengine"
	"github.com/entirehq/mirror-pipeline/pkg/gitjobs"
)

const (
	// backfillDurable is the dedicated durable on the github_meta_backfill
	// stream — distinct from the live webhook consumer's durable so the two
	// drain independently. Overridable via env for non-prod / migration.
	backfillDurable = "meta-fanout-backfill"

	// backfillFilterSubject binds the consumer to every backfill job (all
	// publish to backfillSubject under this wildcard).
	backfillFilterSubject = backfillStreamName + ".>"

	// defaultBackfillGHRPS throttles the consumer's GitHub-API work (token mint
	// + repo fetch) when META_FANOUT_BACKFILL_GH_RPS is unset. The throttle is
	// PER REPLICA (in-process, like entire-api's BACKFILL_REPO_API_RPS), so the
	// effective rate across a region is this value times the meta-fanout replica
	// count — set it with pod count in mind. Conservative by default so it stays
	// well under GitHub's rate limit and doesn't starve the live
	// webhooks_github_v1 consumer.
	defaultBackfillGHRPS = 10.0
)

// tokenMinter mints a GitHub App installation token for a mirror. Satisfied by
// coreapp.Minter (entire-core STS); an interface so the consumer is testable
// without a live mint. The backfill passes installationID 0 — entire-core
// resolves it from the target repo's stored mirror metadata, since a backfill
// has no webhook to carry the id (the live git-sync path gets it from the
// webhook body, see cmd/fanout). See COR-615 summary: this relies on the
// companion entire-core change that resolves installation_id when 0.
type tokenMinter interface {
	InstallationToken(ctx context.Context, targetRepo, owner, repo string, installationID int64) (string, error)
}

// rpsThrottle paces calls to a fixed requests-per-second rate. A leaky-bucket
// over a shared "next allowed" instant: the first call passes immediately, each
// subsequent call waits until its slot. Safe for the serial consume loop and
// for concurrent callers. interval 0 (rps <= 0) disables throttling.
type rpsThrottle struct {
	mu       sync.Mutex
	interval time.Duration
	next     time.Time
}

func newRPSThrottle(rps float64) *rpsThrottle {
	if rps <= 0 {
		return &rpsThrottle{}
	}
	return &rpsThrottle{interval: time.Duration(float64(time.Second) / rps)}
}

// wait blocks until the next rate slot, or returns ctx.Err() if ctx is done.
func (t *rpsThrottle) wait(ctx context.Context) error {
	if t == nil || t.interval == 0 {
		return ctx.Err()
	}
	t.mu.Lock()
	now := time.Now()
	if t.next.Before(now) {
		t.next = now
	}
	slot := t.next
