// backfill stream carries backfillJob payloads, not webhook envelopes, so there
// is no envelope to decode (and a malformed job is an *InputError surfaced from
// Resolve → Term, not a bad_envelope). Returning a nil error here means the
// engine never records ReasonBadEnvelope for the backfill.
type backfillDecoder struct{}

func (backfillDecoder) Decode(data []byte) (fanoutengine.Envelope, error) {
	return fanoutengine.Envelope{Body: data}, nil
}

// newBackfillConsumer wires the github_meta backfill onto the shared engine with
// the work-queue disposition: TermOnExhaustion so a transient failure — or a
// recovered panic — on the final delivery Terms (draining the queue) instead of
// leaving the job orphaned until max_age (COR-762). Same retry envelope as the
// live consumer; its own durable + throttle keep it isolated. Metrics land on
// meta_fanout.backfill{kind=meta} via backfillHooks. The span name
// (meta_fanout.backfill) is preserved verbatim so existing trace queries keep
// working.
func newBackfillConsumer(js nats.JetStreamContext, res *backfillResolver, regions fanoutengine.Regions, metrics *metaFanoutMetrics, durable string) *fanoutengine.Consumer {
	return fanoutengine.New(js, backfillDecoder{}, res, regions, backfillHooks(metrics, backfillKindMeta), fanoutengine.Config{
		Subject:          backfillFilterSubject,
		Durable:          durable,
		Tracer:           tracerName,
		SpanName:         "meta_fanout.backfill",
		AckWait:          consumerAckWait,
		MaxDeliver:       consumerMaxDeliver,
		NakDelay:         consumerFailureDelay,
		TermOnExhaustion: true,
	})
}

// backfillHooks adapts the (nil-safe) backfill metric methods into engine hooks,
// tagging every disposition with kind (meta|pr). Unlike the live consumer the
// backfill ignores the per-delivery event label (there is no webhook event) and
// records against meta_fanout.backfill. A recovered panic Terms on the final
// delivery (reason=max_deliveries) and is separately counted on
// meta_fanout.handler_panic via RecordPanic.
func backfillHooks(m *metaFanoutMetrics, kind string) fanoutengine.Hooks {
	return fanoutengine.Hooks{
		RecordDispatch: func(ctx context.Context, _, outcome, reason string) {
			m.recordBackfill(ctx, kind, outcome, reason)
		},
		RecordPanic: m.recordPanic,
	}
}

