// Start creates/updates the durable consumer on nc and begins delivering
// messages to onMsg, returning a Runner that Stops when ctx is cancelled. The
// stream must already exist (provisioned declaratively); callers whose cells
// opt in per-stream gate Start behind that opt-in so a cell without the stream
// doesn't error at CreateOrUpdateConsumer.
//
// Consume errors are logged at Warn, except a drain/close during shutdown —
// both the core nats.go sentinels ([nuts.IsShutdownFetchErr]) and jetstream's
// own connection-closed error — which is a clean exit rather than a fault.
func Start(ctx context.Context, nc *nats.Conn, cfg Config, onMsg func(jetstream.Msg)) (*Runner, error) {
	if err := cfg.validate(nc, onMsg); err != nil {
		return nil, err
	}
	js, err := jetstream.New(nc)
	if err != nil {
		return nil, fmt.Errorf("jsconsumer(%s): jetstream.New: %w", cfg.Name, err)
	}
	if err := cfg.checkAgainstStream(ctx, js); err != nil {
		return nil, err
	}
	cons, err := js.CreateOrUpdateConsumer(ctx, cfg.Stream, jetstream.ConsumerConfig{
		Durable:           cfg.Durable,
		AckPolicy:         jetstream.AckExplicitPolicy,
		AckWait:           cfg.EffectiveAckWait(),
		MaxDeliver:        cfg.EffectiveMaxDeliver(),
		FilterSubject:     cfg.FilterSubject,
		FilterSubjects:    cfg.FilterSubjects,
		InactiveThreshold: cfg.InactiveThreshold,
		MaxAckPending:     cfg.MaxAckPending,
		// Always sent, so an update carries it — and so a nil CLEARS whatever
		// ladder the durable had, leaving AckWait as the schedule. That is
		// why a declaratively-managed ladder cannot simply be omitted here:
		// see Config.BackOff.
		BackOff: cfg.BackOff,
	})
	if err != nil {
		return nil, fmt.Errorf("jsconsumer(%s): create consumer %s/%s: %w", cfg.Name, cfg.Stream, cfg.Durable, err)
	}
	consumeOpts := []jetstream.PullConsumeOpt{jetstream.ConsumeErrHandler(func(_ jetstream.ConsumeContext, cerr error) {
		if isShutdownConsumeErr(ctx, cerr) {
			return
		}
		cfg.logger().WarnContext(ctx, cfg.Name+": consume error", slog.Any("error", cerr))
	})}
	switch {
	case cfg.KeepInProgress:
		consumeOpts = append(consumeOpts, jetstream.PullMaxMessages(1))
	case cfg.MaxMessages > 0:
		consumeOpts = append(consumeOpts, jetstream.PullMaxMessages(cfg.MaxMessages))
	}
	cc, err := cons.Consume(onMsg, consumeOpts...)
	if err != nil {
		return nil, fmt.Errorf("jsconsumer(%s): consume %s: %w", cfg.Name, cfg.Stream, err)
	}
	watcherDone := make(chan struct{})
	r := &Runner{cc: cc, closed: cc.Closed(), watcherDone: watcherDone}
	if cfg.Retry != nil {
		cfg.Retry.attach(cfg.Name, cfg.logger())
	}
	if mon := cfg.floorMonitor(); mon != nil {
		mon.attach(cons, cfg.Name, cfg.logger())
		pollDone := make(chan struct{})
		r.pollDone = pollDone
		go func() {
			defer close(pollDone)
			mon.pollFloor(ctx, r.closed)
		}()
	}
	go func() {
		defer close(watcherDone)
		select {
		case <-ctx.Done():
			r.Stop()
		case <-r.closed:
		}
	}()
	return r, nil
}

// isRetryableStartError classifies the narrow set of failures that can become
// healthy without changing Config or replacing nc. Everything else returns to
// the owner so a bad deployment cannot stay alive indefinitely with no
// consumer. Unknown server-side 5xx responses are retried, except known
// permanent JetStream configuration/account errors whose API happens to use a
// 5xx status.
func isRetryableStartError(err error) bool {
	if errors.Is(err, jetstream.ErrStreamNotFound) ||
		errors.Is(err, nats.ErrNoResponders) ||
		errors.Is(err, nats.ErrTimeout) ||
		errors.Is(err, nats.ErrDisconnected) {
		return true
	}

	var jsErr jetstream.JetStreamError
	if !errors.As(err, &jsErr) || jsErr.APIError() == nil {
		return false
	}
	apiErr := jsErr.APIError()
	switch apiErr.ErrorCode { //nolint:exhaustive // unrecognized 5xx codes are deliberately retryable; all other unknown codes fail closed
	case jetstream.JSErrCodeBadRequest,
		jetstream.JSErrCodeConsumerCreate,
		jetstream.JSErrCodeConsumerNameExists,
		jetstream.JSErrCodeMaximumConsumersLimit,
		jetstream.JSErrCodeJetStreamNotEnabledForAccount,
		jetstream.JSErrCodeJetStreamNotEnabled,
		jetstream.JSErrCodeConsumerAlreadyExists,
		jetstream.JSErrCodeDuplicateFilterSubjects,
		jetstream.JSErrCodeOverlappingFilterSubjects,
		jetstream.JSErrCodeConsumerEmptyFilter,
		jetstream.JSErrCodeConsumerExists:
		return false
	default:
		return apiErr.Code >= 500
	}
}

// Retry envelope for [Run]'s supervision: exponential from runRetryInitial
// doubling to runRetryMax, reset once a consume loop survives longer than the
// max. Package vars (not consts) so tests can compress the schedule.
var (
	runRetryInitial = time.Second
	runRetryMax     = 30 * time.Second
)

// Run supervises the consume loop [Start] builds. Where Start is one-shot —
// an error at consumer creation is returned, and a consume loop that closes
// underneath the caller (consumer deleted on the server, subscription
// invalidated) stays closed — Run retries both with exponential backoff
// (runRetryInitial doubling to runRetryMax, reset after a loop that outlives
// the max). In particular a stream that is not provisioned yet at boot — the
// declarative-provisioning race — is a retry, not a crash.
//
// Run blocks until ctx is cancelled, then joins the live loop (including an
// in-flight handler, see [Runner.Stop]) before returning, so it composes with
// the cancel → join → drain shutdown ordering as the body of a supervised
// goroutine:
//
//	g.Go(func(ctx context.Context) {
//		if err := jsconsumer.Run(ctx, nc, cfg, onMsg); err != nil {
//			log.Error("consumer config rejected", "error", err)
//		}
//	})
//
// Local configuration errors and permanent server responses (invalid consumer
// configuration, authorization/account setup) can never succeed on retry and
// are returned immediately. A missing declarative stream, temporary transport
// failure, or unknown server-side 5xx response remains supervised. A nil return
// means a clean, ctx-driven exit.
func Run(ctx context.Context, nc *nats.Conn, cfg Config, onMsg func(jetstream.Msg)) error {
	if err := cfg.validate(nc, onMsg); err != nil {
		return err
	}
	delay := runRetryInitial
	for {
		// Each attempt gets a child context so the cancel-watcher goroutine
		// Start arms is released when the attempt dies, instead of one
		// accumulating per recreate for the life of the process.
		attemptCtx, cancelAttempt := context.WithCancel(ctx)
		r, err := Start(attemptCtx, nc, cfg, onMsg)
		if err != nil {
			cancelAttempt()
			if ctx.Err() != nil {
				return nil //nolint:nilerr // a Start error during shutdown is a clean, ctx-driven exit, not a fault to report
			}
			if !isRetryableStartError(err) {
				return err
			}
			cfg.logger().WarnContext(ctx, cfg.Name+": start consumer failed; retrying",
				slog.Any("error", err), slog.Duration("retry_in", delay))
		} else {
			started := time.Now()
			select {
			case <-ctx.Done():
				r.Stop()
				cancelAttempt()
				return nil
			case <-r.closed:
				// Join before recreating, not just cancel: the attempt's
				// ack-floor poll may still be in an in-flight consumer-info
				// request against the OLD consumer, and the next Start attaches
				// the same monitor to a new one. Without the join that reply
				// can land after the reattach and overwrite fresh state with
				// stale. Stop is cheap here — the loop has already closed.
				r.Stop()
				cancelAttempt()
				if ctx.Err() != nil {
					return nil //nolint:nilerr // the loop closing during shutdown is the expected wind-down, not a fault
				}
				// A loop that ran long enough to be called healthy earns a
				// fresh envelope; a flapping one keeps escalating.
				if time.Since(started) >= runRetryMax {
					delay = runRetryInitial
				}
				cfg.logger().WarnContext(ctx, cfg.Name+": consume loop closed; recreating",
					slog.Duration("retry_in", delay))
			}
		}
		select {
		case <-ctx.Done():
			return nil
		case <-time.After(delay):
		}
		delay = min(delay*2, runRetryMax)
	}
}

// Process runs the per-message prologue shared by every consumer: open the
// consumer span (re-parented to the producer across the NATS hop), decode the
// payload, and on a decode error record it, log "<Name>: decode <Stream>;
// term", invoke onUndecodable (so the caller bumps its own drop metric with
// its own attributes), and Term the message — a poison payload won't decode on
// redelivery. On success it invokes handle with the span-enriched context, the
// live span (for RecordError/SetStatus on the business error paths), the
// message, and the decoded event; with Config.KeepInProgress set, an AckWait
// heartbeat runs for the duration of handle.
//
// Callers wire Process as the func they pass to Start AND the entry point
// their tests drive, so the decode-or-term path is exercised the same way in
// production and tests.
func Process[E any](
	ctx context.Context,
	msg jetstream.Msg,
	cfg Config,
	decode func([]byte) (E, error),
	handle func(ctx context.Context, span trace.Span, msg jetstream.Msg, ev E),
	onUndecodable func(ctx context.Context),
) {
	ctx, span := natsmsg.StartConsumerSpan(ctx, cfg.tracer(), msg, cfg.SpanName)
	defer span.End()

	ev, err := decode(msg.Data())
	if err != nil {
		span.RecordError(err)
		span.SetStatus(codes.Error, "decode")
		disposition := "term"
		if cfg.Retry != nil {
			disposition = "dead-letter"
		}
		cfg.logger().WarnContext(ctx, cfg.Name+": decode "+cfg.Stream+"; "+disposition,
			slog.Any("error", err), slog.String("subject", msg.Subject()))
		if onUndecodable != nil {
			onUndecodable(ctx)
		}
		if cfg.Retry != nil {
			// Same terminal effect as the Term below, but the payload
			// survives: a bare Term settles the message perfectly well, it
			// just leaves no trace of what was discarded — the last
			// drop-without-a-record surface in this scaffold, and a Retry is
			// exactly the capture path that closes it.
			if _, dlErr := cfg.Retry.DeadLetter(ctx, msg, "undecodable: "+err.Error()); dlErr != nil {
				cfg.logger().WarnContext(ctx, cfg.Name+": dead-letter undecodable failed", slog.Any("error", dlErr))
			}
			return
		}
		if termErr := msg.Term(); termErr != nil {
			cfg.logger().WarnContext(ctx, cfg.Name+": term failed", slog.Any("error", termErr))
		}
		return
	}
	if cfg.KeepInProgress {
		stop := natsmsg.KeepInProgress(msg.InProgress, cfg.EffectiveAckWait())
		defer stop()
	}
	handle(ctx, span, msg, ev)

package jsconsumer

import (
	"fmt"
	"strings"
	"time"

	"github.com/entireio/go-nuts/backoff"
)

// UnlimitedMaxDeliver mirrors [backoff.UnlimitedMaxDeliver] and
// jetstream.ConsumerConfig.MaxDeliver: a non-positive cap means the broker
// redelivers forever.
const UnlimitedMaxDeliver = backoff.UnlimitedMaxDeliver

// Schedule is a durable consumer's retry timing as plain values, and
// [Schedule.Validate] is the single implementation of the arithmetic that
// says whether it hangs together.
//
// It takes values rather than a live consumer or a [RetryConfig] on purpose.
// The same arithmetic has to run in three places — [NewRetry] at construction,
// a fleet CI lint over rendered NACK Consumer CRs before merge, and (when
// bind-only mode lands) the library at startup against the durable's ACTUAL
// server-side config — and three implementations of it would drift. ENT-1535
// was a consumer whose real redelivery envelope was 34h22m while its config
// advertised 17h45m; duplicated timing arithmetic is precisely how that
// happens. Compile this function into the checker instead of restating it.
//
// Validate is pure: no NATS connection, no I/O, no clock. Zero-valued fields
// are "not known / not constrained" and their checks are skipped, so a caller
// that knows only the server-side ladder still gets every check that ladder
// supports.
type Schedule struct {
	// NakDelay, Factor and MaxDelay describe the CLIENT-side ladder the
	// library applies with NakWithDelay (see backoff.Policy). Leave NakDelay
	// zero when the server owns redelivery.
	NakDelay time.Duration
	Factor   float64
	MaxDelay time.Duration

	// ServerBackOff is the SERVER-side ladder from the consumer's own config
	// (jetstream.ConsumerConfig.BackOff, or a NACK Consumer CR's backOff).
	// Leave it empty when the client owns redelivery. Setting both this and
	// NakDelay is the ENT-1535 defect itself and is reported as a violation.
	ServerBackOff []time.Duration

	// MaxDeliver is the consumer's delivery cap, AckWait its redelivery
	// timeout. Zero means unknown; [UnlimitedMaxDeliver] (or any non-positive
	// value) means the consumer never stops redelivering, which has no
	// terminal branch and so no duration to bound.
	MaxDeliver int
	AckWait    time.Duration

	// CaptureReserve is how many deliveries are held back to retry a failed
	// dead-letter capture, so the ladder's terminal branch is reached at
	// MaxDeliver-CaptureReserve.
	CaptureReserve int

	// MaxTimeToDeadLetter bounds the cumulative scheduled wait to that
	// terminal branch. Zero leaves it unbounded.
	MaxTimeToDeadLetter time.Duration

	// RecoverBy is the delivery by which a transient failure is expected to
	// clear, and FloorAge the stall threshold a floor-age breaker would act
	// on. Both are client-side expectations; zero means not applicable.
	RecoverBy int
	FloorAge  time.Duration

	// StreamMaxAge is the stream's retention window. A ladder that outlives it
	// cannot reach its own terminal branch — the message is discarded first.
	// Zero means unknown or unlimited.
	StreamMaxAge time.Duration
}

// Violation is one way a [Schedule] does not hang together.
type Violation struct {
	// Field names the setting to change, in the caller's own vocabulary where
	// they differ (a CR's backOff is this type's ServerBackOff).
	Field string
	// Problem states what is wrong and what it costs, in one sentence.
	Problem string
}

func (v Violation) String() string { return v.Field + ": " + v.Problem }

// Ladder reports the client-side ladder as a backoff.Policy.
func (s Schedule) Ladder() backoff.Policy {
	return backoff.Policy{NakDelay: s.NakDelay, Factor: s.Factor, MaxDelay: s.MaxDelay, MaxDeliver: s.MaxDeliver}
}

// DeadLetterDelivery is the delivery on which the terminal branch is reached:
// the delivery cap less whatever is reserved for retrying a failed capture.
func (s Schedule) DeadLetterDelivery() int { return s.MaxDeliver - s.CaptureReserve }

// RungBefore is the scheduled wait served before delivery number n (n >= 2),
// from whichever mechanism actually schedules this consumer's redeliveries, in
// precedence order:
//
//  1. ServerBackOff — the durable's ladder. JetStream repeats the LAST rung
//     once the array runs out, so a short list under a larger maxDeliver is
//     not a short ladder.
//  2. NakDelay — a client-scheduled ladder, for modelling a legacy consumer
//     that Naks with its own delays. Nothing in this package produces one.
//  3. AckWait — NO ladder at all. This is not "no wait": with an empty
//     BackOff the broker still redelivers, on the acknowledgement timeout, so
//     the real ladder is AckWait repeated. Treating that case as zero made
//     every duration check pass vacuously — an AckWait of 1h with MaxDeliver 6
//     scored as an instant schedule while really taking four hours to reach
//     the dead-letter branch.
//
// Every timing check goes through here rather than reading the fields
// directly, because each time one didn't, it silently measured a ladder that
// was not the one running.
func (s Schedule) RungBefore(n int) time.Duration {
	switch {
	case n < 2:
		return 0
	case len(s.ServerBackOff) > 0:
		return s.ServerBackOff[min(n-2, len(s.ServerBackOff)-1)]
	case s.NakDelay > 0:
		return s.Ladder().DelayFor(n - 1)
	default:
		return s.AckWait
	}
}

// CumulativeTo is the total scheduled wait a message has served by the time it
// is delivered for the nth time.
func (s Schedule) CumulativeTo(n int) time.Duration {
	var total time.Duration
	for i := 2; i <= n; i++ {
		total += s.RungBefore(i)
	}
	return total
}

// LongestRung is the largest wait this schedule ever serves before the
// terminal branch.
func (s Schedule) LongestRung() time.Duration {
	var longest time.Duration
	for i := 2; i <= s.DeadLetterDelivery(); i++ {
		longest = max(longest, s.RungBefore(i))
	}
	return longest
}

// TimeToDeadLetter is the cumulative scheduled wait before the terminal branch
// runs — the number a stall SLA is actually about. It counts scheduled waits
// only; handler time and a lost delivery's AckWait sit on top.
func (s Schedule) TimeToDeadLetter() time.Duration {
	return s.CumulativeTo(s.DeadLetterDelivery())
}

// Validate reports every way the schedule does not hang together, most
// structural first. An empty result means it is coherent.
//
//nolint:gocognit // one flat list of independent checks; splitting it would scatter the arithmetic this type exists to centralize
func (s Schedule) Validate() []Violation {
	var vs []Violation
	add := func(field, format string, args ...any) {
		vs = append(vs, Violation{Field: field, Problem: fmt.Sprintf(format, args...)})
	}

	// The ENT-1535 defect itself: two schedulers, so neither is the real one.
	if s.NakDelay > 0 && len(s.ServerBackOff) > 0 {
		add("ServerBackOff", "set with a client-side NakDelay (%s): the server stretches each NAK delay by the BackOff increments, so redeliveries follow neither ladder and the configured one becomes dead config", s.NakDelay)
	}
	if s.NakDelay < 0 {
		add("NakDelay", "must not be negative, got %s", s.NakDelay)
	}
	if s.Factor > 1 && s.MaxDelay <= 0 {
		add("MaxDelay", "required with a growing Factor (%.1f): an uncapped rung cannot be checked against any bound", s.Factor)
	}
	for i, d := range s.ServerBackOff {
		if d <= 0 {
			add("ServerBackOff", "rung %d must be positive, got %s", i, d)
		}
	}
	if s.MaxTimeToDeadLetter < 0 {
		add("MaxTimeToDeadLetter", "must not be negative, got %s", s.MaxTimeToDeadLetter)
	}
	// Non-positive means UNLIMITED redeliveries, matching
	// jetstream.ConsumerConfig.MaxDeliver and backoff.UnlimitedMaxDeliver.
	// Only a value below that sentinel is nonsense. An unlimited consumer has
	// no terminal branch, so every duration check below is skipped rather
	// than being computed against a delivery number that does not exist.
	if s.MaxDeliver < UnlimitedMaxDeliver {
		add("MaxDeliver", "must be -1 (unlimited) or positive, got %d", s.MaxDeliver)
	}
	if s.CaptureReserve < 0 {
		add("CaptureReserve", "must not be negative, got %d", s.CaptureReserve)
	}
	if s.MaxDeliver > 0 && s.CaptureReserve >= s.MaxDeliver {
		add("CaptureReserve", "%d leaves no deliveries for the handler out of MaxDeliver %d", s.CaptureReserve, s.MaxDeliver)
	}

	// A server ladder must have somewhere to apply every rung. The bound
	// mirrors the server's own (it rejects len(BackOff) > MaxDeliver, despite
	// error text implying strict >), so the equal case stays legal here too —
	// suspicious rather than wrong, since MaxDeliver deliveries leave only
	// MaxDeliver-1 redeliveries and that last rung is never served.
	if n := len(s.ServerBackOff); n > 0 && s.MaxDeliver > 0 && n > s.MaxDeliver {
		add("ServerBackOff", "has %d rungs but MaxDeliver %d schedules at most %d of them: %d deliveries leave %d redeliveries", n, s.MaxDeliver, s.MaxDeliver-1, s.MaxDeliver, s.MaxDeliver-1)
	}
	// The server does not run a consumer whose AckWait disagrees with its first
	// rung: on the ordinary create/update path it silently REWRITES the stored
	// AckWait to BackOff[0] (measured in internal/brokersemantics,
	// REDACTED). So the redelivery timing is
	// knowable — it is the ladder — and what the declared AckWait becomes is a
	// value nothing on the server ever holds. That is worth a violation for two
	// reasons: the config lies to whoever reads it, and a pedantic-mode client
	// rejects the same request outright rather than normalizing it, so a
	// mismatch this scaffold would apply quietly fails to reconcile under
	// NACK's controller.
	if len(s.ServerBackOff) > 0 && s.AckWait > 0 && s.AckWait != s.ServerBackOff[0] {
		add("AckWait", "%s disagrees with ServerBackOff[0] (%s): the server stores the first rung in place of it, so the declared AckWait never runs — and a pedantic-mode create rejects the mismatch instead of rewriting it", s.AckWait, s.ServerBackOff[0])
	}

	if s.MaxDeliver <= 0 || s.DeadLetterDelivery() < 1 {
		return vs // nothing below can be computed
	}
	ttl := s.TimeToDeadLetter()

	if s.MaxTimeToDeadLetter > 0 && ttl > s.MaxTimeToDeadLetter {
		add("MaxTimeToDeadLetter", "the ladder takes %s to reach the dead-letter branch (delivery %d), past the %s bound: shorten the rungs, lower MaxDeliver, or raise the bound", ttl, s.DeadLetterDelivery(), s.MaxTimeToDeadLetter)
	}
	// A ladder that outlives retention never reaches its own terminal branch.
	if s.StreamMaxAge > 0 && ttl >= s.StreamMaxAge {
		add("StreamMaxAge", "the ladder takes %s to reach the dead-letter branch but the stream discards after %s: the message is gone before it can be captured", ttl, s.StreamMaxAge)
	}

	if s.RecoverBy < 0 {
		add("RecoverBy", "must not be negative, got %d", s.RecoverBy)
	}
	if s.RecoverBy > s.DeadLetterDelivery() {
		add("RecoverBy", "%d exceeds the ladder's %d deliveries: recovery is expected after the ladder has already given up", s.RecoverBy, s.DeadLetterDelivery())
	}
	if s.FloorAge > 0 {
		// The ladder and the breaker threshold are one schedule: if the wait
		// to the expected recovery reaches the threshold, the breaker can
		// quarantine a transient that was still going to succeed.
		if s.RecoverBy > 0 && s.RecoverBy <= s.DeadLetterDelivery() {
			if cum := s.CumulativeTo(s.RecoverBy); cum >= s.FloorAge {
				add("RecoverBy", "the ladder reaches delivery %d after %s, at or past FloorAge (%s): a transient still inside its recovery window could be dead-lettered — shorten the ladder, lower RecoverBy, or raise FloorAge", s.RecoverBy, cum, s.FloorAge)
			}
		}
		// A threshold the ladder never reaches is a breaker that can never
		// fire — configured, named in every doc and dashboard, and inert. The
		// ENT-1535 disease in miniature, so it is a violation rather than a
		// quiet no-op. The breaker's last chance is the dead-letter delivery
		// itself, since Settle weighs quarantine before exhaustion.
		//
		// Note the weaker case this does NOT reject: a threshold above
		// CumulativeTo(DeadLetterDelivery-1) leaves the breaker able to fire
		// only on the very delivery exhaustion would have handled anyway, so
		// it accelerates nothing. That is a judgement about whether the
		// breaker earns its keep on a given ladder, not a broken config, and
		// on a tight bounded ladder it is the normal outcome.
		if ttl := s.TimeToDeadLetter(); ttl > 0 && s.FloorAge > ttl {
			add("FloorAge", "%s is longer than the %s this ladder takes to dead-letter a message: the breaker could never fire — shorten FloorAge, lengthen the ladder, or drop the monitor",
				s.FloorAge, ttl)
		}
		// A breaker only ever fires on a delivery, so a rung longer than the
		// threshold leaves the floor pinned for that rung after it arms.
		if rung := s.LongestRung(); rung > s.FloorAge {
			add("FloorAge", "the largest ladder rung (%s) exceeds FloorAge (%s): the breaker acts on a delivery, so the floor would stay pinned for up to FloorAge+%s", rung, s.FloorAge, rung)
		}
	}
	return vs
}

// Err folds Validate's result into a single error, or nil when the schedule is
// coherent — the form [NewRetry] and a bind-time check want, where fleet CI
// wants the individual violations.
func (s Schedule) Err() error {
	vs := s.Validate()
	if len(vs) == 0 {
		return nil
	}
	parts := make([]string, 0, len(vs))
	for _, v := range vs {
		parts = append(parts, v.String())
	}
	return fmt.Errorf("jsconsumer: incoherent retry schedule: %s", strings.Join(parts, "; "))
}

