// runs — the consumers aren't started and their setup isn't built — leaving
// just the cross-region lifecycle fan below. cons + the done channels stay
// declared at function scope so the readiness gate and shutdown drain can
// see them (nil, and skipped, in lifecycle-only mode).
var (
	cons           *fanoutengine.Consumer
	consumerDone   chan struct{}
	backfillDone   chan struct{}
	prBackfillDone chan struct{}
)
if !lifecycleOnly {
	durable := os.Getenv("META_FANOUT_DURABLE")
	if durable == "" {
		durable = defaultDurable
	}

	metaRes := newMetaResolver(resolver)

	cons = newConsumer(js, metaRes, regions, metrics, durable, webhookevents.SubjectPrefix+">")
	consumerDone = make(chan struct{})
	go func() {
		defer close(consumerDone)
		cons.Run(ctx)
	}()
	slog.Info("Consumer started",
		slog.String("durable", durable),
		slog.String("subject", webhookevents.SubjectPrefix+">"),
	)

	// Backfill consumer: a SEPARATE durable on the dedicated, US-only
	// github_meta_backfill work-queue stream, with its own per-replica
	// GitHub-API throttle (META_FANOUT_BACKFILL_GH_RPS; the effective regional
	// rate is that value times the replica count), so a one-shot region-wide
