// release gate for the Track D loop ports, and it is the gap go-nuts closed for
// itself with internal/brokersemantics after every P1 in the A1 review cycle
// turned out to be a model error rather than a coding one.
//
// The division of labour is the same one go-nuts settled on:
//
//   - the existing fakes — disposition bookkeeping: given this input, did the
//     handler call Ack, or Nak with this delay? Cheap, exhaustive, no broker.
//   - this harness — what the BROKER does: fetch-timeout classification, batch
//     delivery, redelivery timing, ack-floor movement, InProgress extension,
//     drain-during-shutdown, and what CreateOrUpdateConsumer actually stores on
//     a durable that already exists.
//
// A migrated loop needs both, and it needs them in that order: characterise the
// legacy loop against a real broker FIRST (LegacyJetStream below exists for
// exactly that), then assert the migrated loop reproduces it. A before/after
// pair measured through the same harness is the evidence a migration trail
// carries; two assertions written against two different fakes are not.
//
// # No build tag, deliberately
//
// This runs in the default `go test ./...`, so it gates every merge. A tag CI
// forgets to pass is a gate that silently does not run — the same failure shape
// as the fakes it exists to backstop.
//
// # Test-only, and it must stay that way
//
// Importing this package links an entire nats-server into the binary. Nothing
// under cmd/ or pkg/ may import it outside _test.go files; TestNoProductionImport
// in this package's own test enforces that rather than trusting review.
//
// # On a nats-server bump
//
// The semantics measured through this harness are version-specific. When a test
// built on it goes red after a bump, the BELIEF stated in the doc comment that
// test cites is what needs re-deciding — not the test. Version returns the
// linked server's version so a failure can say which one produced it.
package natstest

import (
	"sync"
	"testing"
	"time"

	natsserver "github.com/nats-io/nats-server/v2/server"
	"github.com/nats-io/nats.go"
	"github.com/nats-io/nats.go/jetstream"
)

// readyTimeout bounds how long Server waits for the embedded broker to accept
// connections. Generous: a loaded CI box starting JetStream with a fresh store
// directory is slower than a laptop, and a flaky harness would be worse than a
// slow one.
const readyTimeout = 10 * time.Second

// Version is the linked nats-server's version — the one every measurement taken
// through this harness is attributable to. Print it when a broker-semantic test
// fails, so the failure names the version that produced it.
func Version() string { return natsserver.VERSION }

// Server boots an in-process JetStream nats-server on a random loopback port and
// shuts it down when the test ends. opts may adjust the options — accounts,
// permissions, limits — before start.
//
// The permissions hook is not decoration: an ack whose $JS.ACK publish is denied
// returns no error at all and leaves the floor pinned with nothing logged, which
// is how five consumers shipped without their grant (COR-1224). A loop test that
// wants to reproduce that shape configures it here.
func Server(t *testing.T, opts ...func(*natsserver.Options)) *natsserver.Server {
	t.Helper()
	o := &natsserver.Options{
		Host:      "127.0.0.1",
		Port:      -1, // let the OS pick a free port, so parallel tests don't collide
		NoLog:     true,
		NoSigs:    true,
		JetStream: true,
		StoreDir:  t.TempDir(),
	}
	for _, fn := range opts {
		fn(o)
	}
	s, err := natsserver.NewServer(o)
	if err != nil {
		t.Fatalf("natstest: new embedded nats-server: %v", err)
	}
	go s.Start()
	if !s.ReadyForConnections(readyTimeout) {
		t.Fatalf("natstest: embedded nats-server not ready within %s", readyTimeout)
	}
	t.Cleanup(s.Shutdown)
	return s
}

// Connect dials s and closes the connection when the test ends. Async errors are
// collected rather than written to stderr, and returned by the drain func: a
// permissions violation on $JS.ACK arrives ONLY on the async handler, so a test
// that never reads them cannot tell a denied ack from a successful one.
func Connect(t *testing.T, s *natsserver.Server, opts ...nats.Option) (nc *nats.Conn, asyncErrs func() []error) {
	t.Helper()
	var mu sync.Mutex
	var errs []error
	opts = append(opts, nats.ErrorHandler(func(_ *nats.Conn, _ *nats.Subscription, err error) {
		mu.Lock()
		errs = append(errs, err)
		mu.Unlock()
	}))
	conn, err := nats.Connect(s.ClientURL(), opts...)
	if err != nil {
		t.Fatalf("natstest: connect: %v", err)
	}
	t.Cleanup(conn.Close)
	return conn, func() []error {
		mu.Lock()
		defer mu.Unlock()
		return append([]error(nil), errs...)
	}
}

// JetStream returns the modern jetstream handle — what a migrated loop and
// jsconsumer use.
func JetStream(t *testing.T, nc *nats.Conn) jetstream.JetStream {
	t.Helper()
	js, err := jetstream.New(nc)
	if err != nil {
		t.Fatalf("natstest: jetstream.New: %v", err)
	}
	return js
}

// LegacyJetStream returns the legacy nats.JetStreamContext handle — what every
// mirror-pipeline loop uses today.
//
// It exists so a migration can be measured rather than asserted: run the legacy
// loop through this handle, record what the broker did, then run the migrated
// loop through JetStream above and compare. Once a loop has moved, its tests
// should stop using this; when the last loop has moved, this func goes with it.
func LegacyJetStream(t *testing.T, nc *nats.Conn) nats.JetStreamContext {
	t.Helper()
	js, err := nc.JetStream()
	if err != nil {
		t.Fatalf("natstest: nc.JetStream: %v", err)
	}
	return js
}

// Stream creates a stream, failing the test if it cannot.
//
// Pass the real retention and max-age of the stream under test, not defaults.
// Retention is load-bearing for every give-up decision in Track D — a work-queue
// removes on Ack or Term, an interest stream removes when the last interested
// durable settles, and a limits stream removes on nothing but its own clock — so
// a fixture that leaves it at the zero value measures a different loop than the
// one that ships.
func Stream(t *testing.T, js jetstream.JetStream, cfg jetstream.StreamConfig) jetstream.Stream {
	t.Helper()
	st, err := js.CreateStream(t.Context(), cfg)
	if err != nil {
		t.Fatalf("natstest: create stream %s: %v", cfg.Name, err)
	}
	return st
}

// Consumer creates or updates a durable, failing the test if it cannot.
//
// CreateOrUpdateConsumer is itself under test in this migration: it sends every
// field, so a zero MaxAckPending resets a live durable to the server default and
// an immutable-field disagreement is rejected outright. A test that wants to pin
// either shape drives it through here and reads the result back with Info.
func Consumer(t *testing.T, js jetstream.JetStream, stream string, cfg jetstream.ConsumerConfig) jetstream.Consumer {
	t.Helper()
	cons, err := js.CreateOrUpdateConsumer(t.Context(), stream, cfg)
	if err != nil {
		t.Fatalf("natstest: create consumer %s/%s: %v", stream, cfg.Durable, err)
	}
	return cons
}

// Info reads a consumer's live info — its STORED config and its ack floor.
// What the server holds, not what the request asked for; those differ, which is
// the point.
func Info(t *testing.T, cons jetstream.Consumer) *jetstream.ConsumerInfo {
	t.Helper()
	ci, err := cons.Info(t.Context())
	if err != nil {
		t.Fatalf("natstest: consumer info: %v", err)
	}
	return ci
}

// Publish publishes each payload to subject and waits for the pub-ack.
func Publish(t *testing.T, js jetstream.JetStream, subject string, payloads ...string) {
	t.Helper()
	for i, p := range payloads {
		if _, err := js.Publish(t.Context(), subject, []byte(p)); err != nil {
			t.Fatalf("natstest: publish %s [%d]: %v", subject, i, err)
		}
	}
}

// Env is the common setup: an embedded server, a connection, a modern JetStream
// handle, and the stream described by cfg. Use the individual funcs above when a
// test needs the server options, the async errors, or the legacy handle.
func Env(t *testing.T, cfg jetstream.StreamConfig) (*nats.Conn, jetstream.JetStream) {
	t.Helper()
	nc, _ := Connect(t, Server(t))
	js := JetStream(t, nc)
	Stream(t, js, cfg)
	return nc, js
}

