package timingcontract_test

import (
	"strings"
	"testing"
	"time"

	"github.com/entireio/go-nuts/jsconsumer"

	"github.com/entirehq/mirror-pipeline/internal/timingcontract"
)

// TestValidateRejectsMixedOwnership pins the ENT-1535 defect detector: a
// client-side NakDelay AND a server-side BackOff on one consumer. The server
// stretches each NAK delay by the BackOff increments, so redeliveries follow
// neither ladder while the configured one still reads as authoritative.
//
// This is the check every Track D migration has to keep passing, because the
// migration's whole shape — some loops keep a client ladder, some move to a
// server one — is one edit away from producing exactly this.
func TestValidateRejectsMixedOwnership(t *testing.T) {
	t.Parallel()
	c := timingcontract.Contract{
		Name: "mixed",
		Schedule: jsconsumer.Schedule{
			NakDelay:      30 * time.Second,
			ServerBackOff: []time.Duration{30 * time.Second, 60 * time.Second},
			MaxDeliver:    8,
			AckWait:       30 * time.Second,
		},
	}
	err := c.Validate()
	if err == nil {
		t.Fatal("a client NakDelay alongside a server BackOff validated clean; the ENT-1535 detector is not running")
	}
	if !strings.Contains(err.Error(), "mixed") {
		t.Errorf("violation does not name the contract: %v", err)
	}
}

// TestValidateRejectsAckWaitDisagreeingWithFirstRung pins the other arithmetic
// trap the adoption guidance calls out: with a ladder set, the server stores
// BackOff[0] in place of the declared AckWait, so a mismatch is config that never
// runs — and a pedantic-mode create rejects it outright rather than rewriting it.
//
// natstest.REDACTED measures the same fact
// against a real broker; this asserts the library catches it before a consumer
// ever starts.
func TestValidateRejectsAckWaitDisagreeingWithFirstRung(t *testing.T) {
	t.Parallel()
	c := timingcontract.Contract{
		Name: "skewed",
		Schedule: jsconsumer.Schedule{
			ServerBackOff: []time.Duration{30 * time.Second},
			MaxDeliver:    8,
			AckWait:       31 * time.Second, // one second off, and therefore dead config
		},
	}
	if err := c.Validate(); err == nil {
		t.Fatal("AckWait disagreeing with ServerBackOff[0] validated clean")
	}
}

// TestClientScheduledFlatLadderIsCoherent pins that a SINGLE-owner client ladder
// — no server BackOff — is a valid configuration, not a violation.
//
// This is the shape cmd/worker keeps (COR-1254 records it as a class rule: a
// consumer whose handler time vastly exceeds its desired first rung cannot use a
// server ladder, because AckWait is normalized to BackOff[0]). The distinction
// that makes it legal is ownership, not mechanism: ENT-1535 was MIXED ownership,
// which TestValidateRejectsMixedOwnership above still rejects.
//
// The AckWait here is 15m against a 30s rung deliberately: under a server ladder
// that pair is a violation, and this case would fail if the check stopped
// distinguishing who owns the schedule.
func TestClientScheduledFlatLadderIsCoherent(t *testing.T) {
	t.Parallel()
	c := timingcontract.Contract{
		Name: "mirror-git-v1-<jur>-<cluster>",
		Schedule: jsconsumer.Schedule{
			NakDelay:     30 * time.Second,
			MaxDeliver:   10,
			AckWait:      15 * time.Minute,
			StreamMaxAge: 6 * time.Hour,
		},
	}
	if err := c.Validate(); err != nil {
		t.Fatalf("single-owner client ladder rejected: %v", err)
	}
	if err := c.CheckEnvelope(timingcontract.Envelope{
		DeadLetterDelivery: 10,
		TimeToDeadLetter:   4*time.Minute + 30*time.Second, // 9 redeliveries x 30s
		LongestRung:        30 * time.Second,
	}); err != nil {
		t.Error(err)
	}
}

// TestValidateRejectsALadderOutlivingRetention pins the loss class ENT-1492 is
// about: a ladder that takes longer than the stream keeps the message never
// reaches its own terminal branch, because the stream discards it first.
//
// Kept here rather than left to go-nuts because it is the check most likely to
// start mattering during this migration: three of the four loops sit on streams
// whose max age a fleet overlay can shorten per cell.
func TestValidateRejectsALadderOutlivingRetention(t *testing.T) {
	t.Parallel()
	c := timingcontract.Contract{
		Name: "outlives-retention",
		Schedule: jsconsumer.Schedule{
			ServerBackOff: []time.Duration{time.Hour},
			MaxDeliver:    8,
			AckWait:       time.Hour,
			StreamMaxAge:  2 * time.Hour, // 7 x 1h of ladder against 2h of retention
		},
	}
	if err := c.Validate(); err == nil {
		t.Fatal("a ladder outliving the stream's retention validated clean")
	}
}

// TestMarkdownRendersTheBeforeAfterComparison exercises the renderer on the exact
// shape loop 2 (webhook-forwarder) will carry, so the table format is proven
// before a trail depends on it: a flat client ladder today, a server-owned ladder
// with one capture reserve after, with the give-up delivery and its timing
// preserved byte-for-byte.
func TestMarkdownRendersTheBeforeAfterComparison(t *testing.T) {
	t.Parallel()
	before := timingcontract.Contract{
		Name: "before (client Nak)",
		Schedule: jsconsumer.Schedule{
			NakDelay:   30 * time.Second,
			MaxDeliver: 8,
			AckWait:    30 * time.Second,
		},
	}
	after := timingcontract.Contract{
		Name: "after (server ladder)",
		Schedule: jsconsumer.Schedule{
			ServerBackOff:  flat(30*time.Second, 8),
			MaxDeliver:     9,
			AckWait:        30 * time.Second,
			CaptureReserve: 1,
		},
	}
	for _, c := range []timingcontract.Contract{before, after} {
		if err := c.Validate(); err != nil {
			t.Fatalf("%s: %v", c.Name, err)
		}
	}

	// The property the migration promises: same give-up delivery, same wait.
	wantEnvelope := timingcontract.Envelope{
		DeadLetterDelivery: 8,
		TimeToDeadLetter:   3*time.Minute + 30*time.Second,
		LongestRung:        30 * time.Second,
	}
	for _, c := range []timingcontract.Contract{before, after} {
		if err := c.CheckEnvelope(wantEnvelope); err != nil {
			t.Error(err)
		}
	}

	out := timingcontract.Markdown(before, after)
	t.Logf("rendered timing contract:\n%s", out)

	for _, want := range []string{
		"| delivery |",
		"before (client Nak)",
		"after (server ladder)",
		"t+3m30s — give up",
		"t+4m0s — capture reserve",
	} {
		if !strings.Contains(out, want) {
			t.Errorf("rendered table is missing %q:\n%s", want, out)
		}
	}
	// The before contract stops at 8 deliveries; its 9th cell must be blank
	// rather than a zero that would read as an instant retry.
	lines := strings.Split(out, "\n")
	var ninth string
	for _, l := range lines {
		if strings.HasPrefix(l, "| 9 |") {
			ninth = l
		}
	}
	if ninth == "" {
		t.Fatalf("no row for delivery 9:\n%s", out)
	}
	if strings.Contains(ninth, "t+") && strings.Count(ninth, "t+") != 1 {
		t.Errorf("delivery 9 should have a timing only for the after contract, got: %s", ninth)
	}
}

// TestMarkdownHandlesUnlimitedRedeliveries pins that an unbounded consumer
// renders a note rather than a table: it has no terminal branch, so any row count
// would be invented.
func TestMarkdownHandlesUnlimitedRedeliveries(t *testing.T) {
	t.Parallel()
	out := timingcontract.Markdown(timingcontract.Contract{
		Name:     "unbounded",
		Schedule: jsconsumer.Schedule{NakDelay: time.Second, MaxDeliver: jsconsumer.UnlimitedMaxDeliver},
	})
	if strings.Contains(out, "| delivery |") {
		t.Errorf("unlimited consumer rendered a delivery table:\n%s", out)
	}
	if !strings.Contains(out, "unlimited redeliveries") {
		t.Errorf("unlimited consumer did not render its note:\n%s", out)
	}
}

// flat builds an n-rung ladder of equal delays. JetStream repeats the last rung
// once the array runs out, so a shorter list would behave identically — the rungs
// are written out so len(BackOff) is one of the three MaxDeliver numbers a
// reviewer can check against the other two.
func flat(d time.Duration, n int) []time.Duration {
	out := make([]time.Duration, n)
	for i := range out {
		out[i] = d
	}
	return out
}

