// TestConnectChainsACallerSuppliedErrorHandler pins that a caller's own
// nats.ErrorHandler survives alongside the harness collector.
//
// Options are last-one-wins on Options.AsyncErrorCB, so before the chaining fix
// the collector silently replaced anything the caller passed. Both halves are
// asserted: dropping the chain fails on the caller's counter, and dropping the
// collector fails on asyncErrs.
//
// The trigger is a real permissions violation rather than a synthetic call,
// because that is the async error this harness exists to expose — the shape that
// let five consumers ship without their $JS.ACK grant (COR-1224), returning no
// error at the call site and arriving only here.
func TestConnectChainsACallerSuppliedErrorHandler(t *testing.T) {
	t.Parallel()
	s := natstest.Server(t, func(o *natsserver.Options) {
		o.Users = []*natsserver.User{{
			Username: "app",
			Password: "pw",
			Permissions: &natsserver.Permissions{
				Publish:   &natsserver.SubjectPermission{Allow: []string{"allowed.>"}},
				Subscribe: &natsserver.SubjectPermission{Allow: []string{">"}},
			},
		}}
	})

	var mu sync.Mutex
	callerSaw := 0
	nc, asyncErrs := natstest.Connect(t, s,
		nats.UserInfo("app", "pw"),
		nats.ErrorHandler(func(*nats.Conn, *nats.Subscription, error) {
			mu.Lock()
			callerSaw++
			mu.Unlock()
		}),
	)

	if err := nc.Publish("denied.subject", []byte("x")); err != nil {
		t.Fatalf("publish to a denied subject returned an error at the call site: %v", err)
	}
	if err := nc.Flush(); err != nil {
		t.Fatalf("flush: %v", err)
	}

	deadline := time.Now().Add(5 * time.Second)
	for {
		mu.Lock()
		seen := callerSaw
		mu.Unlock()
		if len(asyncErrs()) > 0 && seen > 0 {
			return // both handlers ran
		}
		if time.Now().After(deadline) {
			mu.Lock()
			seen = callerSaw
			mu.Unlock()
			if len(asyncErrs()) == 0 {
				t.Error("the harness collector recorded no async error for a denied publish")
			}
			if seen == 0 {
				t.Error("the caller-supplied nats.ErrorHandler was discarded rather than chained")
			}
			return
		}
		time.Sleep(20 * time.Millisecond)
	}
}

