// lifecycleBody is an opaque resource_lifecycle_v1 payload. meta-fanout never
// parses it — these tests assert it crosses the fan byte-for-byte — so its
// shape is deliberately arbitrary.
const lifecycleBody = `{"account_ulid":"01ARZ3NDEKTSV4RRFFQ69G5FAV","github_id":583231,"github_login":"octocat"}`

const lifecycleTestSubject = "resource_lifecycle_v1.github_handle.created"

// lifecycleTestLocalCluster is the cell id the test fanout stamps onto fanned
// copies (lifecycleFannedByHeader), so tests can assert the marker value.
const lifecycleTestLocalCluster = "us"

func fanoutForTest(remotes map[string]metajobs.JetStreamPublisher) *lifecycleConsumer {
	return &lifecycleConsumer{
		fanout:  &lifecycleFanout{remotes: remotes, localClusterID: lifecycleTestLocalCluster},
		durable: "test",
		subject: lifecycleSubjectFilter,
	}
}

// fannedInHeader builds a source header that already carries the fanned-by
// marker — i.e. a cross-region copy this cell imported. The msg-id is preserved
// so the header otherwise looks like a normal event.
func fannedInHeader(id, fannedBy string) nats.Header {
	h := msgIDHeader(id)
	h.Set(lifecycleFannedByHeader, fannedBy)
	return h
}

func driveLifecycle(t *testing.T, c *lifecycleConsumer, subject string, data []byte, header nats.Header, msg *fakeMsg) {
	t.Helper()
	ctx, span := otel.Tracer("meta-fanout-test").Start(context.Background(), "test.lifecycle", trace.WithSpanKind(trace.SpanKindConsumer))
	defer span.End()
	c.dispatch(ctx, span, subject, data, header, msg)
}

func msgIDHeader(id string) nats.Header {
	h := nats.Header{}
	h.Set(metajobs.NatsMsgIDHeader, id)
