// called, so tests can pin redelivery behavior without a real JetStream.
type fakeMsg struct {
	acked        int
	naked        int
	termed       int
	nakDelay     time.Duration
	numDelivered uint64
	streamSeq    uint64
}

func (m *fakeMsg) Ack(_ ...nats.AckOpt) error { m.acked++; return nil }
func (m *fakeMsg) Nak(_ ...nats.AckOpt) error { m.naked++; return nil }
func (m *fakeMsg) NakWithDelay(d time.Duration, _ ...nats.AckOpt) error {
	m.naked++
	m.nakDelay = d
	return nil
}
func (m *fakeMsg) Term(_ ...nats.AckOpt) error { m.termed++; return nil }
func (m *fakeMsg) Metadata() (*nats.MsgMetadata, error) {
	return &nats.MsgMetadata{
		NumDelivered: m.numDelivered,
		Sequence:     nats.SequencePair{Stream: m.streamSeq},
	}, nil
}

