// TestLifecycle_PartialRegionFailure_Naks: one unreachable region must not stop
// the others, and the delivery Naks (on the flat delay) so the whole event
// rides redelivery to the failed region.
func TestLifecycle_PartialRegionFailure_Naks(t *testing.T) {
	healthy := &recordingJS{}
	broken := &recordingJS{err: errors.New("region down")}
	c := fanoutForTest(map[string]metajobs.JetStreamPublisher{"eu": healthy, "au": broken})

	msg := &natsmsgtest.FakeMsg{}
	driveLifecycle(t, c, lifecycleTestSubject, []byte(lifecycleBody), msgIDHeader("evt-1"), msg)

	if msg.naked != 1 || msg.acked != 0 || msg.termed != 0 {
		t.Fatalf("partial failure must Nak; got ack=%v nak=%d term=%v", msg.Acked, nakCount(msg), msg.Termed)
	}
	if msg.nakDelay != consumerFailureDelay {
		t.Errorf("transient nak must use the flat delay; got %v want %v", msg.nakDelay, consumerFailureDelay)
	}
	if healthy.count() != 1 {
		t.Errorf("healthy region got %d publishes, want 1 (a failed peer must not starve it)", healthy.count())
	}
}

// TestLifecycle_MsgIDFallsBackToStreamSeq: with no Nats-Msg-Id on the source,
// the fan derives a stable dedup id from the source stream + sequence.
func TestLifecycle_MsgIDFallsBackToStreamSeq(t *testing.T) {
	eu := &recordingJS{}
	c := fanoutForTest(map[string]metajobs.JetStreamPublisher{"eu": eu})

	msg := &fakeMsg{streamSeq: 4242}
	driveLifecycle(t, c, lifecycleTestSubject, []byte(lifecycleBody), nats.Header{}, msg)

	if eu.count() != 1 {
		t.Fatalf("eu got %d publishes, want 1", eu.count())
	}
	want := lifecycleStream + ":4242"
	if got := eu.msgs[0].Header.Get(metajobs.NatsMsgIDHeader); got != want {
		t.Errorf("derived Nats-Msg-Id = %q, want %q", got, want)
	}
}

// TestLifecycleMsgID pins the dedup-id precedence: source header wins, else the
// stream+sequence fallback.
func TestLifecycleMsgID(t *testing.T) {
	if got := lifecycleMsgID(msgIDHeader("from-header"), &fakeMsg{streamSeq: 9}); got != "from-header" {
		t.Errorf("with a source Nats-Msg-Id, msgID = %q, want from-header", got)
	}
	if got := lifecycleMsgID(nats.Header{}, &fakeMsg{streamSeq: 9}); got != lifecycleStream+":9" {
		t.Errorf("without a source id, msgID = %q, want %s:9", got, lifecycleStream)
	}
}

