package main

import (
	"bytes"
	"context"
	"errors"
	"testing"

	"github.com/nats-io/nats.go"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/trace"

	"github.com/entirehq/mirror-pipeline/internal/mirrorjobs"
	"github.com/entirehq/mirror-pipeline/pkg/metajobs"
)

// lifecycleBody is an opaque resource_lifecycle_v1 payload. meta-fanout never
// parses it — these tests assert it crosses the fan byte-for-byte — so its
// shape is deliberately arbitrary.
const lifecycleBody = `{"account_ulid":"01ARZ3NDEKTSV4RRFFQ69G5FAV","github_id":583231,"github_login":"octocat"}`

const lifecycleTestSubject = "resource_lifecycle_v1.github_handle.created"

// lifecycleTestLocalCluster is the cell id the test fanout stamps onto fanned
// copies (lifecycleFannedByHeader), so tests can assert the marker value.
const lifecycleTestLocalCluster = "us"

func fanoutForTest(remotes map[string]metajobs.JetStreamPublisher) *lifecycleConsumer {
	return &lifecycleConsumer{
		fanout:  &lifecycleFanout{remotes: remotes, localClusterID: lifecycleTestLocalCluster},
		durable: "test",
		subject: lifecycleSubjectFilter,
	}
}

// fannedInHeader builds a source header that already carries the fanned-by
// marker — i.e. a cross-region copy this cell imported. The msg-id is preserved
// so the header otherwise looks like a normal event.
func fannedInHeader(id, fannedBy string) nats.Header {
	h := msgIDHeader(id)
	h.Set(lifecycleFannedByHeader, fannedBy)
	return h
}

func driveLifecycle(t *testing.T, c *lifecycleConsumer, subject string, data []byte, header nats.Header, msg *natsmsgtest.FakeMsg) {
	t.Helper()
	ctx, span := otel.Tracer("meta-fanout-test").Start(context.Background(), "test.lifecycle", trace.WithSpanKind(trace.SpanKindConsumer))
	defer span.End()
	c.dispatch(ctx, span, subject, data, header, msg)
}

func msgIDHeader(id string) nats.Header {
	h := nats.Header{}
	h.Set(metajobs.NatsMsgIDHeader, id)
	return h
}

// TestLifecycle_FansToAllRemotes confirms every remote region's stream receives
// the event with the source subject, payload, and dedup id preserved verbatim,
// and the delivery Acks.
func TestLifecycle_FansToAllRemotes(t *testing.T) {
	eu := &recordingJS{}
	au := &recordingJS{}
	c := fanoutForTest(map[string]metajobs.JetStreamPublisher{"eu": eu, "au": au})

	msg := &natsmsgtest.FakeMsg{}
	driveLifecycle(t, c, lifecycleTestSubject, []byte(lifecycleBody), msgIDHeader("evt-1"), msg)

	if !msg.Acked || nakCount(msg) != 0 || msg.Termed {
		t.Fatalf("clean fan must Ack; got ack=%v nak=%d term=%v", msg.Acked, nakCount(msg), msg.Termed)
	}
	for name, js := range map[string]*recordingJS{"eu": eu, "au": au} {
		if js.count() != 1 {
			t.Fatalf("region %s got %d publishes, want 1", name, js.count())
		}
		got := js.msgs[0]
		if got.Subject != lifecycleTestSubject {
			t.Errorf("region %s subject = %q, want %q (preserved verbatim)", name, got.Subject, lifecycleTestSubject)
		}
		if !bytes.Equal(got.Data, []byte(lifecycleBody)) {
			t.Errorf("region %s payload mutated:\n got %s\nwant %s", name, got.Data, lifecycleBody)
		}
		if id := got.Header.Get(metajobs.NatsMsgIDHeader); id != "evt-1" {
			t.Errorf("region %s Nats-Msg-Id = %q, want the source id evt-1 (cross-region dedup)", name, id)
		}
		// Every fanned copy is stamped with this cell's id so the destination
		// cell won't re-export it (one-generation fan, COR-902).
		if fb := got.Header.Get(lifecycleFannedByHeader); fb != lifecycleTestLocalCluster {
			t.Errorf("region %s %s = %q, want %q (fanned-copy marker)", name, lifecycleFannedByHeader, fb, lifecycleTestLocalCluster)
		}
	}
}

// TestLifecycle_MarkedMessage_SkippedNotRefanned is the core COR-902 fix: an
// event that already carries the fanned-by marker (a cross-region copy this
// cell imported) is ack'd WITHOUT being re-fanned, so the fan is exactly one
// generation deep and an echo loop is structurally impossible.
func TestLifecycle_MarkedMessage_SkippedNotRefanned(t *testing.T) {
	eu := &recordingJS{}
	au := &recordingJS{}
	c := fanoutForTest(map[string]metajobs.JetStreamPublisher{"eu": eu, "au": au})

	msg := &natsmsgtest.FakeMsg{}
	driveLifecycle(t, c, lifecycleTestSubject, []byte(lifecycleBody), fannedInHeader("evt-1", "eu"), msg)

	if !msg.Acked || nakCount(msg) != 0 || msg.Termed {
		t.Fatalf("a marked (fanned-in) message must Ack; got ack=%v nak=%d term=%v", msg.Acked, nakCount(msg), msg.Termed)
	}
	if eu.count() != 0 || au.count() != 0 {
		t.Errorf("a marked message must NOT be re-fanned; eu=%d au=%d publishes, want 0/0", eu.count(), au.count())
	}
}

// TestLifecycle_MarkedMirrorCreated_SeedsButDoesNotRefan pins the COR-717
// preservation: a mirror.created for a foreign-origin mirror reaches US only as
// a fanned copy, and US is where the github_meta seed runs — so the seed MUST
// still fire for a marked message even though the fan is skipped.
func TestLifecycle_MarkedMirrorCreated_SeedsButDoesNotRefan(t *testing.T) {
	eu := &recordingJS{}
	enq := &fakeEnqueuer{}
	res := &fakeMirrorResolver{up: mirrorjobs.MirrorUpstream{Provider: "github", Owner: "octocat", Repo: "hello-world"}}
	c := seedingConsumerForTest(map[string]metajobs.JetStreamPublisher{"eu": eu}, enq, res)

	msg := &natsmsgtest.FakeMsg{}
	driveLifecycle(t, c, mirrorCreatedSubject, mirrorCreatedBody("01HMIRROR"), fannedInHeader("evt-1", "eu"), msg)

	if !msg.Acked || nakCount(msg) != 0 {
		t.Fatalf("a marked mirror.created must Ack; got ack=%v nak=%d", msg.Acked, nakCount(msg))
	}
	if eu.count() != 0 {
		t.Errorf("a marked message must NOT be re-fanned; eu got %d publishes, want 0", eu.count())
	}
	// The seed hook still ran: the new mirror's metadata is backfilled even
	// though the event arrived as an import.
	if res.calls != 1 || len(enq.jobs) != 1 {
		t.Errorf("seed must still run for a marked mirror.created; resolver calls=%d jobs=%d, want 1/1", res.calls, len(enq.jobs))
	}
}

// TestLifecycle_NoRemotes_Acks: single-region mode (no remotes) is a benign
// no-op — nothing to fan, so the delivery Acks.
func TestLifecycle_NoRemotes_Acks(t *testing.T) {
	c := fanoutForTest(map[string]metajobs.JetStreamPublisher{})
	msg := &natsmsgtest.FakeMsg{}
	driveLifecycle(t, c, lifecycleTestSubject, []byte(lifecycleBody), msgIDHeader("evt-1"), msg)
	if !msg.Acked || nakCount(msg) != 0 {
		t.Errorf("no-remotes fan must Ack; got ack=%v nak=%d", msg.Acked, nakCount(msg))
	}
}

// TestLifecycle_PartialRegionFailure_Naks: one unreachable region must not stop
// the others, and the delivery Naks (on the flat delay) so the whole event
// rides redelivery to the failed region.
func TestLifecycle_PartialRegionFailure_Naks(t *testing.T) {
	healthy := &recordingJS{}
	broken := &recordingJS{err: errors.New("region down")}
	c := fanoutForTest(map[string]metajobs.JetStreamPublisher{"eu": healthy, "au": broken})

	msg := &natsmsgtest.FakeMsg{}
	driveLifecycle(t, c, lifecycleTestSubject, []byte(lifecycleBody), msgIDHeader("evt-1"), msg)

	if msg.naked != 1 || msg.acked != 0 || msg.termed != 0 {
		t.Fatalf("partial failure must Nak; got ack=%v nak=%d term=%v", msg.Acked, nakCount(msg), msg.Termed)
	}
	if msg.nakDelay != consumerFailureDelay {
		t.Errorf("transient nak must use the flat delay; got %v want %v", msg.nakDelay, consumerFailureDelay)
	}
	if healthy.count() != 1 {
		t.Errorf("healthy region got %d publishes, want 1 (a failed peer must not starve it)", healthy.count())
	}
}

// TestLifecycle_MsgIDFallsBackToStreamSeq: with no Nats-Msg-Id on the source,
// the fan derives a stable dedup id from the source stream + sequence.
func TestLifecycle_MsgIDFallsBackToStreamSeq(t *testing.T) {
	eu := &recordingJS{}
	c := fanoutForTest(map[string]metajobs.JetStreamPublisher{"eu": eu})

	msg := &fakeMsg{streamSeq: 4242}
	driveLifecycle(t, c, lifecycleTestSubject, []byte(lifecycleBody), nats.Header{}, msg)

	if eu.count() != 1 {
		t.Fatalf("eu got %d publishes, want 1", eu.count())
	}
	want := lifecycleStream + ":4242"
	if got := eu.msgs[0].Header.Get(metajobs.NatsMsgIDHeader); got != want {
		t.Errorf("derived Nats-Msg-Id = %q, want %q", got, want)
	}
}

// TestLifecycleMsgID pins the dedup-id precedence: source header wins, else the
// stream+sequence fallback.
func TestLifecycleMsgID(t *testing.T) {
	if got := lifecycleMsgID(msgIDHeader("from-header"), &fakeMsg{streamSeq: 9}); got != "from-header" {
		t.Errorf("with a source Nats-Msg-Id, msgID = %q, want from-header", got)
	}
	if got := lifecycleMsgID(nats.Header{}, &fakeMsg{streamSeq: 9}); got != lifecycleStream+":9" {
		t.Errorf("without a source id, msgID = %q, want %s:9", got, lifecycleStream)
	}
}

// TestLifecycle_InjectsTraceWithoutMutatingSource: trace injection happens on a
// per-region copy, so the shared source header is never written to and regions
// don't leak trace context into one another.
func TestLifecycle_InjectsTraceWithoutMutatingSource(t *testing.T) {
	eu := &recordingJS{}
	c := fanoutForTest(map[string]metajobs.JetStreamPublisher{"eu": eu})

	src := msgIDHeader("evt-1")
	driveLifecycle(t, c, lifecycleTestSubject, []byte(lifecycleBody), src, &natsmsgtest.FakeMsg{})

	if _, leaked := src["traceparent"]; leaked {
		t.Error("trace context leaked into the shared source header")
	}
	if len(src) != 1 {
		t.Errorf("source header mutated: %v", src)
	}
}

// TestLifecycle_SubjectFilterIsWholeStream guards the dumb-pipe contract: the
// consumer binds the entire stream, leaving subtype filtering to downstream.
func TestLifecycle_SubjectFilterIsWholeStream(t *testing.T) {
	if lifecycleSubjectFilter != "resource_lifecycle_v1.>" {
		t.Errorf("subject filter = %q, want resource_lifecycle_v1.>", lifecycleSubjectFilter)
	}
}

