              {
                "text": "and",
                "type": "text",
                "marks": [
                  {
                    "type": "bold"
                  }
                ]
              },
              {
                "text": " a ",
                "type": "text"
              },
              {
                "text": "meta-fanout",
                "type": "text",
                "marks": [
                  {
                    "type": "code"
                  }
                ]
              },
              {
                "text": " publish grant, neither of which exists; out of scope by rule.",
                "type": "text"
