                "type": "text"
              },
              {
                "text": "jsconsumer.Run",
                "type": "text",
                "marks": [
                  {
                    "type": "code"
                  }
                ]
              },
              {
                "text": " exposes no start-success signal, so ",
                "type": "text"
              },
              {
                "text": "Ready()",
                "type": "text",
                "marks": [
                  {
                    "type": "code"
                  }
                ]
              },
              {
                "text": " now reports only that the configuration was accepted — which ",
                "type": "text"
