                "marks": [
                  {
                    "type": "code"
                  }
                ]
              },
              {
                "text": " is kept verbatim on the metric — dashboards key on it and its meaning is unchanged (this delivery failed and will come back). What changed is who schedules the redelivery, which the metric never described.",
                "type": "text"
              }
