              },
              {
                "type": "listItem",
                "content": [
                  {
                    "type": "paragraph",
                    "content": [
                      {
                        "text": "FanFailure_IsRedeliveredByTheServerLadder",
                        "type": "text",
                        "marks": [
                          {
                            "type": "bold"
                          },
                          {
                            "type": "code"
                          }
                        ]
                      },
                      {
                        "text": " — settle nothing, get the delivery back on the ladder. The fixture ladder is scaled to milliseconds and ",
                        "type": "text"
                      },
                      {
                        "text": "growing",
