// probeDurable keeps lifecycleConsumer.durableBound current until ctx is done. It
// probes immediately, then on a ticker, so a pod does not sit NotReady for a whole
// interval after a healthy start.
//
// The interval is slow on purpose: this is one CONSUMER.INFO per pod per interval
// against every cell's NATS, and /readyz is polled far more often than the answer
// changes — so the probe is cached rather than run per request.
func (c *lifecycleConsumer) probeDurable(ctx context.Context, cfg jsconsumer.Config) {
	js, err := jetstream.New(c.nc)
	if err != nil {
		// Nothing recoverable: jetstream.New only fails on a malformed connection,
		// which no later probe would fix. Leave durableBound false — NotReady is
		// the honest report — and let Run's own error path speak to the cause.
		slog.ErrorContext(ctx, "Lifecycle readiness probe could not build a JetStream handle; reporting NotReady",
			slog.Any("error", err))
		return
	}
	ticker := time.NewTicker(lifecycleReadyProbeInterval)
	defer ticker.Stop()
	for {
		c.durableBound.Store(c.durableReachable(ctx, js, cfg))
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
		}
	}
}

// durableReachable reports whether the durable answers on the server. A bounded
// timeout of its own, so a probe cannot hang past the interval and stall the
// readiness signal at a stale value.
func (c *lifecycleConsumer) durableReachable(ctx context.Context, js jetstream.JetStream, cfg jsconsumer.Config) bool {
	ctx, cancel := context.WithTimeout(ctx, lifecycleReadyProbeTimeout)
	defer cancel()
	if _, err := js.Consumer(ctx, cfg.Stream, cfg.Durable); err != nil {
		// Debug, not warn: during a rollout or a provisioning race this is the
		// expected transient, and Run already logs the same condition per attempt.
		// The signal an operator acts on is /readyz itself.
		slog.DebugContext(ctx, "Lifecycle readiness probe failed; reporting NotReady",
			slog.String("stream", cfg.Stream), slog.String("durable", cfg.Durable), slog.Any("error", err))
		return false
	}
	return true
}

// handle is the per-message entry point — the production callback and the seam
// tests drive, so the span prologue is exercised the same way in both.

