git checkout -b nodo/natstest-shutdown-before-ready-wait -q && python3 - <<'PY'
full = '''	// Register the shutdown BEFORE waiting on readiness, and keep it in that
	// order. A server that never reports ready is still running: still bound to
	// its port and still holding its JetStream store. Fataling first leaves it
	// there for the rest of the process — and because t.TempDir registered its own
	// cleanup earlier, cleanups run LIFO and the store directory is removed
	// underneath a live server rather than after it stopped. The consequence lands
	// as a flake in a LATER parallel test, which is the kind of failure that gets
	// blamed on anything but its cause.
'''
brief = '''	// Shutdown registered BEFORE the readiness wait, so a server that never
	// becomes ready is still torn down — see startServer in
	// internal/brokersemantics for why the order matters.
'''
targets = {
 'internal/brokersemantics/harness_test.go': (full, '\t\tt.Fatal("embedded nats server not ready in time")'),
 'jsconsumer/jsconsumer_test.go': (brief, None),
 'natsmsg/publish_test.go': (brief, None),
 'helpers_test.go': (brief, None),
}
for path, (comment, _) in targets.items():
    s = open(path).read()
    # move the cleanup above the readiness check
    import re
    pat = re.compile(
        r'(\tgo s\.Start\(\)\n)'
        r'(\tif !s\.ReadyForConnections\(10 \* time\.Second\) \{\n(?:.*\n)*?\t\}\n)'
        r'\tt\.Cleanup\(s\.Shutdown\)\n')
    new, n = pat.subn(lambda m: m.group(1) + comment + '\tt.Cleanup(s.Shutdown)\n' + m.group(2), s)
    assert n == 1, (path, n)
    open(path, 'w').write(new)
    print(path, 'fixed')
PY
grep -n -A3 "go s.Start()" internal/brokersemantics/harness_test.go | head -6
